INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22192805657', 'Blusa Básica Feminina Decote Redondo Em Algodão', 'Blusa feminina feita em malha de algodão. A blusa Baby Look é uma peça essencial no guarda-roupa feminino, pois ela pode compor diversos looks! Essa peça com caimento ajustado ao corpo, conta com decote redondo e mangas curtas. Além disso, ela foi feita em malha de algodão super elástica e leve, sendo confortável, respirável de toque macio e fácil manuseio, garantindo alta durabilidade e versatilidade no uso. É Uma peça atemporal e que pode ser usada de infinitas formas. Combine com calça mom jeans e tênis baixa, para um visual casual! Blusa Baby Look Decote Redondo Mangas Curtas Feita em Malha de Algodão Situação de Uso: Casual, Qualquer Ocasião e Dia a Dia', 59.9, 53.91, NULL, 'Women Clothes > Tops > Shirts & Blouses', 'https://cf.shopee.com.br/file/sg-11134201-7rbnl-lqkyuh2hepl3b7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939838662%2F22192805657', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19497501507', 'Bermuda Maculina BT Sports Masculina Proteção UV50+ Mormaii', 'BERMUDA MASCULINA BT SERIES MORMAII PRODUTO ORIGINAL À PRONTA ENTREGA A Linha BEACH SPORTS Mormaii foi desenvolvida especialmente para a prática dos esportes de praia. Tecidos leves,flexíveis. CARACTERISTICAS DO PRODUTO: Bermuda masculina, com cintura em elastano e cordão para ajuste. feito em tecido leve de secagem rápida, ideal para a prática esportiva Material: 93% Poliester 7% Elastano Proteção: uv50+ MORMAII: A história da Mormaii começa nas belas praias da região sul do litoral brasileiro no início dos anos 70, fundada pelo então médico e surfista Morongo. Surge, assim, uma marca com raízes no surfe, mas com um objetivo maior: a busca pela qualidade de vida. Atualmente, a marca é reconhecida por mais de uma centena de produtos que atendem as categorias Surf, Mergulho, Skate, Fitness, Moda Praia, Bicicletas, além de produtos como óculos, relógios e chinelos, entre outros, tornando a Mormaii a maior e mais querida marca de esportes livres do Brasil.', 129.9, 129.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Bottoms', 'https://cf.shopee.com.br/file/br-11134207-7r98o-makc7msqj3ztce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F312703265%2F19497501507', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
