INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20799320302', 'Frigobar Philco 68L Branco 5 Níveis de ajustes PFGE01', 'Frigobar Philco PFGE01 5 Níveis de ajustes 68L, ideal para armazenar suas bebidas e alimentos prediletos! São 68 litros de capacidade que garante maior aproveitamento de espaço, além de maior praticidade e organização, já que o Frigobar Philco PFGE01 possui compartimento para latas e garrafas. O controle de temperatura com 5 opções de ajuste possibilita escolher a temperatura de acordo com o necessário. Já o sistema de refrigeração com compressor permite uma maior capacidade de refrigeração. A porta do Frigobar Philco PFGE01 é reversível, ou seja, escolha a abertura para esquerda ou direita facilitando a acomodação no seu ambiente. Os pés do Frigobar são ajustáveis e você pode nivelar conforme necessidade garantindo um nivelamento perfeito. Livre de CFC, gás refrigerante ecologicamente correto, não agride o meio ambiente. Tudo isso, com classificação energética “A” que entrega performance com menor consumo de energia. Frigobar Philco PFGE01 5 Níveis de ajustes 68L, com tamanho ideal e a qualidade que você procura! Compacto e econômico Capacidade 68 litros Classe "A" em eficiência energética Sistema de refrigeração com compressor Controle de temperatura com 5 opções de ajuste Prateleiras removíveis Compartimentos para latas e garrafas Bandeja aparadora de água Pés com regulagem ajustável Porta Reversível Degelo Manual Gás refrigerante R-600 - Livre de CFC Ruído aproximadamente (47dB).', 899.9, 899.9, NULL, 'Home Appliances > Kitchen Appliances > Refrigerators', 'https://cf.shopee.com.br/file/sg-11134201-8258o-mqdf07oikvsy90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F811034337%2F20799320302', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203452795', 'Câmara de Ar Aro 16 Vulcan Bor VJ-16 Intruder Kansas Shineray XY', 'CÂMARA DE AR VULCANBOR VJ-16 - Aros 16 Medidas de pneu compatível: 3.00-16 3.50-16 90/80-16 3.25-16 80/100-16 90/90-16 Aplicação Comuns: Suzuki Modelo: Intruder Anos compatíveis: Todos Dafra Modelo: Kansas 150 Anos compatíveis: Todos Shineray Modelo: XY 125.14 // XY 150.5 Anos compatíveis: Todos Projetada para oferecer durabilidade e eficiência, mantendo o padrão de qualidade original para uma experiência de pilotagem segura e confortável. Diferencial do produto: - Resistência ao rasgo proporcionando durabilidade extrema. - Emenda robusta para enfrentar condições adversas. - Elasticidade superior para se adaptar a diferentes terrenos e condições. - Resistência contra furos, mais longevidade em seu uso. - Vedação eficiente mantendo a pressão ideal e a integridade do pneu. – Marca: Vulcan Bor - Código: 152754 – Modelo: VJ-16 - Válvula: TR-4 – Linha: motocicletas – Tamanho de aro: 16 Recomendações: A desmontagem e montagem requerem ferramentas adequadas e cuidado, com todos os componentes ajustados com exatidão. Recomenda-se contar com um profissional especializado para evitar danos às peças.', 23.75, 23.75, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Inner Tubes for Tires', 'https://cf.shopee.com.br/file/sg-11134201-82615-mjk9uyu8cv0m81', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F789664648%2F58203452795', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
