INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493210238', 'MINI ESPUMANTE MAYOS BRUT 187ML', 'Você está comprando: MINI ESPUMANTE MAYOS BRUT 187MLPaís de origem: BRASILValidade: IndeterminadaSOBRE O PRODUTO Mayos Sparkling tem como DNA a autenticidade do território e a leveza por saborear a vida, através de espumantes que traduzem o frescor do nosso clima tropical. TERROIR: Serra Gaúcha - Rio Grande do Sul TIPO DE UVA: Prosecco/Glera, Trebbiano, Malvasia e Chardonnay AÇÚCAR RESIDUAL: 10 g/l HARMONIZAÇÃO Ideal como aperitivo, a versão Brut revela-se um vinho de degustação para festas e eventos sociais. Nas refeições, pode acompanhar entradas leves, pratos elaborados a base de peixes e frutos do mar, carnes brancas e aves preparados com bastante simplicidade ou frias, pela elegância e fineza de ambas. Temperatura ideal de serviço entre 6 e 8°C. VISUAL Com reflexos verdes, o tom dourado pálido e vivo é animado por borbulhas finas. AROMAS O nariz é limpo, fresco, dando vazão a notas de frutas brancas, frutas secas e alguns toques de confeitaria. PALADAR Na boca é bastante aromático, franco e refrescante.', 43.52, 43.52, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/sg-11134201-7rdvn-lyp2wez2d9yv80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F844012318%2F22493210238', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41729025462', 'Kit Freio Hidráulico GTS GHD-100 com 10 Pares de Pastilhas Compatíveis', 'Kit Freio Hidráulico GTS GHD-100 com 10 Pares de Pastilhas Compatíveis – Para Mountain Bike O freio hidráulico GTS GHD-100 foi desenvolvido para ciclistas que buscam desempenho, segurança e praticidade em trilhas e uso urbano. Com sistema de acionamento hidráulico por óleo mineral, proporciona frenagens precisas e moduladas, mesmo em descidas técnicas e terrenos irregulares. Este kit completo inclui os freios dianteiro e traseiro com adaptadores de 160mm, além de 10 pares de pastilhas compatíveis com modelos Shimano (formato quadrado), garantindo reposições futuras com excelente custo-benefício. A regulagem de curso do manete permite ajustes conforme a preferência do ciclista, tornando a experiência de pedal mais personalizada e confortável. Com montagem simples e manutenção acessível, é uma escolha ideal para quem procura eficiência com ótimo acabamento e compatibilidade com os principais padrões do mercado. Especificações técnicas Marca: GTS Modelo: GHD-100 Modalidade: Mountain Bike Tipo: Freio hidráulico a disco Sistema: óleo mineral (compatível com Shimano) Compatibilidade de pastilhas: Shimano M395, M445, M315 (formato quadrado) Regulagem de curso do manete: sim Comprimento da mangueira: dianteira 85 cm / traseira 155 cm Acompanha: 2 adaptadores de freio 160 mm, pinças, manetes e discos Peso aproximado: 746 g (com adaptadores) Pastilhas inclusas: 10 pares Montagem: prática e direta', 196.92, 158.99, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-8262n-mldx3u1uyz2n49', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F990966849%2F41729025462', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
