INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56001424394', 'Spray Jelly Grip Refreshing Aloe essence', '✨ JELLY GRIP REFRESHING ALOE SPRAY Refresque, hidrate e fixe sua maquiagem com o Jelly Grip Refreshing Aloe Spray da essence, o spray multifuncional que transforma sua rotina de beleza. Sua fórmula inovadora em gel se transforma em um spray leve ao entrar em contato com a pele, proporcionando aplicação uniforme e confortável. Enriquecido com aloe vera, oferece hidratação instantânea, brilho natural e ajuda a manter a maquiagem no lugar por mais tempo. O resultado é uma pele com sensação fresca, hidratada e renovada ao longo do dia. Conheça toda a linha Jelly Grip da essence e apaixone-se. 💦 Spray Multifuncional Prepara, fixa e revitaliza a pele. 🌿 Enriquecido com Aloe Vera Hidratação instantânea e sensação refrescante. ✨ Fixa a Maquiagem Ajuda a prolongar a duração do look. 💧 Efeito Refrescante Pele com aspecto iluminado, hidratado e renovado. 🌿 Sobre a Marca A essence é a marca nº 1 na Europa em unidades de cosméticos*, oferecendo qualidade com preço acessível. 100% livre de crueldade animal desde o início, com forte compromisso com produtos veganos. Acreditamos em uma beleza divertida, acessível e responsável. Para a essence, cada pessoa é única — o perfeito é ser você. *Marca de cosméticos em unidades.', 39.9, 39.9, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/sg-11134201-821fe-mh2ec66h76yx3a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816819540%2F56001424394', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
