INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18799607393', 'Ração Special Dog Para Cães Adultos Sabor Carne Plus 15kg', '- Indicado para cães; - Para cães adultos; - Com 22% de proteína de alta qualidade; - Auxilia na redução e odor das fezes; - Absorção de forma mais eficiente. Ração Special Dog Cães é um alimento Premium ideal para cães adultos, pois contém ômegas 3 e 6 para uma pele protegida e pelos mais bonitos. Favorece o equilíbrio para o bem-estar diário, contém 22% de proteínas e com isso trazendo mais qualidade de vida para o pet. Com 100% de minerais orgânico, auxilia na saúde intestinal diminuindo as fezes e o odor. Ingredientes Farinha de vísceras de frango, farinha de carne e ossos, milho integral moído*, sorgo integral moído, farelo de soja*, farelo de trigo, óleo de vísceras de frango, gordura suína, óleo de peixe, casca de aveia, hidrolisado de fígado de frango e suíno, cloreto de sódio (sal comum), DL-metionina, vitamina A, vitamina D3, vitamina E, vitamina K3, vitamina B1, vitamina B2, vitamina B6, vitamina B12, vitamina C, niacina, cloreto de colina, ácido pantotênico, ácido fólico, biotina, iodato de cálcio, sulfato de cobre, sulfato de ferro, levedura enriquecida com selênio, proteinato de manganês, proteinato de zinco, propionato de cálcio, sorbato de potássio, parede celular de levedura, acidificante, antioxidantes (BHA e BHT).', 137.9, 137.9, NULL, 'Pets > Pet Food > Dog Food', 'https://cf.shopee.com.br/file/br-11134207-820m8-mlz2vpgg3cw78f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F398944029%2F18799607393', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
