INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193705392', 'Capa Anti Impacto AZ Defender Magnetic Para Galaxy S25 Plus', 'AZ Defender Capa AZ Defender - Proteção Robusta com Suporte para MagSafe A AZ Defender é a escolha ideal para quem busca máxima proteção sem abrir mão da praticidade. Projetada para absorver impactos, essa capa possui bordas reforçadas com tecnologia antichoque, garantindo maior resistência contra quedas e batidas do dia a dia. - Compatível com MagSafe – Ímãs embutidos que garantem fixação segura e eficiente para carregadores e acessórios MagSafe. - Proteção reforçada – Feita de TPU de alta resistência, com bordas elevadas para proteger a tela e a câmera. - Design robusto e funcional – Estilo moderno e imponente, perfeito para quem valoriza durabilidade e segurança. - Aderência confortável – Textura antiderrapante para melhor pegada e segurança no uso diário. Garanta já a sua AZ Defender e mantenha seu dispositivo protegido com o melhor da tecnologia e do design!', 109.9, 49.9, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m81voylvfe2911', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442913304%2F22193705392', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
