INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12196241991', 'Kit Profissional Jbl St200 Tweeter Fenolico+ Driver D200x', 'Kit Jbl potente pra quem curte um bom som! Ele acompanha o D200-X que é um Driver de compressão com diafragma fenólico de alta eficiência. Excelente para reprodução de médias e altas frequências. Possui diafragma fenólico tipo domo que garante eficiência e durabilidade. Possui docade 25mm (1") permitindo acoplagem com diversas cornetas. Base injetada resistente a altas temperaturas. Acompanha também o super tweeter ST 200 que apresenta elevada eficiência e baixa distorção na reprodução das altas frequências. Pode ser utilizado em sistemas de PA, mini trios automotivos e em sistemas de reforço de som. A base e o difusor são construídos em alumínio contribuindo assim para uma melhor dissipação de calor da bobina móvel, com um acabamento de usinagem diamantada ferramenta de diamante e envernizados. Adquira seu kit!!! Especificações Técnicas: Driver D200x Jbl Selenium 110watts Alta Eficiência Forte • Potência: 110 Watts Rms • Impedância: 8 Ohms • Sensibilidade: 107 dB SPL 1W1m: 3 • Resposta de Frequência -10 dB: 500 - 7500 Hz • Corneta Utilizada nos Testes: HL 14-25 • Frequência de Corte Mínima Recomendada: 500 Hz • Diâmetro da Garganta: 25mm • Material do Diafragma: Fenólico • Material do imã: Ferrite de Bário • Dimensões Aproximadas: 10,7x10,7x6,8 cm (AxLxC) • Peso: 840g Super Tweeter Jbl St200 Selenium St 200 100 Rms Jbl Fenólico • Potência: 70 Watts Rms • Impedância: 8 Ohms • Resposta de Frequência: 2.000 a 20.000Hz • Dispersão Sonora: 40x40º • Material do Diafragma: Fenólico • Diâmetro da Bobina: 46mm • Peso: 750g • Dimensões: 11,5x12,4x6,1cm (LxAxP) Conteúdo da Embalagem: • 01 Driver D200X Selenium Jbl • 01 Super Twitter JBL ST200 70 Watts Rms • Manual e Certificado de Garantia Importante: • Garanti