INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23397483974', 'Máscara de dormir Stitch 3D – Disney', 'Depois de um dia descobrindo novas brincadeiras e vivendo aventuras incríveis, você precisa de uma mãozinha na hora de tirar aquela soneca? A gente te ajuda! Feita em poliéster e com um toque extremamente macio de pelúcia, te ajuda a eliminar a claridade indesejada e pegar no sono mais rápido! Não importa o lugar, essa máscara te acompanha em todos os seus sonos! O produto é importado, feito em poliéster possui detalhes incríveis que vão fazer você se apaixonar! Precisando de uma ajudinha para tirar aquele soninho? A gente te ajuda! Conta com om um toque muito macio além de possuir uma veste muito confortável e ergonômica, é tudo o que você precisa para uma noite de sono perfeita! Não precisa mais se incomodar com claridade externa, essa máscara deixa tudo escurinho e confortável! Não importa se é no sofá ou na cama, essa máscara garante os melhores sonhos em qualquer lugar! Especificações: Tamanho: 12cmx19cm Material: Poliéster Cuidados e recomendações de uso: Passar com temperatura máxima de 110° (sem vapor). Não alvejar. Permitido uso de centrifuga e máquina secadora. Temperatura máxima de lavagem 40°', 64.9, 64.9, NULL, 'Travel & Luggage > Travel Accessories > Travel Pillows & Eye Covers', 'https://cf.shopee.com.br/file/sg-11134201-822yr-mi1ebkp8i8leaf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404743073%2F23397483974', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23994164317', 'Garrafa Mosquetão Quarteto Fantástico - Marvel', 'Depois de um dia cheio de aventuras salvando o mundo e derrotando vilões, você não achou uma garrafa que te ajude a derrotar a sede? A gente te ajuda! Com 500ml de capacidade essa garrafa mata a sua sede! Não importa qual é a aventura, essa garrafa te acompanha em todos os lugares! A garrafa é nacional, muito prática e fácil de transportar, cabe em qualquer cantinho da sua mochila ou bolsa! Com 500ml de capacidade, não importa se você vai enfrentar trabalho, escola ou faculdade, essa garrafa te acompanha em todas as suas tarefas do dia a dia! Feita em alumínio, ajuda a manter a temperatura da sua bebida, para sua água ou suco estarem sempre fresquinhos! Especificações: Altura: 18,5cm| Largura: 7cm| Comprimento: 7cm| Capacidade: 500ml| Material: Alumínio Cuidados e recomendações de uso: Não colocar o produto na geladeira ou congelador. Choques ou quedas podem danificar o produto. Lavar com água, esponja macia e sabão neutro. Não vai á lava-louças e nem ao micro-ondas. Não utilizar produtos químicos ou abrasivos.', 54.9, 54.9, NULL, 'Home & Living > Dinnerware > Water Bottles & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7ra39-mbe102nc0w2rfa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404743073%2F23994164317', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
