INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597334996', 'Nunca o Bastante | Sarah Ivill', 'Vamos admitir, queremos ser bonitas e bem-sucedidas. Mas será que essas marcas de uma mulher "empoderada" poderiam ser ídolos que exigem nossa devoção servil? Se você já lutou com isso, provavelmente conhece a sensação de que nunca será bonita ou perfeita o bastante. Nesse livro, Sarah Ivill discute questões relacionadas à imagem corporal e ao sucesso pessoal enquanto compartilha sobre seu antigo vício em magreza e condicionamento físico. No processo, ela confronta cinco mentiras comuns das quais mulheres de todas as idades são vítimas e nos aponta de volta para nossa aceitação em Cristo, onde encontramos a verdadeira solução para nossa busca pela beleza e sucesso. 14x21cm 150 Páginas', 52.9, 43.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rcdj-lrgn836lm5imf4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23597334996', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23291211966', 'Devocional 40 Dias na Terra Média | Eduardo Medeiros', 'Esta obra da série "40 Dias" tem um foco especial na Terra-media, um dos locais mais incríveis já imaginados por qualquer autor. O colossal universo criado por J.R.R Tolkien oferece a singular oportunidade de mergulhar não apenas na história surpreendente, mas também na psique de personagens tão ricos e complexos. Aprenda princípios espirituais profundos a partir dos heróis e vilões da obra de Tolkien, em 40 textos devocionais inéditos inspirados nos livros, filmes e série da Terra-media e além. 14x21cm 120 Páginas', 32.9, 26.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7qvd2-lgpqx2y9ij2259', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23291211966', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14711086189', 'Redescobrindo o Tesouro Perdido do Culto Familiar | Jerry Marcelino', 'AUTOR: Jerry Marcelino EDITORA: Fiel DESCRIÇÃO DO LIVRO:Este livro é um incrível lembrete da importância do culto familiar e um maravilhoso guia prático para as famílias que acham muito difícil manter este costume. John MacArthur pastor e professor na Grace Community Church, Sun Valley, Califórnia. Se você está procurando idéias práticas e diretrizes para estruturar seu culto em família, não poderá encontrar um guia melhor do que este. O pastor Marcellino nos proporciona grande ajuda no que se refere a desenvolvermos um tipo de culto familiar capaz de envolver nossos filhos. Tedd Trip autor de Pastoreando o Coração da Criança, Editora Fiel INFORMAÇÕES TECNICAS: ISBN 9788581320410 Título Redescobrindo o Tesouro Perdido do Culto Familiar Autor Jerry Marcelino Título original Rediscovering the Lost Treasure of Family Editora Editora Fiel Páginas 64 Formato 12.00 x 16.00 cm Peso 60.00 g. Acabamento Brochura Categorias Familia, Vida Cristã Edição 2a Edição', 21.9, 21.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/0925ca392ef230f129072259db4f4fd0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F14711086189', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
