INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093960942', 'Adesivo para Concreto e Reparos - Sikadur® Epoxi Tix Cinza (Lata 1kg) - SIKA', 'SIKADUR® EPOXI TIX - ADESIVO PARA CONCRETOS E REPAROS - CINZA CLARO (LATA 1KG) | SIKA Sikadur® Epoxi Tix é um adesivo estrutural à base de resina epóxi, conhecido por sua alta viscosidade tixotrópica. Este produto bi-componente é ideal para profissionais que buscam uma solução eficaz e duradoura em diversas aplicações de construção e reparo. Características do Produto: - Tipo: Adesivo estrutural à base de resina epóxi - Viscosidade: Alta (tixotrópico) - não escorre - Cor: Cinza Claro - Embalagem: 1 Lata de 1kg (A + B) Usos Recomendados: - Colagem entre concreto velho e novo ; - Fixação de apoios estruturais ; - Ancoragem de cabos ; - Colagem de elementos pré-moldados ; - Juntas de concretagem (juntas frias) ; - Fixação de chumbadores, calhas e guias em superfícies horizontais ; - Reparos em arestas de concreto aparente, trincas e defeitos superficiais ; - Colagem da Manta de Hypalon Sikadur Combiflex ; - Colagem não estrutural de azulejos em piscinas ; - Colagem de bicos ou niples para injeção de resina epóxi em trincas passivas. Vantagens: - Fácil Aplicação: Ideal para superfícies horizontais e verticais - Endurecimento Rápido: Alta eficiência em projetos - Excelente Aderência: Compatível com concreto, argamassa, madeira, fibrocimento, pedras, cerâmicas, aço, ferro, alumínio e vidro - Impermeável: Resistente à umidade - Elevadas Resistências Mecânicas: Alta resistência à tração e compressão - Resistência Química: Excelente resistência a óleos, graxas, gasolina, soluções salinas, ácidos e álcalis diluídos Instruções de Aplicação: - Preparação da Base: A superfície deve estar limpa e livre de impurezas, como poeira, óleo e ferrugem. - Mistura: Homogeneizar os componentes A e B separadamente e, em seguida, misturá-los até obter uma cor uniforme. - Aplicação: Utilize uma espátula para aplicar uma camada de 1 a 2 mm de espessura, preenchendo todas as cavidades.', 89.9, 87.9, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9hgr0yz4w8p3b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1501367141%2F23093960942', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20997312537', 'Modelador Triskle Mais Q Onda Cacheados 500ml', 'O Modelador Mais Q Onda Cacheadas tem em sua composição óleos vegetais que auxiliam na hidratação e saúde dos seus cabelos. Define os cachos, auxilia na retenção de água nos fios, conferindo alto brilho. Além disso, protege os fios contra os danos dos raios UV. Pode ser usado para misturinhas com gelatinas ou óleos vegetais para potencializar a hidratação e definição. Modo de uso: Com os fios úmidos aplique o Modelador Mais Q Onda por toda a extensão dos fios, amassando e apertando de baixo para cima (movimento em direção à raiz) estimulando a formação dos cachos. Sem enxágue. #html-body [data-pb-style="646BA65FA7B41"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA65FA7B57"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 68.58, 68.58, NULL, 'Beauty > Hair Care > Hair Styling', 'https://cf.shopee.com.br/file/sg-11134201-7rbk0-lkzc38lcoxm9f1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F20997312537', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
