INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7187566261', 'ULTRA LED TITANIUM 9005 HB3 6000K SHOCKLIGHT 12V 50W 10000LM (par)', 'Bem Vindo à AT4U !!! Ultra Led Titanium ShockLight HB3 6000K 12V 50W 5000 LUMENS As Lâmpadas UltraLED Shocklight garantem a melhor solução em iluminação automotiva, pois possuem tecnologia coreana de última geração, garantindo uma eficiência de 10.000 lúmens (5000 em cada lâmpada) que iluminam muito mais que lâmpadas halógenas comuns. Sua temperatura de 6000 K (kelvins) confere um visual com luz extremamente branca, mantendo a economia no consumo de apenas 50W (12v). Caso você queira atualizar e garantir uma iluminação mais forte e atraente, nós temos a lâmpada ideal para o seu veículo. Características: - Modelo: HB3 - Voltagem: DC9-32V - Lumens: 5000 (cada lâmpada) - IP Rate: IP65 - Chip:CSP Samsung - Temperatura Cor: 6000K - Dissipador: Alumínio de Aviação 6063 - Vida Útil: 20x lâmpada halógena - Temperatura de Operação: -40°C ~ +80°C Especificações: - Acabamento Galvanizado e Cromado - Substrato de Alumínio - LED de Última Geração Coreano - Corpo de Liga de Alumínio - Driver Incorporado - Base de Dissipação em Alumínio de Aviação - À Prova D''água - Despolarizado - Com Certificações Internacionais de Qualidade CE, FC, RoHS e E4 - Resistente a Vibrações - Resistente ao Calor Conteúdo da Embalagem: - 01 Par de Lâmpada Ultra LED Modelo HB3 - 01 Manual de Instalação IMPORTANTE: * Postagem em até 24h. * Entrega Garantida. * COMPRE COM SEGURANÇA. * Tire suas dúvidas via chat com nossos especialistas.', 230.04, 230.04, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/af8e96d2b7af31aaac06e23abbd5a4e6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349249646%2F7187566261', NULL, NULL, '2026-07-2