INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12667043089', 'Kit Fusion Shampoo & Máscara - Wella Professionals', 'Este Kit Contém: 1 - Shampoo Fusion 250ml 1 - Máscara de Tratamento Fusion 150ml Sobre o Produto: Linha Fusion foi feita para todos os tipos de cabelos. Reconstroi a fibra instataneamente previnindo futuros danos. Shampoo - Limpa sem agredir os fios. Recupera e devolve maciez até para os cabelos mais danificados. Máscara Capilar - Ajuda a Recuperar e proteger da quebra. Contém ingredientes intensamente condicionantes e aminoácidos. Auxilia na proteção dos fios e futuros danos causados pela escovação. Modo de usar: Após lavar os cabelos com o shampoo da linha Fusion, Aplicar uma pequena quantidade da mascara em todo o comprimento. Emulsionar. Massagear do comprimento as pontas, mecha a mecha. Deixar agir por 5 minutos. Enxaguar. Finalizar como desejar. Ingredientes: Shampoo - AQUA, SODIUM LAURETH SULFATE, COCAMIDROPROPYL BETAINE, SODIUM CHLORIDE, CITRIC ACID, LAURETH-2, SODIUM LAUROYL GLUTAMATE, PARFUM, SODIUM BENZOATE, PEG-4, DISTEARYL ETHER, AMODIMETHICONE, PANTHENOL, POLYQUATERNIUM-10, DISTEARYL ETHER, GUAR HYDROXYPROPYLTRIMONIUM CHLORIDE, GLYCERIN, POLYQUATERNIUM-6, PHENOXYETHANOL, PROPYLENE GLYCOL, PEG-90M, DICAPRYLYL ETHER, HEXYL CINNAMAL, TRISODIUM ETHYLENEDIAMINE DISSUCCINATE, LINALOOL, BENZYL SALICYLATE, LIMONENE, ALPHA-ISOMETHYL IONONE, SILK AMINO ACIDS, SODIUM CITRATE, ALANINE, GLYCINE, HISTIDINE, SILICA, CALCIUM CARBONATE. Mascara - WATER/AQUA/EAU, STEARYL ALCOHOL, BIS-AMINOPROPYL DIMETHICONE, BEHENTRIMONIUM CHLORIDE, CETYL ALCOHOL, PANTHENOL, ISOPROPYL ALCOHOL, BENZYL ALCOHOL, PHENOXYETHANOL,GLYCERIN, FRAGANCE/PARFUM, METHYLPARABEN, TOCOPHERYL ACETATE, GLYCERIN, PROPYLPARABEN, DISSODIUM EDTA, OLEIC ACID, LIMONENE, BENZYL SALICYLATE, HEXYL CINNAMAL, LYCIUM BARBARUM FRUIT EXTRACT, CITRIC ACID, SODIUM BENZOATE, LACTI ACID, POTASSIUM SORBATE. Cuidados/Restrições: Evite o contato com os olhos. Caso isso aconteça, enxágue com água em abundância. Havendo irritação, suspender o uso e procurar orientação médica. Não ingerir. Manter fora do alcance de crianças. Uso externo.', 353.45, 171.46, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/br-11134201-7r98o-lksff67u7s2eb3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F361729924%2F12667043089', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
