INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18799257319', 'Kit Soul Blond Matizador 1kg Original Richée', 'Richée Soul Blond Repositor de Massa Termo Ativado reduz o volume dos cabelos, realinhando o fios e eliminando o frizz enquanto matiza os tons indesejados. Sua fórmula enriquecida com D-Pantenol, Ácido Hialurônico e pigmentos violetas, corrige instantaneamente os tons amarelados e alaranjados, devolvendo o brilho e maciez aos cabelos deixando-os saudáveis e iluminados. A linha Soul Blond foi desenvolvida para manter o loiro dos sonhos. Elimina os tons amarelados ao mesmo tempo que hidrata. Modo de usar: Lave os cabelos com shampoo anti resíduos. Em seguida, separe-os em mechas. Com o auxílio de um pincel, aplique o Richée Soul Blond Repositor de Massa Termo Ativado nas mechas em todo o comprimento a um centímetro da raiz. Deixe agir por 10 a 30 minutos. - Enxágue completamente.Seque 80% dos fios, escove e divida o cabelo em 4 partes. Pranche em mechas finas de 5 a 10 vezes. Finalize como desejar', 199.8, 199.8, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0d5e1xpopls39', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F513541030%2F18799257319', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
