INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201474349', 'Lip Balm Bombom de Cereja - Cereja Mania Dabelle Beauty', 'O Lip Balm HidraCor Bombom de Cereja entrega hidratação profunda, proteção e um toque de cor elegante.Com um tom vermelho mais fechado, sofisticado e natural, deixa os lábios macios, confortáveis e com acabamento uniforme ao longo do dia. Multifuncional, pode ser usado como balm, tint ou blush.Acompanha adesivos exclusivos DaBelle para personalizar o produto. Tecnologia HidraCorNúcleo Cereja:Concentração de Vitamina E, Ácido Hialurônico e Manteiga de Karité, que hidrata profundamente, previne ressecamento, melhora a aparência das linhas finas e mantém os lábios protegidos e saudáveis. Camada Externa:Entrega a cor Bombom de Cereja — um vermelho encorpado, com aspecto natural e acabamento suave. BenefíciosHidratação intensa com ativos poderosos. Cor elegante e efeito natural. FPS 15 para proteção diária contra raios UV. Efeito Lip Tint após remoção do excesso. Textura confortável, não pegajosa. Multifuncional: também funciona como blush. Vegano e não testado em animais. Ideal para uso diário. Modo de UsoAplique diretamente nos lábios para hidratar e adicionar cor. Para efeito tint: aplique, retire o excesso com batidinhas e pronto. Como blush: espalhe pequena quantidade nas maçãs do rosto para efeito saudável.', 39.9, 37.99, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134201-822yq-mo8e15x3zoxya7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939411398%2F58201474349', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
