INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10310382912', 'Espaleira Para Violino Com Regulagem 3/4 - 4/4 Profissional', 'As espaleiras são muito comumente usadas entre os violinistas e violistas modernos, permitindo uma atitude mais confortável ao tocar, adicionando altura no ombro e impedindo o instrumento de escorregar . Um ombro bem descansado ajuda a melhorar o som do instrumento, diminuindo as vibrações da parte de trás do violino e fornecendo uma estrutura firme e confortável. Esta espaleira alivia a tarefa de sua mão esquerda, permitindo que mais suavemente seja feita a mudança de posição. Características: - Curvatura confortável. - Os garfos de borracha protegem a superfície do violino e evitam arranhar. Especificações: Material: Abs/Espuma Garfos: Emborrachado Tamanho: 20 x 3,3 x 5,5 cm Cor: Preta Violino: 3/4 - 4/4 Ajustável: Sim (ângulos) Contém: 01 Espaleira *Imagens Ilustrativas', 35.6, 35.6, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/625201782a35e3669523b407bd202799', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442397041%2F10310382912', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
