INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20699371088', 'Filtro Óleo Fiat Cronos 1.8 2018 A 2019 Mann', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. >Aplicação CRONOS 1.8 PRECISION E.TORQ 2018 até 2019 CRONOS 1.8 PRECISION E.TORQ AT6 2018 até 2019 Conteúdo Da Embalagem 1 Filtro de Óleo Observação Motor EtorQ 16V Tipo de Veículo para Carros Marca Com uma ampla e inovadora linha de produtos a Mann-Filter, sempre primando um alto padrão de qualidade em seus produtos, atendendo assim a todas as exigências da montadoras. Contando com filtros de ar, óleo, combustível e cabine para todos os tipos de motores veículares é máquinas. O Produto Com a finalidade de remover os resíduos indesejáveis que podem estar contidos no óleo do motor, o f iltro de óleo é feito com um papel especial, que está contido dentro da carcaça do filtro. O óleo sujo pode causar entupimento do motor podendo causar até a fundição do mesmo. Importante • Tempo de garantia - 3 meses • Imagem meramente ilustrativa • Valor unitário • Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 EAN 7893390402195 Código do Fabricante HU816/2X >', 24.35, 24.35, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbn9-lltsgfzu6ppl94', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1340945235%2F20699371088', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
