INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498008718', 'Processador Expert Dsp4 Star Bluetooth Player Mesa Crossover', 'Eleve sua experiência de áudio com o processador de áudio Expert DSP4, um dispositivo de última geração projetado para profissionais e entusiastas de som. Com recursos avançados e controle preciso, o DSP4 é a solução perfeita para instalações de áudio no som automotivo. Características • 4 Saídas independentes • 2 Entradas digitais • Roteamento de canais • Bluetooth de áudio com LINK sem fio • Ajuste de sensibilidade de entrada • 11 bandas de equalização de entrada • 1 banda de equalização paramétrica por canal • Crossover com filtros do tipo Butterworth, Linkwitz-Riley e Expert com atenuações de 6 a 48dB/8º • Delay independente por canal • Limiter com Threshold, Atack e Release configuráveis • Limite de pico com ajuste de Threshold • Inversão de polaridade • Ganho de entrada • Mute independente por canal • Gerador de frequência e varredura • Senha de usuário • 3 Memórias 100% configuráveis • Preset com todas as configurações • Ganho independente por canal • Saída remote 300ma • Interface de comunicação via Bluetooth • App com controle de: Roteamento de Canais - Ganho Geral -Ganho de Saída - Limiter RMS - Limiter de Pico - Delay - Equalizador de Entrada - Equalizador de Saída - Inversão de Polaridade - Memórias 100% Configuráveis - Senha de Proteção - Gerador de Sinais • Chassis de alumínio • Dimensões: 154 x 104 x 46mm • Peso: 0.42kg', 680.0, 680.0, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m2107wckfgsx22', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F411060907%2F22498008718', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
