INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23492009730', 'Par Junta Homocinetica Cobalt 2012 1.4 25/21 Dentes Nakata', 'ATENÇÃO,CONFIRA A QUANTIDADE DE DENTES DA PEÇA EM SEU VEÍCULO ANTES DE EFETUAR A COMPRA,COBALT 2012 POSSUI 2 MODELOS( 25/22 DENTES E 25/21 DENTES),CONFIRA PARA NÃO COMPRAR ERRADO! Par Junta Homocinetica GM COBALT MOTORES 1.4 COM ABS CÂMBIO MECÂNICO ORIGINAL NAKATA NJH-09-0582 PRODUTO NOVO!!! A junta homocinética serve exatamente para transmitir torque (“Força”) do sistema de transmissão, para as rodas e ao mesmo tempo, permitir que as rodas girem - durante o comando da direção e os movimentos da suspensão - sem criar oscilações e vibrações na direção. Marca: Nakata Código da peça: NJH050582 Tipo: Junta homocinética Lado: Esquerdo, Direito Posição: Roda OBSERVAÇÃO: 25 DENTES EXTERNOS / 21 DENTES INTERNOS Versão: JUNTA HOMOCINÉTICA - NJH050583 GM COBALT MANUAL COM ABS 1.4 8V 01/2012 12/2012 RODA 25 DENTES EXTERNO / 21 DENTES INTERNO DIR/ ESQ VALOR REFERENTE À DUAS UNIDADES (02 JUNTAS HOMOCINÉTICA ) GARANTIA 90 DIAS PRODUTO ORIGINAL NOVO Imagens meramente ilustrativas Garantia de 90 Dias mediante apresentação do certificado de garantia. Imagens meramente ilustrativas. Instalação deve ser realizada por um profissional especializado. Não nos responsabilizamos por má instalação, uso inadequado do produto ou adaptações que não são compatíveis com a aplicação correta do produto segundo o fornecedor. Garantia do vendedor: 90 meses', 426.0, 383.4, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lk2ifcrxkayyfb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442403193%2F23492009730', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
