INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23799443460', 'Esponja Multiuso Scotch-Brite', 'A Esponja Multiuso Scotch-Brite é a solução ideal para remoção de sujeiras difíceis nos mais diversos tipos de superfície. Com alto poder de limpeza, ela dura até quatro semanas e é ótima para uso na cozinha, em garagens e em ambientes externos. Use o lado verde para limpeza mais pesada, como panelas e frigideiras de alumínio, e o lado amarelo para limpeza mais delicada. Indicada para panelas, talheres e louças em geral.', 10.79, 10.79, NULL, 'Home & Living > Home Care Supplies > Sponges & Scouring Pads', 'https://cf.shopee.com.br/file/sg-11134201-825am-mqnekzie22o262', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554925%2F23799443460', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294234392', 'Motosserra Elétrica EV1600 1600W 50Hz/60Hz 220v Vonder', 'Motosserra Elétrica EV1600 1600W 50Hz/60Hz 220v Vonder Possui freio automático de corrente, pino pega-corrente, protetores de mão esquerda e direita e trava de segurança do gatilho, além de dupla isolação, que garante maior segurança ao operador. Indicada para corte de lenha, podas, jardinagem, pequenas derrubadas, corte de pequenas árvores e galhos. Utilizada em chácaras, sítios, fazendas ou condomínios. Óleo para corrente indicado: 10W-30 ou 20W-50. Modelo:EV 1600 Potência:1.600 W Tamanho do sabre (comprimento):14" Passo da corrente:3/8" (0.375") - 9,53 mm Calibre da corrente:0.050" - 1,3 mm Rotação (rpm):8.000/min (±10%) Capacidade do reservatório de lubrificação do sabre:110 ml Tensão: 220 V~ Frequência:50 Hz/60 Hz Nível de pressão sonora (LpA):112 dB Aceleração transmitida nas mãos - braços do operador - ah:8,3 m/s² Incerteza da aceleração transmitida nas mãos - braços do operador - k:1,5 m/s² Massa aproximada.:Sem sabre 3,86 kg / Sem corrente 4,19 kg Massa aproximada (peso):5.024 kg Conteúdo da Embalagem: 1 Eletrosserra. Garantia legal: 90 dias + Garantia contratual: 3 meses (Para locadoras, garantia única e exclusiva de 90 dias)', 667.58, 503.72, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rcdq-ltcpyqu8kk4x1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F23294234392', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8882841084', 'Pano De Prato Barrado Atacado Premium Kit Com 10 Peças', 'Quer uma cozinha moderna ? Comece pelos Panos de Prato! Pano de prato sacaria de alta qualidade (O Legitimo), com barrado e passa fita, com excelente absorção, não solta fiapos na louça, super absorventes e são anti mancha, podem ser lavados em água sanitária sem medo de manchar os barrados, conta com diversas estampas modernas e exclusivas, uma mais linda que a outra, criadas para alegrar e dar vida a sua cozinha. Contém 10 unidades Estampas: Sortidas Especificações: Trama 12, acabamento em bainha nas laterais com costura reforçada. Barrado: altura de 12cm 100% algodão tecido anti-mancha, estampas exclusivas. Medidas: 41 cm largura x 66 cm altura. Marca da Sacaria: Têxtil H. Carvalho (O Legitimo pé de Galinha). LAVAGEM: Podem ser lavados em água sanitária. Detalhes da Sacaria: O tecido branco do pano de prato é feito em sacaria 100% algodão (conhecido por donas de casa como pé de galinha), considerado por muitos a melhor sacaria do mercado.', 79.99, 55.99, NULL, 'Home & Living > Home Care Supplies > Cleaning Cloths', 'https://cf.shopee.com.br/file/sg-11134201-23020-r5cqqb5y5gnve9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F388739239%2F8882841084', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693502357', 'Jogo Lixas Tubulares Furadeira/Parafusadeira 25 Peças Vonder', 'Jogo de lixas tubulares para furadeira/parafusadeira, com 25 peças, VONDER Acompanha lixas de vários diâmetros, adequando-se a diferentes necessidades. Indicado para furadeiras ou parafusadeiras. Utilizado, principalmente, para superfícies de madeira. Pode ser usado também para lixamento de metais e ferrugens. Especificações: Costado: Tecido Diâmetro do suporte: 1 de 13 mm / 1 de 19 mm / 1 de 25 mm / 1 de 38 mm / 1 de 50 mm Diâmetro e largura da lixa: 13 mm x 13 mm (4 peças) / 19 mm x 25 mm (4 peças) / 25 mm x 25 mm (4 peças) / 38 mm x 38 mm (4 peças) / 50 mm x 38 mm (4 peças) Grão: G 80 Material do suporte: Aço niquelado e borracha Rotação máxima do suporte: Suporte de 13 mm = 30.000/min / suporte de 19 mm = 25.000/min / suporte de 25 mm = 15.000/min / suporte de 38 mm = 10.000/min / suporte de 50 mm = 7.500/min Tipo de costado: Tecido Tipo do grão: Óxido de alumínio Tipo e medida do encaixe do suporte: Haste cilíndrica / suporte de 13 mm = 3,15 mm / suporte de 19 mm, 25 mm, 38 mm e 50 mm = 6,35 mm Massa aproximada (peso) (kg): 0,754 kg Conteúdo da Embalagem: 1 Jogo de lixas tubulares, composto por: 5 suportes e 20 lixas tubulares.', 117.93, 117.93, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m30yqbnkesclee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F22693502357', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297989241', 'Extratora Portátil P/ Limpeza Estofados ELV 1500 Vonder', 'Extratora Portátil Para Limpeza Estofados e Carpetes ELV 1500 Vonder Indicado para aspirar líquidos, é ideal para limpeza de pisos, estofados, sofás, carpetes, cadeiras e diversas superfícies. O sistema pulveriza água ou produto de limpeza e realiza a sucção junto com a sujeira, proporcionando uma limpeza profunda e eficiente no material. Extratora compacta, prática e portátil, facilitando o transporte durante o uso. Possui reservatório para água limpa/produto de limpeza com capacidade de 1,3 L e reservatório para água suja com capacidade de 500 ml. Conta com bocal 3 em 1 que pulveriza, esfrega e extrai sujeiras até das camadas mais profundas. Além disso, possui motor com dupla isolação, garantindo maior segurança ao operador. Produto com certificação compulsória conforme Portaria Inmetro nº 148 de 28/03/2022 e normas ABNT NBR NM 60335-1 e IEC 60335-2-2, com foco nos requisitos de segurança, certificado por organismo acreditado pelo Inmetro. Características: Marca: Vonder Modelo: ELV 1500 Tipo do motor: Universal Potência: 400 W Capacidade do reservatório: 500 ml Capacidade do reservatório de água limpa/produto de limpeza: 1,3 litro Tipo do filtro de ar: Espuma Aspiração: 36 m³/h Vácuo: 90 mbar Comprimento da mangueira: 1,5 m Comprimento do cabo elétrico: 3,3 m Dimensões (C x L x A): 285 mm x 152 mm x 265 mm Frequência: 50 Hz / 60 Hz Nível de ruído: 84 dB(A) Peso: 4 kg Benefícios: Limpeza profunda com sistema de pulverização e sucção Bocal 3 em 1 que remove sujeiras mais difíceis Compacta e portátil, fácil de transportar Reservatórios separados que facilitam o uso Mais segurança com motor de dupla isolação Conteúdo da Embalagem: 1 Extratora para limpeza 1 Bocal simples 1 Bocal 3 em 1 1 Manual', 619.9, 466.56, NULL, 'Home Appliances > Small Household Appliances > Vacuum Cleaners & Floor Care Appliances', 'https://cf.shopee.com.br/file/br-11134207-820lm-mm0nhf2sutc4b5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F23297989241', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54259380516', 'Passadeira Vaporizador Britânia Portátil 1200W Bivolt BVP06', 'A Passadeira a Vapor Britânia Portátil 1200W Bivolt BVP06 é ideal para quem busca praticidade na hora de desamassar roupas e tecidos no dia a dia. Compacta, leve e fácil de manusear, ela conta com cabo dobrável, permitindo melhor aproveitamento de espaço e mais facilidade para guardar ou transportar. Com potência de 1200W, reservatório de 260ml e vapor com saída de 17g/min, a passadeira oferece bom desempenho para deixar as peças com aparência mais alinhada de forma rápida e prática. Pode ser utilizada na posição horizontal ou vertical, sendo uma ótima opção para roupas, cortinas, almofadas, sofá e tábua de banho. Características: Marca: Britânia Modelo: BVP06 Potência: 1200W Capacidade do reservatório: 260ml Luzes de funcionamento: Sim, na cor vermelha Copo dosador: Sim, 50ml Quantidade de furos: 7 furos Tempo de uso contínuo: 18 minutos Tempo aproximado de aquecimento: 25 segundos Bivolt automático ou manual: Automático Temperatura máxima: 98°C Cabo dobrável: Sim Perfeito para viagem: Sim Taxa de emissão de vapor: 17g/min Acessórios: Escova e copo dosador Cor do produto: Azul e branco Material: Metal e plástico Tamanho do cordão: 1,90m Frequência do plugue: 10A Pinos: 3 pinos Benefícios: Portátil e compacta, ideal para uso em casa ou viagens Cabo dobrável, facilitando o armazenamento Reservatório de 260ml para maior praticidade no uso Pode ser usada na vertical ou horizontal Aquecimento rápido em aproximadamente 25 segundos Conteúdo da embalagem: 1 Passadeira a Vapor Britânia BVP06 Bivolt 1 Escova 1 Copo dosador', 269.83, 269.83, NULL, 'Home & Living > Home Care Supplies > Mops', 'https://cf.shopee.com.br/file/sg-11134201-820nb-mneb6sn60c9284', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F54259380516', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52407180535', 'Escova Manual Aço 6 Fileiras Cabo Plástico 1p SPARTA', 'Escova manual em aço com seis fileiras de cerdas, projetada para limpeza eficiente de superfícies ásperas como grelhas, churrasqueiras e ferramentas. A construção em aço confere maior resistência ao desgaste, garantindo desempenho prolongado em tarefas de raspagem e limpeza pesada. O cabo em plástico proporciona empunhadura firme e manuseio confortável durante o uso. Produto prático e compacto, indicado para aplicações domésticas e profissionais que exigem remoção de sujeira incrustada com precisão. Características: Modelo: 7486855 Referência: 7486855 Marca: SPARTA Material: Aço Fileiras: 6 Cabo: Plástico Quantidade: 1 peça Benefícios: Limpeza eficaz de sujeiras incrustadas graças às cerdas em aço. Durabilidade superior para uso contínuo em tarefas pesadas. Cabo plástico para manuseio confortável e controle durante a limpeza. Design compacto e prático para armazenamento e transporte. Adequada para uso doméstico e profissional. Conteúdo da embalagem: 1 escova manual em aço com cabo plástico, 6 fileiras (1 peça).', 27.76, 21.82, NULL, 'Home & Living > Home Care Supplies > Cleaning Brushes', 'https://cf.shopee.com.br/file/sg-11134201-8262e-mls9knjlmqdd7a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F52407180535', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393865689', 'FERMENTO EM PÓ NITA 2KG FERMENTO PARA BOLOS, TORTAS E BISCOITOS', 'Fermento em Pó Químico Refil - Nita Fermento químico em pó 2kg. Não contém glúten. Principais Aplicações: Bolos, tortas. Lista de Ingredientes: Bicarbonato de sódio, fosfato monocálcico, amido de milho geneticamente modificado (por Bacillus thuringiensis, Streptomyces viridochromogenes, Agrobacterium tumefaciens, Zea mays, Sphingobium herbicidorovans, Dicossoma sp., Diabrotica firgifera, Thermoccocales spp., Bacillus substilis) ou fécula de mandioca e carbonato de cálcio. Características Físico-QuímicasResolução da Anvisa nº 38 de 27/12/1977 Características MicrobiológicasResolução ANVS nº 331 de 23 de dezembro 2019. Não contém glúten. Prazo de Validade: 12 meses a contar da data de fabricação, sob condições adequadas de armazenagem. Conservação: Manter em local fresco, seco e inodoro, evitando sol, calor e umidade.', 77.85, 77.85, NULL, 'Food & Beverages > Baking Needs > Baking Powder & Soda', 'https://cf.shopee.com.br/file/sg-11134201-7renb-m80fdkkiy9w1bb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F23393865689', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
