INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198526230', 'Maybelline The Colossal Volum''Express Waterproof - Máscara para Cílios 9,2ml', 'Maybelline The Colossal Volum''Express Waterproof - Máscara para Cílios 9,2ml Máscara de cílios preta. The Colossal Volum''Express Waterproof à prova d''água e resistente ao calor, umidade e suor, realça o olhar sem borrar. Enriquecida com colágeno e agentes espessantes, a fórmula de The Colossal Volum''Express Waterproof garante que o seu efeito tenha longa duração. Seu aplicador alcança e preenche todos os fios e deixa os cílios alongados, curvados e cheios de volume. Testado dermatológica e oftalmologicamente, pode ser usado por olhos sensíveis e usuários de lentes de contato. Ação Colágeno e agentes espessantes: encorpa e dá volume aos cílios por longa duração. Conselho de Aplicação Aplique diretamente sobre os cílios, penteando os fios da raiz até ponta. Reaplique até alcançar o efeito desejado, sempre em movimento de "ziguezague" para não empelotar. Antes de usar a máscara, sempre retire o excesso da fórmula na própria embalagem ou com o auxílio de um papel. Isso impede o acúmulo nos cílios e que um fio não grude no outro. Resultado Seus cílios alongados e volumosos por longa duração.', 123.05, 63.9, NULL, 'Beauty > Makeup > Eyes', 'https://cf.shopee.com.br/file/sg-11134201-7rasz-ma4iobmy17ym68', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F23198526230', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
