INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21697406981', 'Sandália Babuche Infantil Menino Básico Liso Marinho E Laranja 19/20', 'O Babuche Plugt Joy Baby Básico tem tira traseira que facilita o calce, sola antiderrapante e leve. Ele é um básico que deixa o lookinho dos meninos ainda mais estiloso! As crianças AMAM, a escolha PERFEITA!! Aqui na Plugt você encontras os melhores modelos que são tendência no Verão. Temos a escolha perfeita para todas as ocasiões! Comprimento da Palmilha em CM: (medida do dedão ao calcanhar) 19/20 - 13,3 cm 21/22 - 14,6 cm 23/24 - 16 cm 25/26 - 17,3 cm -------------------------------------------------------------------------------------- SOBRE NÓS: A Plugt é uma empresa especialista em fabricação de calçados infantis injetados. O material que utilizamos é o PVC Microexpandido que além de leve, confortável, FÁCIL DE LAVAR, ainda é RECICLÁVEL (o que conseguimos fazer desde o processo produtivo até após o uso - um processo amigo do meio ambiente). Sempre nos inspiramos no poder da imaginação das crianças para criar produtos divertidos e coloridos assim como a Plugt é! Ah, e sem deixar de lado o conforto, a praticidade de calce e a facilidade em lavar que as mamães amam! Fabricamos calçados do 17/18 até o 41/42', 139.9, 139.9, NULL, 'Baby & Kids Fashion > Boy Shoes > Sandals', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lm6jcy6wurzf23', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F284865829%2F21697406981', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393148995', 'Plenitude - Grupo Editorial Gente', '“Não fuja da dor, não fuja do constrangimento, não fuja do desprazer. Se for preciso se humilhar, humilhe-se. Deixe doer! Viva o processo de ser transformado todos os dias pela verdade.” Você tem sido sincero consigo e com o mundo sobre como está vivendo sua vida? Como estão seu casamento, suas finanças, suas amizades, sua vida familiar e espiritual? Se estiverem no piloto automático, pode ser hora de parar e refletir com verdade sobre isso. Esse exercício é, fundamentalmente, o que propõe Camila Saraiva Vieira neste seu livro Plenitude: 40 dias para você ir além. Para chegar à sua vida plena, você passará pelos pilares de um bom relacionamento com Deus e consigo, trabalhando aspectos como consciência, identidade, obediência, orgulho e humildade. A autora o guiará por essa jornada de conexão, sugerindo orações diárias e diálogos com o Pai, além de exercícios para ajudá-lo a trazer consciência sobre cada situação vivida. Neste livro, você encontrará: Meios para construir e fortalecer uma conexão poderosa com Deus, entendendo os verdadeiros propósitos Dele para sua vida O caminho para construir o hábito de meditar na palavra do Senhor Formas de usar sua consciência para combater o orgulho e humilhar-se diante do Pai, aceitando o que Ele trouxer para você Informações sobre como acabar com padrões inconscientes que já não fazem sentido e que impedem que sua vida siga na direção da plenitude que você merece Exortações a aceitar a presença de Deus na sua vida em todos os sentidos, aguardando pacientemente pelas promessas que virão.', 55.23, 55.23, NULL, 'Books & Magazines > Books > Parenting & Family', 'https://cf.shopee.com.br/file/sg-11134201-7rdwb-lxpw2cax3ngqa1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F22393148995', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
