INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23192569914', 'Ataque dos Titãs Vol. 15 - Panini', 'Com uma revolução política em andamento, a Divisão de Reconhecimento começa a ir atrás do apoio da população, rebelando-se contra o governo. Enquanto isso, Eren e Historiya se aproximam cada vez mais da verdade sobre a transformação dos titãs!', 42.17, 42.17, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-7rbll-ln3i8tfqo7so1a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F23192569914', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253912448', 'Pneu Pirelli Aro 17 Powergy 215/50 R17 91v', '** ENVIAMOS PARA TODO BRASIL ** PRODUTO NOVO ** GARANTIA DE FÁBRICA DE 5 ANOS (somente por defeitos de fabricação, ficando invalida em caso de danos por acidentes, buracos na pista, mau uso e má instalação) ** EMISSÃO DE NF **O FATURAMENTO É REALIZADO APENAS PARA CONSUMO, SENDO VETADO O FATURAMENTO PARA REVENDA. ** SOBRE O PNEU: O Pirelli Powergy é o pneu ideal para motoristas que estão em busca de uma solução eficiente, segura e confortável para encarar os desafios do dia a dia. Sua construção foi desenvolvida para reduzir a distância em frenagens, principalmente no piso molhado. Essa qualidade, atrelada ao desenho das lamelas com barbatanas na banda de rodagem, diminui as chances de aquaplanagem e derrapagens na chuva. O Powergy foi construído com tecnologia de ponta e materiais de alta qualidade para proporcionar melhor aderência e precisão nas manobras. Além disso, a baixa resistência ao rolamento melhora a eficiência energética, o conforto e aumenta a economia de combustível. Esse pneu pode ser utilizado nos seguintes carros: CHEVROLET: BOLT, CRUZE, CRUZE II, CRUZE SPORT6, CRUZE SPORT6 II CITROEN: C4 GRAND PICASSO, C4 PICASSO FIAT: CROMA, STILO FORD: FOCUS, FOCUS FASTBACK, FOCUS HATCHBACK, FOCUS II HONDA: CIVIC X JAC: IEV60, T60 MITSUBISHI: ECLIPSE NISSAN: LEAF SUBARU: LEGACY TOYOTA: COROLLA XEI, COROLLA XI VOLVO: C70, S60, S80 Garantia de fábrica: 5 anos', 714.0, 642.6, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-82632-mjtwq9cnf6yof8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1081431407%2F58253912448', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
