INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201340444', 'Pastilha Freio Dianteira FRASLE Para Logan Sandero Stepway Zen', 'IDEAL AUTO PARTS Desde 1990 IDEAL PARA SEU CARRO Pastilha Freio Dianteira FRASLE APLICAÇÃO RENAULT Logan 1.0 12V De 2013 A 2021 Logan 1.6 8V De 2013 A 2019 Logan 1.6 16v De 2013 A 2019 Sandero 1.0 12V De 2014 A 2019 Sandero 1.6 8v De 2014 A 2019 Sandero 1.6 16v De 2014 A 2019 Stepway 1.6 8V De 2014 A 2019 Stepway 1.6 16v De 2022 A 2025 Stepway Zen 1.0 12V De 2022 A 2025 MEDIDAS: 140 X 42.5 X 17.5mm APLICA SE PARA SISTEMA FREIO TEVES CODIGO DO FABRICANTE FRASLE PD1483 CONTEÚDO DA EMBALAGEM 04 Pastilha Freio Dianteira QUALIDADE Produto Novo GARANTIA 03 Meses De Garantia NOTA FISCAL Sim SUPORTE PÓS VENDA Sim SOBRE A IDEAL AUTO PARTS Fundada em 1990, somos uma empresa do ramo de comércio e varejo de peças novas para veículos automotores. São mais de 30 anos oferecendo peças reconhecidas nacionalmente e internacionalmente com os melhores preços do Brasil. A paixão por automóvel e o crescimento do mercado, contribuiu para a expansão da marca e hoje contamos com quatro endereços físicos, localizados em pontos estratégicos na cidade de Limeira, Artur Nogueira e Rio Claro, no interior de São Paulo. Contamos com uma equipe especializada para prestar o melhor atendimento e oferecer exatamente o que nosso cliente precisa. São mais de 35 mil Itens de diversas montadoras a disposição em nossas lojas. CASO TENHA ALGUMA DÚVIDA USE O CAMPO DE PERGUNTAS, ESTAREMOS A DISPOSIÇÃO PARA TE ATENDER', 126.9, 126.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-82286-mhrldsse8u1159', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616290090%2F58201340444', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
