INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14718310332', 'Valvula Termostatica Sonic Cruze Tracker MTE', 'IDEAL AUTO PECAS - Desde 1992 - IDEAL PARA SEU CARRO! Valvula Termostatica - MTE APLICACAO: Cruze 1.8 16v de 2012 a 2015 MTE Sonic 1.6 16v de 2012 a 2015 Tracker 1.8 16v de 2013 a 2016 (Abertura 92?C) DESCRICAO DO PRODUTO: A valvula termostatica trabalha para que o motor trabalhe em uma temperatura adequada e assim, retire sua melhor potencia e economia. A valvula controla a saida do liquido de arrefecimento do motor ao radiador e assim equilibra a temperatura do motor.', 183.9, 183.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Engine', 'https://cf.shopee.com.br/file/d4b6bc9c3e644a6e69d3a007d5af8756', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616290090%2F14718310332', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
