INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251360983', 'Camisola Infantil Manga Curta', 'Delicado, confortável e cheio de charme, o pijama infantil feminino Lilica Ripilica é a escolha perfeita para tornar a hora de dormir ainda mais especial. Confeccionado em malha comfort, proporciona um toque macio e leve, ideal para acompanhar as pequenas em noites tranquilas ou momentos de descanso em casa. Com fundo off white, o conjunto é decorado por uma estampa rotativa de floral delicado com a encantadora interferência do rostinho da Lilica Ripilica, que aparece de forma sutil entre as flores, trazendo um toque lúdico e feminino à peça. A blusa de manga curta possui modelagem tradicional, oferecendo conforto e liberdade nos movimentos. Já o shorts, coordenando com a blusa, tem cós confortável e conta com um charmoso detalhe de falso amarração em cadarço de algodão personalizado, que embeleza o look sem abrir mão da praticidade. É o conjunto ideal para unir bem-estar, estilo e doçura no dia a dia das meninas.', 129.5, 77.7, NULL, 'Baby & Kids Fashion > Girl Clothes > Tops', 'https://cf.shopee.com.br/file/sg-11134201-8227s-mhrw42598g056c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F980954412%2F58251360983', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
