INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898573575', 'Engate Reboque Nissan Sentra 2014 A 2021 700kg Brucke tOP', 'Engate Fixo Nissan Sentra 2014 2015 2016 2017 2018 2019 2020 2021 700kg Brucke O Engate Reboque Brucke foi desenvolvido para transporte de grande quantidade de carga, reboque de trailers, barcos e demais veículos. Com uma capacidade de tração máxima 700KG o Engate Reboque Brucke foi produzido com material especial de aço carbono preparado com Pintura Eletrostática na cor preta, seu kit é de Excelente Qualidade com acabamento em cromado Especificação Técnica: - Fabricado em Aço Carbono Pintado na Cor Preta - Modelo Fixo com Excelente Acabamento - Pintura Eletrostática a Pó - Tomada Elétrica: 12V 6 Polos Cromada - Usa furação original do veículo (NÃO FURA) - Bola de Engate Resistente Cromada com 50mm de Diâmetro - Peso da Esfera:40KG - Tração Máxima de 700KG - Produto de Alta Qualidade - Homologado pelo INMETRO e normas exigidas pelo Órgão Fiscalizador; Resolução CONTRAN Nº 937 Conteúdo da Embalagem: 1- Engate; 1- Bola Cromada; 1- Tomada Elétrica; 1- Capa cromada em Inox; 1- Kit de fixação; Compatível : Sentra 2014 2015 2016 2017 2018 2019 2020 2021 - Prezado Cliente: - Por favor, verifique a Capacidade Máxima de Tração (CMT) no manual do seu veículo antes de fazer a compra, pois alguns veículos utilizam o engate reboque exclusivamente por motivos estéticos, sem a capacidade de tracionar carretinhas ou objetos pesados. - Por gentileza, verifique se o modelo da imagem e os anos mencionados no anúncio correspondem ao seu veículo antes de concluir a compra. -Caso necessite de esclarecimentos adicionais, sinta-se à vontade para utilizar o campo de perguntas! - Imagens Meramente Ilustrativas - Garantia de fábrica: 6 meses a Empresa não é responsável pela má instalação do produto, Recomendamos que a instalação seja feita por um profissional especializado Garantia do vendedor: 3 meses', 411.86, 411.86, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rasy-mapqtqe76okz87', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1069588064%2F22898573575', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23994063786', 'Conector DC Jack para Notebook Asus Z450LA-WX002T', 'Conector DC Jack compatível com Asus Z450LA-WX002T Este é um DC Jack bringIT compatível com o notebook Asus Z450LA-WX002T. Ele é ideal para acabar com os problemas de alimentação de energia em um notebook. O DC Jack — ou DC Power Jack — é um conector interno responsável por intermediar a alimentação de energia entre a fonte (carregador) e o laptop. Este produto é um de alta qualidade e cumpre todas as especificações de segurança dos notebooks. Para evitar problemas de compatibilidade, compare as fotos deste anúncio com seu equipamento original. Assim você consegue verificar as principais informações de compatibilidade e demais especificações do seu notebook. Atenção: Esse é um dc jack bringIT, portanto não é um produto original da fabricante Asus. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Informações Técnicas Tamanho do Conector: 5.5mm x 2.5mm Cabo: Sem Cabo Garantia: 3 meses de garantia contra defeitos de fabricação Referência: DC131-AS-0007', 35.6, 33.82, NULL, 'Computers & Accessories > Desktop & Laptop Components > Power Supply Units', 'https://cf.shopee.com.br/file/sg-11134201-82591-mqu944dmsykh3a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F23994063786', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
