INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697917235', 'Creamy Skincare Ácido Glicólico - Creme Redutor de Linhas 30g', 'Creamy Ácido Glicólico - Creme Redutor de Linhas 30g Creme Redutor de Linhas de uso noturno para todos os tipos de pele. Creamy Ácido Glicólico auxilia na uniformização do tom, melhora a textura da pele, deixa os poros menos aparentes e previne sinais da idade. Conselho de Aplicação Uso noturno. Aplicar sobre a pele seca e preferencialmente hidratada, evitando a região dos olhos, os cantos do nariz e da boca. Espalhe 1 ou 2 pumps sobre a pele do rosto, pescoço e/ou do colo, se desejar. No início do uso, recomenda-se usar em noites alternadas até que a pele não apresente nenhum sinal de irritação. Lave a pele pela manhã e aplique protetor solar.', 199.25, 94.9, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/sg-11134201-7rdxg-m18uvtgyp0rcc6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F22697917235', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498399093', 'Kit Creamy Pro-Adapaleno Ácido Glicólico Sérum Creme Redutor (2 produtos)', 'Kit Creamy Pro-Adapaleno Ácido Glicólico Sérum Creme Redutor (2 produtos) Este Kit Contém Creamy Skincare Pro-Adapaleno - Sérum Facial 30g: trata e reduz a inflamação acneica, controlando o brilho e a oleosidade. Enriquecido com adapalenato, esse reinóide possibilita resultados mais rápidos e com menos irritação. Possui ação anti aging, reduz os poros e melhora a vermelhidão da pele sem ressecar. Creamy Skincare Ácido Glicólico - Creme Redutor de Linhas 30g: creme redutor de linhas de uso noturno para todos os tipos de pele. Auxilia na uniformização do tom, melhora a textura da pele, deixa os poros menos aparentes e previne sinais da idade. Conselho de Aplicação Sérum: À noite, utilize 1 pump sobre a pele do rosto limpa e completamente seca, evitando o contorno dos olhos, do nariz e da boca. Nas primeiras aplicações, limite o uso para uma ou duas vezes por semana. Sua utilização pode aumentar a fotossensibilidade. Aplique sempre um filtro solar de alta proteção durante o dia. Ácido Glicólico: uso noturno. Aplicar sobre a pele seca e preferencialmente hidratada, evitando a região dos olhos, os cantos do nariz e da boca. Espalhe 1 ou 2 pumps sobre a pele do rosto, pescoço e/ou do colo, se desejar.', 512.05, 242.9, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/sg-11134201-7repw-m8dsdtogbzxldd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F22498399093', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
