INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22209963686', 'Escapamento Escape Pro Tork Papaléguas Eight Aço Titan 150 KS/ES 2004 a 2008', 'O Escapamento Pro Tork Papaléguas Eight proporciona uma maior otimização do motor e respostas mais rápidas nas acelerações, além do seu ronco grave. Seu tubo em formato oval e sua saída em formato 8 dão uma aparência mais esportiva à sua moto. Pensando também na durabilidade, o escapamento é fabricado com materiais que garantem maior vida útil ao produto e resistência contra as ações do tempo. Especificações: - Modelo: Papaléguas Eight; - Material: Aço; - Marca: Pro Tork; - Segue todas as normas reguladoras de fabricação; Aplicação: - Titan 150 KS/ES 2004; - Titan 150 KS/ES 2005; - Titan 150 KS/ES 2006; - Titan 150 KS/ES 2007; - Titan 150 KS/ES 2008. Instalação: - Antes de finalizar a compra, certifique-se de que sua moto seja compatível com algum dos modelos acima. Pois o produto é pronto para instalação e não necessita de nenhum tipo de adaptação; - Para realizar a instalação, leve sua moto à uma oficina especializada; - A Sportbay não se responsabiliza pela má instalação do produto. OBS: - Pode haver diferença de tonalidade entre a imagem e o produto real por conta do tratamento de imagens e a calibração de cores da tela de seu monitor ou aparelho. Sportbay - Seu Esporte, Nossa Paixão.', 310.42, 254.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Exhaust and Muffler', 'https://cf.shopee.com.br/file/sg-11134201-22120-t90aep6njvkv1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F22209963686', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23136881385', 'Baú Moto Bauleto 35 Litros Pro Tork Smart Box 4 Universal com Refletor Vermelho /Fumê', 'O Baú Smart Box 4 é uma excelente opção para os motociclistas que necessitam carregar alguns objetos no dia a dia. Com capacidade de 35 litros, comporta um capacete, mais uma capa de chuva ou outros itens pequenos. Oferece segurança extra com a lente com defletor, disponível em vermelho ou fumê. A fechadura com chave também é um diferencial. O modelo é universal, podendo ser instalado em qualquer motocicleta, porém, há a necessidade de comprar à parte o bagageiro em aço específico. Especificações: - Capacidade: 35 litros; - Cabe 1 capacete + capa de chuva; - Injetado em polipropileno de alta qualidade; - Fechadura com chave; - Lente com defletor traseiro (vermelho ou fumê); - Acompanha parafusos e base para a fixação do baú; - Marca: Pro Tork. Medidas: - Altura 33 cm x largura 46 cm x comprimento 39,5 cm. Instalação: - Recomendamos que a instalação seja feita em bagageiro de aço, por profissional especializado; A loja não se responsabiliza pela má instalação do produto. Observação: - Pode haver diferença de tonalidade entre a imagem e o produto real por conta do tratamento da foto e a calibração de cores da tela do seu monitor ou aparelho.', 357.78, 159.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Cases', 'https://cf.shopee.com.br/file/sg-11134201-7qvcq-lf9ziq8hxsy4de', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F23136881385', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
