INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52210180111', 'De quanta terra precisa um homem? e outras histórias | Liev Tolstói', 'Nesta coleção de quatro contos, Tolstói fala das coisas que realmente importam na vida, abordando com leveza temas sérios como teologia, filosofia e natureza humana trazendo ensinamentos inesquecíveis e significados profundos em uma leitura cativante. Título: De quanta terra precisa um homem? e outras histórias | Liev Tolstói Autor: Liev Tolstói Páginas: 96 Formato: 16 x 23 cm Edição: 2020 Capa: Brochura Peso: 0,245 kg ISBN: 9786555522372 Editora: Ciranda Cultural', 11.9, 11.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-820m8-mnzvbngbx98m38', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F52210180111', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293520007', 'O Sobrenatural na medicina | D. M. Lloyd Jones', 'O Sobrenatural na medicina | D. M. Lloyd Jones Esta palestra proferida por D. Lloyd-Jones em maio de 1971, na conferência anual da Fraternidade Médica Cristã, trata de forma abreviada, mas abrangente, do assunto da “cura miraculosa” , ou seja, da intervenção divina em casos de enfermidade fora da competência da medicina. “O Doutor” nos dá uma boa orientação sobre os problemas envolvidos neste assunto e salienta as atitudes e os princípios básicos que devem nos servir de bússola quanto à posição bíblica sobre o mesmo. Autor: D. M. Lloyd Jones Editora: Pes Acabamento: Capa comum brochura Dimensões: 11 cm largura x 18 cm altura Número de páginas: 48', 5.99, 5.99, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7reqe-m2bfqln8sp4z6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F23293520007', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
