INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23494951154', 'Geladeira BRO85M 3 Portas Side Inverse 554 Litros Frost Free Brastemp', 'Sua cozinha merece o status de protagonista, e a Brastemp Side Inverse é o toque de sofisticação que faltava. Com um design arrebatador e a elegância das três portas, ela transforma o ato de cozinhar em uma experiência de puro prazer e praticidade. Viva a exclusividade de ter o melhor do design moderno ao seu alcance. Características: Marca: Brastemp Modelo: BRO85M Consumo Aproximado de Energia: 31,3 Kw/ano Eficiência Energética: Classe A Quantidade de Portas: 3 Portas Tipo de Geladeira: Frost Free Sistema de Refrigeração: Inverter Degelo: Automático Capacidade do Freeezer (L): 178L Capacidade em Litros: 554L Código da Certificação INMETRO: 005218/2016 Conteúdo da Embalagem: 01 Geladeira BRO85MB 3 Portas Side Inverse 554 Litros Frost Free Brastemp 01 Guia Rápido 01 Manual de Instruções 01 Kit de Instalação para Puxadores Dimensões: Altura: 186cm Largura: 84cm Profundidade: 73cm Peso: 86Kg Garantia do Fornecedor: 12 Meses Observações: Imagem meramente ilustrativa. Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. As cores podem sofrer variações de acordo com o tipo, configuração e resolução do seu monitor. Verifique a voltagem do produto antes de colocar no carrinho. Verifique as dimensões do produto. Certifique-se de que ele passará por elevadores, portas, escadas e/ou corredores, evitando imprevistos com a entrega do produto.', 6916.8, 6916.8, NULL, 'Home Appliances > Kitchen Appliances > Refrigerators', 'https://cf.shopee.com.br/file/sg-11134201-820lx-mnyi31fr53i967', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F443109642%2F23494951154', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698446468', 'Carrinho de Controle Remoto Batman Autoracing Candide - 90003', 'Explore a empolgação do Veículo Controle Remoto 3 funções Batman Autoracing da Candide Brinquedos. Inspirado no lendário herói noturno, oferece três funções distintas: para frente, para trás e parado. Com controle remoto em formato de volante, proporciona uma experiência autêntica e realista. Pilhas inclusas garantem diversão imediata. Ideal para entusiastas de todas as idades, este veículo de alta qualidade une a aura do Batman à emoção das corridas. Adquira já e acelere para a diversão! - Faixa Etária Recomendável: Acima de 3 Anos - Origem: Importado - Funções: 3 Funções - Composição: Plástico - Certificado: INMETRO - Dimensões da Embalagem: C: 7,2 cm / L: 36 cm / A: 27 cm - Controle Remoto Características: - Marca:CANDIDE - Modelo:90003 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - 01x Carrinho Batman Autoracing - 01x Controle Remoto - Pilhas', 95.48, 95.48, NULL, 'Mom & Baby > Toys > Toy Vehicles', 'https://cf.shopee.com.br/file/sg-11134201-7rfhr-m9anf2lew4iv73', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F23698446468', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
