INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9868134083', 'Kit Som Bluetooth Polo + 4 Alto Falante Bravox 200w', 'Kit Composto por um aparelho usb Bluetooth + 4 alto falantes b3x60x Bravox ----------------------------------------------------------------------------------------------------------- MP3 Player Automotivo Rádio FM USB SD Entrada Auxiliar BLUETOOTH. Tela Led Painel Frontal 4 saídas de autofalante Função de relógio real Sintonização de rádio eletrônica Suporte para USB/ SD/ abertura para cartão MMc Compatível com formato de música MP3 Com Bluetooth ----------------------------------------------------------------------------------------------------------- 2 Pares Alto Falantes Bravox 6 Polegadas Triaxial B3x60x Kit Os Triaxiais e o Quadraxial 6x9” da Linha X possuem design arrojado e inovador e se adaptam perfeitamente aos novos conceitos de carros “tunados”, aliando potência, desempenho e durabilidade. De simples instalação, podem ser instalados em qualquer veículo com ou sem adaptação nas portas dianteiras, traseiras, tampão e painel. CARACTERÍSTICAS: 6"POLEGADAS 50WRMS 4OHMS Cone injetado em polipropileno Bobina em corpo de alumínio Borda injetada em santoprene Ímã de fluxo magnético Tweeter Mylar e Midrange ESPECIFICAÇÕES TÉCNICAS Modelo B3X60 X Código 9-6076/097 Polegadas 6" Impedância 4 Sens. dB/W/m 89 Fo Hz 85 RESP.Fq. Hz 60 - 20K WMAX. Watts 100 WRMS. Watts 50 Altura mm 53 Diâmetro mm 165 CONTEÚDO DA EMBALAGEM • 4 - Alto-falantes 6" Bravox B3X60X - 50W RMS cada (sem tela)', 258.46, 221.54, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/f54928f2c54d25951f67805fe8a79d30', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328179142%2F9868134083', NULL, NULL, '2026-07-28T02:11:31.708458+0