INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28394564463', 'Kit 4 Marca Texto Neon Stabilo Boss - STABILO', 'Kit 4 Marca Texto Neon Stabilo Boss - STABILO • Pedidos feitos até às 11:00 horas (de segunda à sexta) são despachados no mesmo dia!!! Clássico de design incomparável Acabamento de alta qualidade, tinta à base de água e conforto na escrita Tecnologia STABILO Anti-Dry-Out: 4 horas de proteção contra ressecamento para trabalhos concentrados 2 larguras de linha: 2 + 5 mm Ótimo para adicionar toques de cor em letterings manuais ou journaling. STABILO BOSS ORIGINAL tem sido a escolha favorita de estudantes, profissionais de escritório, designers e artistas. A ponta chanfrada com duas larguras de linha de 2 e 5 mm permite sublinhar e destacar com apenas um marca-texto.Traz ordem para registros, anotações e muito mais. Ótimo para trabalhar, estudar e projetos criativos. Características do produto: pode ficar destampado por até 4 horas sem ressecar ou falhar. Teve um dia corrido? Não se preocupe se esqueceu de recolocar a tampa. O STABILO BOSS ORIGINAL pode ser facilmente recarregado após períodos de uso intenso.', 80.0, 54.96, NULL, 'Stationery > Writing & Correction > Pens & Inks', 'https://cf.shopee.com.br/file/sg-11134201-81zu9-mmw28x0piltyac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F721033344%2F28394564463', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
