INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43050367907', 'Livro A Saga Wingfeather | O Monstro Nos Vales | Andrew Peterson', 'Livro A Saga Wingfeather O monstro nos vales. GUERREIROS BARBUDOS. FRUTAS GOSTOSAS. E O SEGREDO MORTAL DA COLINA DA CHAMINÉ. O Reino de Anniera caiu, e a família real está fugindo. Perseguidos incansavelmente pelos exércitos de Fangs, liderados por Gnag, o Sem-Nome, Janner e sua família aguardam encontrar refúgio no último lugar seguro do mundo: Vales Verdes, uma terra de frutas deliciosas, corajosamento protegida por guerreiros temidos até mesmo pelos Fangs de Dang. Mas um novo problema ameaça a esperança da família Igiby por paz: o irmão mais novo de Janner, Kalmar ? herdeiro do trono de Anniera ?, agora tem um rabo. E pelagem cinza. Isso para não falar das duas orelhas pontudas e compridas, ou das perigosas garras. Para o povo desconfiado de Vales Verdes, ele se parece com um monstro. Janner, porém, sabe que ele não é tal coisa. Seu irmão não é tão assustador quanto parece. Kalmar é perfeitamente inofensivo. Será mesmo? O terceiro livro da premiada A Saga Wingfeather leva a família Igiby ? e seus leitores ? a uma nova e arrebatadora aventura, cheia de mistérios, traições e dissimulações. Há um monstro em Vales, e a verdade espreita pelas sombras. ANDREW PETERSON é cantor e compositor aclamado pela crítica e pelo público, além de ser o autor da premiada A Saga Wingfeather. É também o fundador da Rabbit Room, uma organização que nutre comunidades por meio de histórias, arte e música. Ele e sua esposa, Jamie, têm três filhos e vivem em Nashville, nos EUA. Especificações do livro A Saga Wingfeather Título: A Saga Wingfeather Subtítulo: O Monstro Nos Vales Autor(es): Andrew Peterson Ano de Edição: 2022 Capa: Brochura Acabamento: Laminação Fosca com Verniz Localizado Miolo: Papel Pólen 70g Páginas: 328 Dimensões: Altura: 23 cm Largura: 16 cm Profundidade: 2,0 cm Peso: 0,580 kg ISBN: 9786589129394 Editora: Trinitas', 58.54, 58.54, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m9jbsgixghtl4c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F43050367907', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19207532460', 'As Armadilhas Do Inimigo | Bob Sorge', 'As Armadilhas Do Inimigo Como lidar com a rejeição e o louvor dos homens Como lidar com a rejeição e o louvor dos homens rejeição muitas pessoas foram devoradas por seu estrago e a maioria também a distribuiu louvores de homens os sinistros tentáculos do louvor do homem buscam constantemente desqualificar os servos de Deus de sua mais alta herança rejeição e bajulação são como barrancos gêmeos que percorrem a estrada estreita da santidade Cada passo conta Para jesus as opiniões dos homens eram insignificantes à luz da afeição exuberante e da aprovação apaixonada do Seu Pai aprenda como manter seu coração diante de Deus de um modo que agrade a ele em meio à rejeição e ao louvor das pessoas A questão da rejeição é um dos problemas fundamentais que o ser humano tem experimentando Quando o Espírito Santo levanta ministérios destemidos antes da segunda vinda de Cristo ele que capacitar seu povo a andar em um amor ousado que acompanha a busca do Senhor de uma maneira sincera Bob Sorge tem experiência nesta dimensão vital da graça de Deus e escreve de uma maneira clara e útil Mike Bickle Diretor da casa internacional de oração Kansas City Missouri Ler este livro é uma obrigação para aqueles que desejam conhecer a verdadeira maturidade espiritual Paul Johansson Chanceler Instituto Bíblico Elim Lima Nova Iorque Há épocas em que Deus libera um livro para ajudar seus filhos a crescerem e alcançarem a estatua de Cristo Este é um daqueles livros! Curto e convincente leia e passe para os outros Larry Tomczak Líder cristão Rejeição Muitas pessoas foram devoradas por seu estrago e a maioria também a distribuiu Loures de Homens Os sinistros tentáculos do louvor do homem buscam constantemente desqualificar os servos de Deus de sua mais alta herança Rejeição e bajulação Bob Sorge mora em Kansas city Missouri EUA onde é membro da casa internacional de oração Ele carrega uma paixão pelo reavivamento das igrejas e a intimidade pessoal com jesus que caracteriza todos os seus livros Título As Armadilhas Do Inimigo Edição Como lidar com a rejeição e o louvor dos homens Autor Bob Sorge Páginas 120 Formato 21 × 14 × 1 cm Peso 0 372 kg ISBN 9788576071709 Editora Atos', 23.21, 23.21, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/05f9eb9924c0fe4920da9337ce8ca5ca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F19207532460', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
