INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19198010083', 'Aquarela - Livro De Colorir - Dinossauro', 'Sabemos que as crianças amam pintar, então olha novidade incrível, imagina pintar com aquarela, nessa coleção você encontra além de desenhos incríveis, aquarelas lindos para colorir. É só colocar água em cima da tinta e se divertir muito, aproveite! 27x28cm 16 Páginas', 14.9, 12.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rff9-m4cg941kzj0kb1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F19198010083', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20777581534', 'Bíblia Sagrada | NVI | Leitura Perfeita | Letra Grande | Couro Soft | Verde', 'A Bíblia Coral Floral é a escolha perfeita pra quem quer uma NVI com letra grande sem abrir mão de uma capa feminina e delicada. A capa além de linda, possui uma base de látex interna que a torna muito mais flexível e durável, prevenindo rachaduras. O material é uma junção de duas peças de courosoft (PU), um verde costurado em outro coral texturizado. Além de dar aquele charme a mais ainda temos um toque aveludado que agrega leveza ao manuseio. Essa bíblia possui linguagem NVI (Nova Versão Internacional) que é baseada nos seguintes fundamentos: precisão, beleza de estilo, clareza e dignidade, trazendo uma versão ao mesmo tempo fiel e contemporânea. Nela, você encontrará ainda a fonte Leitura Perfeita. Desenvolvida exclusivamente para a Thomas Nelson Brasil, a Leitura Perfeita é uma fonte singular, moderna, bonita, clara e legível, ao mesmo tempo em que integra os melhores avanços em tipografia de bíblias modernas. O resultado é uma tipologia que traz total conforto na leitura em qualquer tamanho. Características: Texto na tradução NVI (Nova Versão Internacional)Capa em courosoft (PU)Base interna de látex para maior durabilidade e flexibilidadeDuas cores e texturas de capa (Verde e Coral)Fonte Leitura PerfeitaLetra tamanho grandeLombada costurada para total aberturaFitilho colorido 1600 Páginas 14x21cm', 101.9, 101.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7qvez-lf7s4ox3zsawbb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F20777581534', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8012552145', 'Vislumbres da Graça | FIEL', 'Deus se importa com as pequenas coisas do seu dia a dia? Às vezes, a vida parece um fardo. São sempre as mesmas tarefas e obrigações, desafios e desencorajamentos, ansiedades e responsabilidades. Todas as mulheres já experimentaram essa sensação, seja uma mãe, dona de casa ou uma mulher que trabalha fora, dividindo tempo entre o trabalho e o lar. Porém, este livro irá encorajar suas leitoras a enxergar a realidade da graça de Deus naquelas áreas do dia a dia que parecem entediantes e sem importância. Através de exemplos pessoais e histórias cativantes, a autora apresenta reflexões ricamente bíblicas que irão ajudar a leitora a experimentar o poder extraordinário do evangelho em sua vida cotidiana. 256paginas 21x14cm', 48.9, 47.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/98b7bb62d943d4db3859192c4046cfe4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F8012552145', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
