INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594459449', 'Pack Energético Baly Energy Drink Maçã Verde 2l', 'A Baly é a maior marca brasileira de energéticos, pioneira e líder no Brasil em embalagens 2L, e o Maçã Verde 2L é leve, autêntico e cheio de frescor, perfeito para quem busca equilíbrio e energia. Com o sabor leve e refrescante da maçã verde, cada porção traz intensidade com Taurina, Cafeína e Vitaminas do Complexo B. Seja na resenha com os amigos, pegando aquele solzão na praia, virando a noite no game ou encarando a semana de provas, Baly tá sempre com você! Perfeito para compartilhar com a galera ou celebrar em família, o Baly Energy Drink Maçã Verde na litragem 2L oferece mais quantidade e energia, mantendo o sabor e a brasilidade que só a Baly entrega. Nascemos no Carnaval, da mistura que só o Brasil tem, e cada lata carrega essa energia única e vibrante. Também disponível na versão Zero Açúcar Produto não alcoólico', 89.0, 76.54, NULL, 'Food & Beverages > Beverages > Energy & Isotonic Drinks', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfjvzq135s07a6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1618156944%2F23594459449', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
