INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793417448', 'Kit Filtros Ford Ka 2014 até 2018 + Higienizador AL2504 CES1108', 'Kit de Filtros e Higienizador para Ford Ka (2014 a 2018) AL2504 CES1108 GRANADA Mantenha seu Ford Ka (modelos de 2014 a 2018) sempre em excelente condição com este kit completo, que inclui filtros de ar, filtros de ar condicionado e um higienizador automotivo tipo "granada" para limpeza interna. Ideal para garantir o bom funcionamento do sistema de ventilação e a qualidade do ar dentro do veículo. O kit contém: Filtro de ar: Proporciona proteção eficiente ao motor, evitando a entrada de poeira e partículas prejudiciais, garantindo uma melhor queima de combustível e maior durabilidade do motor. Filtro de ar condicionado: Purifica o ar que circula no habitáculo do veículo, removendo partículas de poeira e poluentes, garantindo um ambiente mais saudável e agradável para os ocupantes. Higienizador automotivo ("granada"): Produto específico para higienização do sistema de ar condicionado e do interior do veículo. Elimina odores e bactérias, promovendo um ar mais limpo e fresco para os passageiros. Este kit é perfeito para manter a qualidade do ar dentro do veículo, além de garantir o bom funcionamento dos filtros, promovendo saúde, conforto e eficiência para o seu Ford Ka.', 69.99, 69.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m143htvk24we08', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1021060335%2F22793417448', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
