INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9770358810', 'Livro - Estrelas mágicas - Capa comum - Ciranda Cultural', 'Joana gostava de céu azul, da luz do sol. Viajar à noite significava passar muito tempo no escuro. E ela tinha medo do escuro. Ela e sua gata Duquesa. Clarice, avó de Joana, resolveu contar a ela uma história que ouvira havia muito tempo, sobre como as estrelas iluminavam o céu. Um livro sensível, para ser saboreado a cada página, Estrelas mágicas é uma grande celebração à capacidade e beleza do amor. Editora: Ciranda Cultural Edição: 1, 2020 Autor: Walter Sagardoy Idioma: Português Páginas: 32 Dimensões: L 24.00 x A 24.00 x E 0.30 ISBN: 9786555001600', 39.9, 39.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/d7b95769c44edea6400c00090399d369', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F9770358810', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
