INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207596546', 'Ração Quatree Supreme Gatos Castrado Senior +7 Frango + 10kg', 'DESCRIÇÃO: QUATREE SUPREME GATOS CASTRADO SENIOR +7 10.1KG A Quatree Supreme Gato Castrado Sênior +7 (10,1kg) é uma ração Super Premium desenvolvida para gatos castrados com mais de 7 anos. Com sabor salmão e frango, foca na saúde renal, cardíaca (taurina/L-carnitina) e controle de peso, sendo livre de transgênicos, com conservantes naturais e baixo nível de sódio/fósforo. Principais Benefícios e Características: Saúde Sênior e Estrutural: Enriquecida com sulfato de glicosamina e condroitina para suporte articular, além de antioxidantes para o sistema imunológico. Controle de Peso e Trato Urinário: Fórmula com teor de gordura moderado e fibras (lignocelulose) para saciedade, auxiliando no peso ideal. Inclui controle de pH urinário. Gestão de Bolas de Pelo: Fibras especiais ajudam a reduzir a formação de bolas de pelos no trato digestivo. Nutrição Natural: Ingredientes de alta digestibilidade (farinha de salmão, frango, batata-doce) e sem corantes ou aromatizantes artificiais. Redução de Odor: Extrato de yucca reduz o odor das fezes.', 416.65, 239.77, NULL, 'Pets > Pet Food > Cat Food', 'https://cf.shopee.com.br/file/sg-11134201-8260k-mm8z4vym91xfcb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1009890604%2F58207596546', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
