INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20751863690', 'Amortecedor de Porta Malas Porta Traseira Punto 2007 até 2016', '***AS MARCAS PODEM VARIAR CONFORME A DISPONIBILIDADE EM ESTOQUE*** O amortecedor mola a gás da tampa no porta malas é um componente responsável na sustentação dessa tampa por auxiliar na abertura e amortecimento evitando grandes impactos. Ele também funciona como uma espécie de limitador e suavizado de movimento, evitando desgaste e quebra das dobradiças. Seu formato é semelhante ao encontrado no sistema de suspensão do veículo, porém, normalmente tem diâmetros menores e comprimentos maiores. Esse modelo de amortecedor possui movimento mais suave e constante por usar o gás nitrogênio injetado sob pressão, que garante durabilidade e vida mais longa. Quando você abre a tampa do porta malas, o nitrogênio empurra uma haste metálica ligada a ela, o que facilita sua abertura — desse modo não é preciso fazer tanta força. Ao soltar a tampa, o nitrogênio mantém essa força e evita que a tampa feche sozinha. Quando você a força para baixo, comprime novamente o nitrogênio, levando a haste metálica de volta à posição inicial. Amortecedor de Porta Mala Punto 2007 até 2016 Informações técnicas Ano: Punto 2007 até 2016 Posição: Tampa traseira Medida Aberto de Ponta a Ponta: 45,5 cm Itens inclusos: 1 Amortecedores Tampa Traseira Punto', 34.99, 34.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/1128aed5a76b74932b451236e4c96bd2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341544056%2F20751863690', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
