INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23892558757', 'Limpeza Pesada Porcelanato 1lt Hidrorepel - Limpador / Remov', 'Limpeza Pesada PorcelanatoDetergente para limpeza pesada e pós-obra de porcelanatos polidos e esmaltados Vantagens Limpa profundamente os porcelanatos impregnadas Remove manchas e limo Atua na sujeira do substrato causadas no uso do dia-a-dia Limpeza pós-obra dos restos de cimentos e argamassas provenientes de construção ou reforma Prepara a superfície para tratamento com seladores, hidrofugantes, oleofugantes e agentes de proteção. Aplicação Áreas internas e externas. Superfícies novas ou já em uso. Superfícies Porcelanatos polido Porcelanatos esmaltados Cerâmica esmaltada Rendimento Pode ser usado puro ou diluído na proporção de 1:1 a 1:10 Limpezas profundas – 30 m²/L. Limpezas leves – 200 m²/L. A diluição influencia na limpeza, por isso teste a quantidade diluída numa pequena área, para verificar os resultados desejados. Importante: Este produto não deve ser utilizado ou ter contato com pisos cimentícios, mármores e pedras calcarias. Caso necessário, aplicação em ambientes, cujo esteja aplicado um desses produtos, proteger, isolando com fita ou plástico, para evitar o contato com o mesmo.', 54.32, 35.31, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-7rcdr-ls31t029ds76be', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1190424233%2F23892558757', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
