INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259467439', 'Borges Azeite de Oliva Extra Virgem', 'Descubra o sabor autêntico da Espanha com o Azeite de Oliva Extra Virgem Clássico Borges. Extraído das melhores azeitonas, este azeite é perfeito para elevar o sabor de suas receitas, sejam elas saladas, carnes ou peixes. Com um grau de acidez ideal, ele garante um toque suave e uma presença marcante em qualquer prato. Ideal para ser armazenado ao abrigo do calor, em temperatura ambiente, seco e ao abrigo da luz. Não contém glúten.', 37.49, 37.49, NULL, 'Food & Beverages > Cooking Essentials > Oil', 'https://cf.shopee.com.br/file/sg-11134201-8259g-mqnem2rbzcao95', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554958%2F58259467439', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22099170154', 'Agua Bi Desmineralizada Radiador E Bateria Orbi 12873', 'Água Bi-Desmineralizada ORBI para baterias e radiadores é industrializada através de processos modernos e eficientes. Recomendada para uso em baterias e radiadores automotivos de veículos leves e pesados, motos, linha agrícola e linha náutica. Características: Condutividade elétrica, inferior a 9 microsiemens. Isenta de sais minerais, ferro, cálcio e magnésio. Modo de usar: Utilizar como parte na preparação do aditivo de radiador, misturando com o aditivo antes da adição no sistema, Pode ser usada pura, para completar o nível de água do radiador. Usar 1/1, ou seja, para cada 1 litro do Aditivo para Radiador, será usado 1 litro de água Bi-desmineralizada. Em baterias elétricas use apenas água bi-desmineralizada para preencher as células. Se os níveis de eletrólitos nas células estiverem baixos, ou seja, se as placas estiverem expostas, preencha só para cobri-las. Precauções: Produto químico não classificado como perigoso de acordo com a ABNT NBR 14725-2. Não reutilizar a embalagem. Em contato com a pele ou olhos, lave em água corrente por alguns minutos. EM CASO DE INGESTÃO: Contate imediatamente um CENTRO DE INFORMAÇÃO TOXICOLÓGICA (CEATOX 0B00 014 81 10) ou médico levando a embalagem do produto. MANTENHA O PRODUTO FORA DO ALCANCE DE CRIANÇAS E ANIMAIS DOMÉSTICOS. Composição: Agua Bi-Desmineralizada, Validade: 36 meses após a data de fabricação. Lote e fabricação impressos na embalagem.', 9.99, 9.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-821g0-mgi274drqarx18', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F888889365%2F22099170154', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
