INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20098881121', 'Esmalte Risqué Cintilante Platino', 'Toda a linha de esmaltes Risqué Rosas Cintilantes, além de apresentar textura única e brilho perolado, acompanha as tendências da moda, possibilitando diversas composições de looks e maximizando a beleza da sua maquiagem e acessórios. Com secagem rápida, use a sua imaginação e crie lindas nails art que farão sucesso aonde quer que você vá. Com fórmula especial, livre de componentes que costumam causar alergias, o Esmalte Risqué é perfeito para os cuidados diários. Apaixone-se pela cor, presencie a longa duração e viva a beleza de suas unhas de forma única com os Esmaltes Risqué Cintilante. Modo de usar: Com as unhas limpas, aplique uma ou duas camadas do esmalte, de acordo com a intensidade desejada. #html-body [data-pb-style="646BA6481C8C2"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA6481C8D6"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 16.63, 16.63, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-7rbk0-lkuy1x4hbv3cff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F20098881121', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23196737398', 'Hastes Flexíveis Minná Tradicional c/150un', 'As Hastes Flexíveis Minná são as suas aliadas na higiene diária de toda a família. Com tamanho e maciez ideal para a limpeza das orelhas, umbigo e nariz. Possuem bactericida em sua formulação, evitando contaminações. As pontas em 100% algodão não soltam fiapos e são muito higiênicas. Versáteis, elas também podem ser usadas para a aplicação de medicamentos e na hora de retocar a maquiagem. Modo de uso: Deve ser utilizado através de um leve contato com a área desejada, normalmente sendo aplicado com os seus dois lados aderentes, assim realizando seu desejo de forma rápida e fácil. #html-body [data-pb-style="646BA64B63693"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA64B636A8"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 19.65, 19.65, NULL, 'Health > Personal Care > Ear Care', 'https://cf.shopee.com.br/file/sg-11134201-7rbkg-lm7htq8qlzrff1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F23196737398', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19598989963', 'Tonalizante Light Color 1.0 Preto Azulado', 'Tintura Light Color foi especialmente elaborada com os incríveis Óleo de Coco e Óleo de Macadâmia, a fórmula de Light Color faz um verdadeiro milagre nos fios: Colore e trata seu cabelo de forma suave e SEM AMÔNIA. E o melhor, Light Color é um produto liberado! Pode se jogar nessa mudança! Modo de Uso : Antes de usar, faça o Teste de sensibilidade/ Prova de toque (vide folheto explicativo) 48 horas antes de cada utilização deste produto. Opção I - Cabelos Naturais Nunca coloriu os seus cabelos Última aplicação de coloração há mais de 3 meses. Preparação da mistura: Desembarace e molhe os cabelos com água, sem lavá-los, Enxugue-os cuidadosamente. Caso os cabelos possuam resíduos de gel, mousse, etc ou estejam oleosos, lave-os com shampoo. Coloque as luvas, Com um pincel, misture bem em um recipiente não metálico o conteúdo da bisnaga de coloração Light Color de 45g com 90ml de Emulsão Ativadora Salon Line até obter uma consistência homogênea e cremosa. Utilize a mistura imediatamente e não guarde sobras. Aplicação / Tempo de ação: Aplique a mistura uniformemente nos cabelos mecha por mecha, na raiz, comprimento e pontas. Para cabelos: Finos, Louros, Avermelhados, Permanentados, Alisados e Relaxados Deixe a mistura agir por 15 minutos. Para cabelos: Normais, Grisalhos e Escuros Deixe a mistura agir por 20 minutos. Após o tempo de ação, enxágue abundantemente até que a água corra límpida. Não é necessário usar shampoo. Aplique o Condicionador Salon Line. E deixe agir por 3 minutos. Enxágue abundantemente. Opção II - Cabelos já coloridos. Preparação da mistura: Desembarace e molhe os cabelos com água, sem lavá-los. Enxugue-os cuidadosamente. Caso os cabelos possuam resíduos de gel, mousse, etc ou estejam oleosos, lave-os com shampoo. Coloque as luvas, Com um pincel, misture bem em um recipiente não metálico o conteúdo da bisnaga de coloração Light Color de 45g com 90ml de Emulsão Ativadora Salon Line até obter uma consistência homogênea e cremosa. Utilize a mistura imediatamente e não guarde sobras. Aplicação / Tempo de ação: Aplique na raiz dos cabelos por 15 minutos e no comprimento e pontas somente nos últimos 5 minutos, totalizando o tempo de ação de 20 minutos. Para cabelos: Finos, Louros, Avermelhados, Permanentados, Alisados, Relaxados, Normais, Grisalhos e Escuros. Após o tempo de ação, enxágue abundantemente até que a água corra límpida. Não é necessário usar shampoo. Aplique o Condicionador Salon Line. E deixe agir por 3 minutos. Enxágue abundantemente. #html-body [data-pb-style="646BA6467EAEE"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA6467EB03"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 26.38, 26.38, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-7rbmb-lmgggvivl4p1ef', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F19598989963', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
