INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18197424114', 'Tonalizante Keraton Men Cinza Natural', 'O tonalizante Keraton MEN com Ormagel XPU é uma coloração semipermanente que foi desenvolvido com um exclusivo blend de algas marinhas, rico em biopolimeros hidratantes e protetores que auxiliam no tratamento dos cabelos, atuando nos fios como um filme protetor da cor. Keraton Men tonaliza suavemente os fios brancos realçando a cor dos cabelos devolvendo-lhes uma aparência natural e saudável. Modo de uso: Proteja a roupa com uma capa ou toalha. Faça a aplicação nos cabelos secos. Não é necessário lavá-los a não ser que possuam resíduos de produtos finalizadores. Aplique a mistura nos cabelos começando pela lateral, ou onde houver maior concentração de fios brancos. Em seguida espalhe por todo o cabelo uniformemente e massageie suavemente. Importante: A aplicação deve acontecer em no máximo 3 minutos. Após a aplicação deixe o produto agir por mais 5 minutos, marque no relógio. Para uma cobertura mais intensa dos fios brancos mais resistentes, deixe o produto agir no máximo até 10 minutos.Terminado o tempo de pausa, enxágüe com água morna em abundancia e lave com o shampoo de sua preferência.', 55.77, 55.77, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-7rbnf-lmggg8smuj4qc4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F18197424114', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
