INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203296796', 'Quem Disse, Berenice? Batom Líquido Vinheli 4ml', 'A linha Instamatte Quem Disse, Berenice? Oferece acabamento mate e longa duração. Quem Disse, Berenice? Batom Líquido Vinheli possui nova fórmula com textura fina, alta pigmentação e conforto, deixando os lábios aveludados por horas. Sua cor é um vinho sofisticado que nunca sai de moda. Com duração de até 6 horas, cobertura mate confortável, secagem rápida e sem ressecamento, é vegano e dermatologicamente testado. Não acumula nos vincos, realçando a beleza natural dos lábios. Prático e estiloso, é a escolha ideal para uma produção rápida e impecável. Nenhum produto Quem Disse, Berenice? é Testado em animais, ou seja, este item possui selo Cruelty Free. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 49.9, 49.9, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134201-8262d-mjhfbmbr16v8bf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1671118112%2F58203296796', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
