INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26344160009', 'Porta Mantimento Lyor Vegas de Vidro com Tampa Preto 2,3L', 'Porta Mantimento Lyor Vegas de Vidro com Tampa Preto 2,3L O Porta Mantimento de Vidro com Tampa em Metal Vegas Preta de 2,3L da Lyor é uma escolha elegante e funcional para armazenar mantimentos com estilo e eficiência. Capacidade de 2,3LCom uma capacidade generosa de 2,3L, o porta mantimento é ideal para armazenar porções significativas de mantimentos, como grãos, massas, arroz, entre outros. Design EleganteO design elegante do porta mantimento confere um toque refinado à sua cozinha, tornando-o uma peça versátil para diferentes estilos de decoração. Versatilidade de UsoAlém de mantimentos secos, o porta mantimento pode ser utilizado para armazenar outros itens, como doces, biscoitos, ou até mesmo objetos não alimentícios. Fácil de LimparO vidro facilita a limpeza, e a tampa em metal Vegas preta pode ser removida para uma higienização completa. O Porta Mantimento de Vidro com Tampa em Metal Vegas Preta de 2,3L da Lyor é uma adição funcional e estilosa à sua cozinha, proporcionando um armazenamento seguro e elegante para seus mantimentos. Lyor - Soluções completas para o seu Lar. Contém: 1 Pote Lava Louça: Não Microondas: Não Forno: Não Fogão: Não Freezer: Não Medidas Produto: Altura 24,10cm x Largura 11,70cm x Comprimento 11,70cm Peso: 0,86Kg Cor: Preto Material: Acrílico Capacidade: 100ml Lavar com detergente neutro, esponja macia e secar imediatamente. Não lavar em máquinas, não utilizar produtos químico.', 55.0, 38.99, NULL, 'Home & Living > Decoration > Others', 'https://cf.shopee.com.br/file/sg-11134201-8262l-mk1c8t36kefbee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F869809385%2F26344160009', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47254762920', 'Conjunto 9 Porta Temperos com Suporte Lyor Bege Vidro', 'Conjunto 9 Porta Temperos com Suporte Lyor Bege Vidro Produto funcional com forte apelo visual para vitrines organizadas, kits gourmet e campanhas de cozinha prática. O conjunto com 9 potes e suporte bege oferece equilíbrio entre estética clean e utilidade cotidiana. Produto funcional com forte apelo visual para vitrines organizadas, kits gourmet e campanhas de cozinha prática. O conjunto com 9 potes e suporte bege oferece equilíbrio entre estética clean e utilidade cotidiana. Alta Percepção de Valor e Boa Rotatividade Vidro + suporte = combinação visual que atrai consumidores que valorizam funcionalidade com design. Ideal para Ações de Organização e Curadoria de Lar Excelente para vendas sazonais, kits presenteáveis e espaços com proposta prática. Tamanho Comercial com Apelo Modular Compacto, fácil de expor e com excelente desempenho em campanhas de renovação de cozinha. Lyor – Produtos que organizam, encantam e geram resultado. Contém: 9 Porta Temperos Medidas Produto: Altura 19,50cm x Largura 18,50cm x Comprimento 18,50cm Peso: 1,26Kg Lavar com água corrente e detergente neutro, escorrer toda água antes de guardar. Não lavar em máquinas, não utilizar produtos químico.', 124.0, 97.99, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-8262e-mk15eswxokqv6d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F869809385%2F47254762920', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57358520916', 'Camisa Corinthians Masculina Logo Bordado Preta Licienciado', 'Camisa Corinthians Coimbra Masculina Oficial Algodão com Escudo Bordado Mostre sua paixão pelo Timão com a Camisa Corinthians Coimbra Masculina, perfeita para torcedores que valorizam conforto, estilo e identidade. Com escudo bordado no peito e design esportivo, essa peça se destaca tanto nas arquibancadas quanto no dia a dia. A camisa combina modernidade e tradição, trazendo um visual marcante e cheio de personalidade para quem carrega o manto alvinegro. Produzida em 95% algodão e 5% poliéster, oferece toque macio, boa respirabilidade e conforto térmico, ajudando a manter o corpo agradável mesmo em dias mais quentes. Seu caimento confortável garante liberdade de movimentos para diversas ocasiões. Características do produto Contém: 1 camisa masculina Modelo: Corinthians Coimbra Composição: 95% Algodão e 5% Poliéster Gola: Careca Manga: Curta Escudo bordado no peito Estilo: Casual / Esportivo Caimento confortável Indicado para: Dia a dia, jogos e lazer Produto oficial Indicação de uso Dias de jogo Uso casual Torcedores do Corinthians Atividades do dia a dia Ao adquirir produtos na Sloth, você garante qualidade, durabilidade e originalidade. Todos os produtos são comercializados com autorização da marca e acompanhados de nota fiscal. Seu pedido será processado e enviado em até 24 horas após a aprovação do pagamento. Caso ocorra qualquer imprevisto, você será informado imediatamente. Em casos de defeito de fabricação, oferecemos 30 dias para devolução, com reembolso após confirmação do problema. Os custos de envio em devoluções por defeito são totalmente cobertos pela Sloth. 7 dias para devolução por desistência após o recebimento do produto', 184.9, 139.9, NULL, 'Men Clothes > Tops > T-Shirts', 'https://cf.shopee.com.br/file/sg-11134201-81ztg-mmuuwxxkldl190', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322737721%2F57358520916', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46359337462', 'Camisa Infantil Corinthians Braziline Lumina', 'Camisa Corinthians Infantil Lumina A Camisa Corinthians Infantil Lumina, desenvolvida pela Braziline, é uma peça licenciada oficialmente que une a paixão pelo clube ao conforto ideal para o dia a dia e a prática esportiva. Produzida em poliéster de alta tecnologia, a camisa oferece leveza e excelente mobilidade, permitindo que as crianças se movimentem com liberdade. Além disso, o material auxilia na rápida evaporação do suor, mantendo o corpo seco mesmo em dias mais quentes, e garante alta durabilidade, resistindo ao uso frequente e às lavagens sem perder a qualidade. Seu design clássico valoriza a tradição alvinegra, com escudo aplicado em alta definição que assegura nitidez e resistência ao desgaste. A gola careca conta com reforço interno, proporcionando mais conforto e evitando irritações, além de ajudar a manter o formato original da peça ao longo do tempo. A camisa se ajusta ao corpo infantil de forma equilibrada, sem apertos ou excessos. P Características: Contém: 1 Camiseta Infantil Corinthians Lumina Categoria: Infantil / Juvenil. Composição: 100% Poliéster. Tipo de Manga: Curta. Gola: Redonda (Careca). Escudo: Detalhes: Escudo oficial do Corinthians termo aplicado no peito Dimensões Aproximadas: 4: 46 x 35cm 6: 50 x 38cm 8: 54 x 41cm 10: 58 x 44cm 12: 62 x 47cm 14: 66 x 50cm Ao adquirir produtos na Sloth, você está garantindo qualidade, durabilidade e originalidade. Todos os itens são comercializados com autorização da marca e acompanhados de nota fiscal. Seu pedido será processado e enviado em até 24 horas após a aprovação, com comunicação imediata em caso de imprevistos. O prazo de garantia para produtos que venham a apresentar problemas de fabricação é de 90 dias após o recebimento.', 139.9, 99.99, NULL, 'Men Clothes > Tops > T-Shirts', 'https://cf.shopee.com.br/file/sg-11134201-820mw-mnd063unylfmd3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322737721%2F46359337462', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47759985743', 'Desodorizador Glade Automatic Spray Aparelho + Refil Toque de Maciez 260ml', 'Glade Automatic Spray te ajuda a deixar o ambiente mais aconchegante através de fragrâncias infundidas com óleos essenciais. O aparelho desenvolvido para complementar a decoração de qualquer ambiente é alimentado por pilha e libera automaticamente um spray discreto, de acordo com o ajuste de tempo de sua escolha. São até 60 dias de spray de fragrância, quando programado para liberação a cada 36 minutos. Não é necessário ligá-lo na tomada, basta programar e colocá-lo no cômodo desejado para aproveitar o conforto e perfume proporcionado.', 90.35, 90.35, NULL, 'Pets > Litter & Toilet > Diapers', 'https://cf.shopee.com.br/file/sg-11134201-823r7-moievw2ij66bf1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683952730%2F47759985743', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
