INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7253688608', 'KIT Shampoo + Condicionador Engrossador Tio Nacho 415ml - 2 ITENS', 'Shampoo + Condicionador Engrossador 415ml Tio Nacho O Shampoo Tio Nacho Engrossador contém exclusiva combinação de Geléia Real com Capilgross e extratos de origem natural, que aumentam a espessura do fio e evitam a queda, proporcionando cabelo mais forte, volumoso e saudável. Modo de usar: 1) Aplique sobre o cabelo molhado, distribuindo generosamente, fazendo uma leve massagem no couro cabeludo; 2) Enxágue e repita a operação. 3) Para potencializar os resultados, use toda a linha Tio Nacho Engrossador. O Condicionador Tio Nacho Engrossador contém exclusiva combinação de geléia real com Capilgross e extratos de origem natural, que aumentam a espessura do fio e evitam a queda, proporcionando cabelo mais forte, volumoso e saudável. Modo de usar: Após o uso do shampoo, aplique sobre todo o comprimento dos fios, até as pontas. Deixe agir por um minuto e enxágue. Benefícios: - Proporciona um aumento na espessura dos fios, fortalece e revitaliza o couro cabeludo; - Além disso, devolve o brilho e a força dos cabelos opacos e quebradiços. Indicado para cabelos com pouco volume.', 79.9, 79.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-7r98p-lmoyad8bj6raf2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290598330%2F7253688608', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
