INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23311479319', 'Par Amortecedor Dianteiro Cofap SANDERO 1.6 2014 2015 2016 2017 2018 2019 2020 2021', 'PAR DE AMORTECEDORES DIANTEIROS LINHA SANDERO / LOGAN PRODUTO NOVO ORIGINAL COFAP TURBOGÁS COM NOTA FISCAL ATENÇÃO,NÃO SERVE NO MODELO STEPWAY CARACTERÍSTICAS - Código do fabricante: GP30579 - Aplicação: Dianteiro - Lado: Esquerdo / Direito - Modelo Turbogás: O amortecedor Turbogás da Cofap possui, além do óleo, um gás em seu interior, o que evita a formação de bolhas de ar (cavitação), comum em situações de solicitação extrema, que leva à perda de eficiência do amortecedor. Proporciona maior rendimento, conforto e estabilidade. Aplicação: SANDERO 1.0 2014 2015 2016 2017 2018 2019 2020 2021 SANDERO 1.6 2014 2015 2016 2017 2018 2019 2020 2021 LOGAN 1.0 2014 2015 2016 2017 2018 2019 2020 2021 LOGAN 1.6 2014 2015 2016 2017 2018 2019 2020 2021 ITENS INCLUSOS NA EMBALAGEM: 02 AMORTECEDORES GP30579 GARANTIA DO PRODUTO - A troca ou desistência desse item pode ser feita em até 7 dias corridos a partir do recebimento do produto. - Os amortecedores possuem 24 meses de garantia contra defeito de fabricação diretamente com o fornecedor. Para a garantia, é importante manter o certificado de qualidade com o selo do código de barras (vide embalagem). ATENÇÃO - A EMPRESA não se responsabiliza pelo mau uso ou instalação indevida do produto, sempre recomendamos que a instalação seja feita por um profissional especializado. - Imagens meramente ilustrativas.', 993.0, 893.7, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/br-11134201-22120-9a5mz2wwk5kv7f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442403193%2F23311479319', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256911840', 'Penteadeira 2 Portas 4 Gavetas com Visor de Vidro Studio Albatroz', 'Penteadeira Studio Albatroz: ideal para quem busca mais organização, praticidade e um toque moderno no quarto. Com 2 portas, 3 gavetas e visor de vidro, essa penteadeira oferece excelente aproveitamento interno para organizar maquiagens, acessórios e itens pessoais. O tampo com vidro facilita a visualização dos objetos armazenados, trazendo mais praticidade para o dia a dia, além de valorizar o design do móvel com um visual mais elegante e funcional. Produzida em MDP com acabamento em pintura UV, a peça combina durabilidade e fácil manutenção. Seu design versátil permite integrar diferentes estilos de decoração, tornando o ambiente mais harmonioso e bem distribuído, além de contribuir para uma rotina mais organizada e eficiente. Manutenção e cuidados: limpar com pano macio e seco, evitar produtos abrasivos, não colocar peso excessivo sobre o vidro, proteger da umidade, manter em local seco e arejado. Item: Penteadeira com visor de vidro Marca: Albatroz Linha: Studio Quantidade de portas: 2 Quantidade de gavetas: 3 Material principal: MDP Acabamento: Pintura UV Tampo: Com visor de vidro Tipo de peça: Penteadeira Estilo: Moderno Dimensões do produto: Altura: 133 cm Largura: 105 cm Profundidade: 40 cm Peso: 37,7 Kg Garantia: 3 meses', 799.9, 799.9, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/br-11134207-820lj-mls1fy25roxyec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1243712796%2F58256911840', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
