INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21899262806', 'CLOSEUP CREME DENTAL AÇÃO PROFUNDA LIQUIFRESH ICE COM 100G', 'Closeup Liquifresh Ice 100g: Gelo Refrescante, Hálito Extra Forte e Dentes Brancos O Creme Dental Closeup Liquifresh Ice de 100g é para quem busca um hálito fresco que dura mais e dentes visivelmente mais brancos. Sua fórmula em gel líquido penetra mais fundo, oferecendo uma limpeza interdental mais eficaz e um sabor intenso de Hortelã Ice com efeito resfriante. Com flúor e micropartículas, o Liquifresh Ice ajuda a remover as manchas superficiais, protegendo contra cáries e fortalecendo o esmalte. É ideal para quem quer um hálito que impressiona e um sorriso naturalmente mais branco. Destaques Closeup: Ação Profunda: Gel que limpa em áreas de difícil acesso. Hálito Fresco Extremo: Sabor Hortelã Ice para frescor máximo. Branqueamento: Ajuda a remover manchas superficiais. 100g: Tamanho ideal para o uso diário da família. Escove os dentes por pelo menos dois minutos, após cada refeição. Atitude e frescor garantidos. Prepare-se para Closeups!', 27.74, 27.74, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-7rd40-lvnl766umps64e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1251200960%2F21899262806', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
