INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42456743624', 'Sapateira multifuncional 3 Níveis para 20 Pares de Sapatos e Calçados - Móveis Bonatto', 'Sapateira 3 Portas Espaçosa com Prateleiras – Móveis Bonatto A Sapateira 3 Portas da Móveis Bonatto é perfeita para quem busca mais organização no dia a dia sem abrir mão de um design moderno e funcional. Fabricada em MDP de alta qualidade, oferece ótimo espaço interno com prateleiras bem distribuídas, ideal para manter seus calçados sempre arrumados. Características principais: -3 portas com dobradiças metálicas de alta resistência -Fabricada 100% em MDP, garantindo durabilidade e excelente acabamento -Design moderno, ideal para quarto, corredor, hall de entrada ou closet -Prateleiras internas que comportam até 20 pares de calçados -Puxadores discretos e funcionais -Acabamento fácil de limpar Dimensões : -Altura: 110 cm -Largura: 60,5 cm -Profundidade: 27 cm Montagem: -Produto enviado desmontado, com manual de instruções e ferragens inclusas', 416.66, 198.98, NULL, 'Home & Living > Home Organizers > Shoe Storage Boxes', 'https://cf.shopee.com.br/file/br-11134207-820mc-mntzbn1upqf893', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1242718651%2F42456743624', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58260255875', '30 Clipes Quadrados Aço Inoxidável, Resistentes e Seguros, para Roupas, Íntimas e Meias de Bebê', '1、Secagem de Grande Capacidade com Maior AgilidadePossui 30 prendedores em disposição matricial, distribui as roupas de forma uniforme para melhor ventilação e maior eficiência de secagem, deixando as peças secas muito mais rápido. 2、Estrutura de Aço Reforçada, Estável e ResistenteFabricado em aço inoxidável de 4mm de espessura, possui alta capacidade de suporte, permanece estável e não deforma, atendendo facilmente à demanda de secagem de grande quantidade de roupas. 3、Prendedores de Mola em Aço Inoxidável com Firmeza TotalPrendedores de mola em aço inoxidável de alta qualidade com forte poder de fixação, evitam que roupas escorreguem e garantem secagem segura. O gancho com superfície lisa não mancha nem deixa marcas de ferrugem nas peças. 4、Resistente à Ferrugem e Corrosão, Vida Útil de 10 AnosTotalmente em aço inoxidável, é anticorrosivo e antiferrugem, mantendo a aparência de novo mesmo em ambientes úmidos para uso prolongado. Durável com vida útil de 10 anos, excelente custo-benefício. 5、Alta Dureza e Não DeformaEstrutura em aço com excelente resistência. Não deforma mesmo ao pendurar cargas pesadas por muito tempo, mantendo sempre a forma original. 6、Versátil para Diversos Tipos de RoupasIdeal para secar roupas íntimas, meias, toalhas e demais peças, atendendo às diversas necessidades de secagem da família. Este varal múltiplo em aço inoxidável une grande capacidade, durabilidade e resistência à ferrugem. Com estrutura reforçada e prendedores de alta qualidade, garante secagem mais eficiente e segura. Fácil de usar, perfeito para o lar, tanto para pequenas quantidades diárias quanto para lotes grandes de roupas!', 49.0, 39.9, NULL, 'Home & Living > Home Organizers > Hangers & Pegs', 'https://cf.shopee.com.br/file/br-11134207-820m4-mnxx6yn5n6ys47', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1407654055%2F58260255875', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
