INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19299068727', 'Removedor De Piche E Cola Strike Vonixx 1,5 Litro', 'ITENS INCLUSOS:01 - Removedor De Piche E Cola Strike Vonixx 1,5 LitroCARACTERISTICAS:STRIKE é um produto de fórmula balanceada que age na remoção piche e da maioria de resíduos de colas de adesivos e etiquetas autocolantes em geral. Pode ser usado para remoção de sujeiras incrustadas. Não recomendamos o uso do produto em faróis ou superfícies de policarbonato.• Não prejudica o verniz• Não causa manchas• Remove a maioria das colas de adesivosMODO DE USO:1 - Pulverize uma pequena quantidade do produto na área a ser limpa;2 - Aguarde 1 minuto e esfregue o produto com ajuda de um pincel ou pano de microfibra até sentir o desprendimento da contaminação;3 - Pulverize água em abundância e continue esfregando para a remoção total do resíduo;4 - Seque a peça em seguida com uma microfibra limpa e seca.Obs. Se necessário repita a operação; o produto tem afinidade com a a maioria de tipos de colas de adesivos, porém é necessário um pequeno teste antes para ter a certeza da compatibilidade do produto com a contaminação.', 130.0, 130.0, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rbl6-lnudvt8xzx5y07', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F402635111%2F19299068727', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
