INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46102568882', 'Chinelo Kappa Beach Masculino Feminino', 'KAPPA FOOTWEAR Com design contemporâneo e visual marcante, este chinelo destaca a clássica Kappa Banda aplicada na sola, reforçando o DNA autêntico da marca. O solado em borracha natural — macio, aderente ao solo e proporcionando um conforto único — garante passos seguros e suaves. Um modelo versátil, moderno e fiel à qualidade Kappa.', 89.9, 39.9, NULL, 'Men Shoes > Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/br-11134207-820md-mpth6its33erba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1515894191%2F46102568882', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
