INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23295572824', 'FILTRO DE AR CONDICIONADO ASTRA 99->> CES 1301', 'FILTRO DE AR CONDICIONADO ASTRA TODOS Qual a importância de trocar o filtro de ar condicionado? A necessidade de trocar o filtro não só existe como é de extrema importância. Afinal, o ar que você respira dentro do carro passa por ali e, quanto mais sujo ou velho ele estiver, pior será a qualidade do ar no interior do carro. O filtro tem a função de reter poeira, fuligem e eliminar qualquer tipo de impureza do ar. - Retém partículas que provoca alergias, como Pólen. - Efetiva filtração de partículas finas como fuligem, gases de escape, bactérias, etc... - Proteção do sistema de ventilação (aquecimento e Ar condicionado).', 22.99, 22.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134207-820m3-mn341za1q1og42', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F414229824%2F23295572824', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210150495', 'Jarra Leiteira Cremeira De Porcelana Abelha Bee 210ml Hauskraft', '🥤 Jarra Leiteira Cremeira De Porcelana Abelha Bee 210ml Hauskraft Produto ideal para quem busca praticidade, qualidade e um acabamento mais bonito no uso do dia a dia. Confira abaixo os principais detalhes do item. ✨ Diferenciais do Produto • Design Exclusivo: Textura em relevo característica da Linha Bee, que proporciona sofisticação visual e um toque sensorial agradável • Versatilidade: Ideal para servir leite, cremes, mel ou molhos doces, adaptando-se perfeitamente do café da manhã ao jantar • Qualidade Premium: Fabricada em porcelana resistente, garantindo maior durabilidade e um brilho duradouro que não desbota • Acabamento Clean: A cor branca permite infinitas combinações com outros aparelhos de jantar e decorações de mesa 📌 Especificações Técnicas • Marca: Hauskraft • Linha: Bee • Material: Porcelana de alta qualidade • Cor: Branco • Capacidade: 210ml • Dimensões da Peça: 11,5cm x 8cm x 8cm • Conteúdo da Embalagem: 1 Cremeira • Tipo de Embalagem: Caixa litografada (excelente para presente) 🧼 Recomendações de Uso • Restrições: Este produto NÃO é apto para máquina de lavar louças e NÃO é apto para o micro-ondas ✅ Antes do Uso • Lave a peça utilizando detergente neutro e uma esponja macia • Verifique se o produto está em perfeitas condições de uso 🧽 Cuidados e Manutenção • Lave sempre com detergente neutro e esponja macia • Não utilize esponjas ásperas, palha de aço ou produtos abrasivos que possam danificar o esmalte da porcelana • Enxágue abundantemente e seque com um pano macio para preservar o brilho ⚠️ Perigos e Advertências • Produto Frágil: Evite quedas e impactos bruscos • Em caso de quebra, manuseie os cacos com cuidado, pois podem ser cortantes • Mantenha o produto fora do alcance de crianças', 43.74, 39.37, NULL, 'Home & Living > Dinnerware > Jugs, Pitchers & Accessories', 'https://cf.shopee.com.br/file/br-11134207-820m3-mofkz4fxosn97c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1788001787%2F58210150495', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898188889', '2 Higienizador De Ar Condicionado 200 Ml Centralsul', '2 Higienizadores de Ar Condicionado Men Vintage e América 200ml Essência Importada Super Concentrado Elimina Maus Odores Praticidade e Rapidez MODO DE USAR: Após trocar o filtro do ventilador. Ligar o motor do veículo e deixar em neutro. Ligar o ar condicionado em potência alta e ar frio. Agitar a embalagem e após posicionar o produto, abaixo da porta luvas sobre o assoalho do passageiro. Pressionar a válvula até travar e deixar vaporizar todo conteúdo da lata. Após o término da aplicação deixar as portas abertas para circular o ar por 10 minutos, para entrar no carro. VANTAGENS Aplicação fácil e segura, sua utilização proporciona um ambiente limpo, agradável e perfumado. APLICAÇÕES Para limpeza de ar condicionado de automóveis, caminhões, ônibus e aparelhos de ar condicionado de uso doméstico.', 78.99, 78.99, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m640na9h1nyd88', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F414229824%2F23898188889', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19899662247', 'Ração Royal Canin Veterinary Diet Satiety Controle de Peso para Gatos 1,5kg', 'Ração Royal Canin Veterinary Diet Satiety Controle de Peso para Gatos 1,5kg Pet: Gatos; Idade: Adultos; Linha: Veterinary Diet; Corante: Sem corantes; Tipo de Ração: Super Premium; Tamanho de grão: Grãos pequenos; Contém fibras que promovem saciedade; Alto teor de proteína que favorece a manutenção da massa muscular; Estudos indicam que 97% dos gatos perderam peso em três meses com o uso da dieta Satiety; 82% dos gatos apresentaram redução no comportamento de solicitação por alimento; Previne a formação de cristais e cálculos de estruvite e oxalato de cálcio; Uso sob orientação veterinária; Código de barras: 7896181218371. A Ração Royal Canin Veterinary Diet Satiety para Gatos Adultos é uma opção especialmente formulada para auxiliar na gestão de peso dos felinos que sofrem com obesidade ou tendência ao sobrepeso. Desenvolvida com o objetivo de promover uma perda de peso saudável e manter o peso ideal após o processo de emagrecimento, essa dieta atende às necessidades nutricionais do gato, oferecendo uma combinação específica de nutrientes que favorece a saciedade e o controle da fome. Redução do Apetite e Controle de Fome Para controlar o comportamento de solicitação por alimento, a Royal Canin incorporou à fórmula uma mistura especial de fibras naturais. Esses ingredientes proporcionam um efeito saciogênico eficaz, o que ajuda a reduzir o consumo espontâneo de alimento e mantém o gato satisfeito entre as refeições. Segundo um estudo da própria Royal Canin, 82% dos gatos que seguiram a dieta Satiety demonstraram menos insistência por comida, o que reforça a eficácia dessa formulação para o controle de fome e apoio à disciplina alimentar do felino. Perda de Peso Eficiente e Duradoura A eficácia da Ração Royal Canin Veterinary Diet Satiety para gatos foi comprovada em estudos, onde 97% dos gatos participantes apresentaram perda de peso em apenas três meses de uso. Alto Teor de Proteína: Manutenção da Massa Muscular Durante a Perda de Peso Outro aspecto essencial dessa ração é seu alto teor de proteína, que atua diretamente na preservação da massa muscular, mesmo durante o processo de emagrecimento. Manter a musculatura é fundamental para um emagrecimento saudável, já que a perda de massa muscular pode levar a um metabolismo mais lento e comprometer a saúde do gato. Ração Royal Canin Veterinary Diet Satiety substituem o uso de medicamentos? Não substitui, o ideal é que procure um veterinário para que ele possa avaliar as condições do pet e fazer uma recomendação mais específica. Qual o sabor da Ração Royal Canin Veterinary Diet Satiety? A ração Royal Canin é um alimento Super Premium que não possui um sabor especifico, uma vez que em sua composição possui um mix de carnes adequados a formulação e nutrição específica de cada raça e porte e suas necessidades nutricionais diárias, mas possui uma alta palatabilidade e aroma agradável tanto para gatos quanto para cachorros. Por que a Ração Royal Canin Veterinary Diet Satiety é um alimento Super Premium? Os alimentos Super Premium apresentam um nível nutricional mais elevado, e atendem os requisitos mínimos estabelecidos pelo Conselho de Nutrição Animal, os níveis nutricionais devem estar em equilíbrio entre os níveis mínimos e máximos apresentados pela AAFCO (Association of American Feed Control Officials). A Ração Royal Canin Veterinary Diet Satiety para Gatos foi produzida atendendo todos os requisitos. Esses níveis são determinados pelas pesquisas, que buscam ótimas condições de pelagem, desenvolvimento de musculatura e, principalmente, otimização de performance na reprodução e no sistema imunológico. Composição Farinha de vísceras de aves, casca de ervilha, farinha de mandioca, glúten de trigo, farinha de trigo, farelo de glúten de milho*, lignocelulose, gordura de frango, polpa de chicória seca, cloreto de potássio, fosfato monossódico, sulfato de cálcio, levedura seca de cervejaria, óleo de peixe refinado, casca de psyllium, cloreto de colina, cloreto de sódio (sal comum), extrato de marigold, hidrocloreto de glicosamina, sulfato de condroitina, Vitaminas (A, E, C, D3, B1, B2, B6, B12, PP, ácido pantotênico, biotina, ácido fólico, sulfato de ferro, sulfato de cobre, óxido de manganês, óxido de zinco, iodato de cálcio, levedura enriquecida com selênio, cobre aminoácido quelato, manganês aminoácido quelato, zinco aminoácido quelato, L- Carnitina, taurina, palatabilizante à base de fígado de frango, antioxidante (BHA).', 179.88, 179.88, NULL, 'Pets > Pet Food > Dog Food', 'https://cf.shopee.com.br/file/sg-11134201-7rd5o-m729hc6vj8nv90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1470189844%2F19899662247', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193043298', 'Kit Jogo Aco Inox Garfo Faca 24 Pecas Mesa Churrasco Buffet Restaurante Hotel Cozinha Original Line', 'Kit Jogo Aco Inox Garfo Faca 24 Pecas Mesa Churrasco Buffet Restaurante Lanchonete Hotel Refeicao Cozinha Casa America Original Line O Kit Garfo Faca de Mesa Inox Oriente com 24 pecas e perfeito para quem busca qualidade e elegancia em suas refeicoes. Feito em aco inoxidavel, tanto a lamina quanto o cabo, esse kit garfo Faca sao resistentes e duraveis, garantindo sua satisfacao por muito tempo. O Kit ele e ideal para uso em mesas de jantar, proporcionando conforto e praticidade. Adquira agora mesmo o Kit Garfo Faca de Mesa Inox America com 24 pecas e tenha uma experiencia gastronomica ainda mais especial. Medidas Garfo Mesa: . Peso: 0,34 g . Comprimento: 19,5 cm . Largura: 2,5 cm . Espessura: 1,5 mm . Material: Aco inox . Marca: Original Line Medidas Faca Mesa: . Peso: 0,34 g . Comprimento: 20.9 cm . Largura: 1,8 cm . Espessura: 2 mm . Material: Aco Inox . Marca: Original Line Conteudo Da Embalagem: . 12 Garfos Mesa . 12 Facas Mesa Cuidados: Para manter seus talheres sempre brilhando, lave com esponja macia, sabao ou detergente neutro. Produtos abrasivos como palha de aco podem riscar e prejudicar o brilho. Seque imediatamente para evitar manchas. Recomenda-se o uso de agua quente para melhorar o brilho Nao guarde em local umido, a umidade pode provocar manchas. Importante: Garantia de 3 Meses. Valor do Kit. Imagens Meramente Ilustrativas. Nao nos responsabilizamos pelo mau uso do produto.', 98.9, 65.0, NULL, 'Home & Living > Dinnerware > Cutleries', 'https://cf.shopee.com.br/file/sg-11134201-7rd5o-lviazig2kjbb30', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F281898655%2F23193043298', NULL, NULL, '2026-07-28T02:11:31.708458+00