INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22291598620', 'Extratora de Sujeira Britânia BEX2000V 3 em 1 1200W', 'A limpeza perfeita em casas, empresas, hotéis e muito mais! A Extratora de Sujeira Britânia BEX2000V 3 em 1 1200W conta com a potência ideal para realizar limpezas profundas e eficientes em: carpetes, pisos, estofados, tapetes, sofás e muito mais! Garanta a limpeza completa do ambiente. Ela é 3 em 1: extrator, spray de água e soprador, garantindo a máxima limpeza do ambiente, extraindo pó e líquidos, e proporcionando grande versatilidade para o seu dia a dia. Em caso de manchas e sujeiras mais difíceis de remover, a função Spray de Água auxilia na remoção. A Extratora Britânia conta com dois tanques: um para água com detergente (capacidade máxima de 6,8L) e o segundo para água suja (capacidade máxima de 17,2L). Após a remoção, utilize a função sopro. Ele é prático em todos os momentos para secar superfícies, acender churrasqueiras ou soprar as folhas do quintal. • Função extratora • Função aspirador • Função spray água •Possui dois tanques: tanque para água com detergente (capacidade máxima de 6,8L) e tanque para água suja (capacidade máxima de 17,2L •Acessório para cantos •Acessório para pisos e carpetes •Acessórios para estofados •Acessório extratora • Acessório rodo extratora •Cordão elétrico com 4m •Função sopro •Extrai líquidos na função extratora • Rodas para movimentação • Mangueiras de sucção de 2,4m.', 1589.9, 1589.9, NULL, 'Home Appliances > Small Household Appliances > Vacuum Cleaners & Floor Care Appliances', 'https://cf.shopee.com.br/file/sg-11134201-8258m-mqz9jtmagxl0ab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F811879342%2F22291598620', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
