INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498150044', 'Mochila Saco Futebol Time Fluminense Bolsa Esportiva Fitness', 'Seja bem-vindo a Eletroking, leia atentamente a descrição do produto abaixo antes da compra, qualquer dúvida, nos acione no campo de perguntas do anúncio. Mochila Saco Esportiva Xeryu s Fluminense - Ref. 14054 Mostre sua paixão pelo Fluminense onde estiver! Fabricada em RipStop resistente, essa mochila saco combina design moderno, alças ajustáveis e detalhes emborrachados para maior durabilidade. Compacta e leve, é ideal para o dia a dia. Especificações Técnicas: • Modelo: 14054 • Composição/Material: Tecido RipStop • Compartimentos: Com bolso principal amplo • Alças ajustáveis • Abertura/fechamento: Cordão • Dimensões (LxAxC): 33 x 43 x 15 cm • Peso: 150 gramas Conteúdo da Embalagem: • 01 Mochila Saco Esportiva Fluminense • Certificado de Garantia Importante: • Garantia de 273 Dias. • Valor Unitário. • Todos os Nossos Produtos São Novos, Originais e Acompanham Nota Fiscal. • A Eletroking recomenda que a instalação seja feita por profissional especializado e não se responsabiliza pelo mau uso do produto.', 87.9, 82.63, NULL, 'Men Bags > Backpacks', 'https://cf.shopee.com.br/file/sg-11134201-7ra0v-m5a2g7smf5n29c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F463375702%2F23498150044', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18198101322', 'Tanquinho de Lavar Roupa 12kg Wanke Comfort Semiautomática Branco 220V - LWBE120T3', 'Experimente a eficiência e a praticidade da Máquina de Lavar Roupa Wanke Comfort 12kg. Com um design moderno e funcional, esta lavadora semi-automática é ideal para quem busca alta performance e facilidade no cuidado com as roupas. Além de sua grande capacidade e motor potente, esta máquina de lavar destaca-se pelo seu design ergonômico e fácil de usar. Seus 8 programas de lavagem proporcionam a flexibilidade necessária para lidar com diferentes tipos de tecidos e níveis de sujeira, enquanto o filtro de fiapos garante roupas sempre limpas e bem cuidadas. Adquira já a sua Lavadora Wanke Comfort 12kg e transforme a rotina de cuidados com as roupas em uma tarefa rápida e eficiente! Disponível para compra com envio rápido e seguro. Especificações: - Comprimento: 58 cm - Largura: 55 cm - Altura: 94 cm - Peso: 9,30 kg - Tensão / Voltagem: 220V - Consumo de Energia: 0,19 kWh/ciclo - Marca: Wanke - Modelo: Comfort - LWBE120T3 - Capacidade: 12 kg - Motor: WEG - Maior Cuba - Quantidade de Programas: 8 Programas - Botão Ergonômico - Timer Continuo de 10 Minutos (Sem Paradas) - Filtro de Fiapos - Cor: Branco - Sem centrífuga. - As configurações do seu monitor ou dispositivo móvel podem afetar a tonalidade da cor do produto. Conferir na descrição. - Produtos de Enfeite e Eletrônicos Não Estão Inclusos.', 699.9, 649.9, NULL, 'Home Appliances > Large Household Appliances > Washing Machines & Dryers', 'https://cf.shopee.com.br/file/sg-11134201-7repu-m1svjar3lp3c6e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1296760327%2F18198101322', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
