INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18999561547', 'Minidicionário Houaiss da língua portuguesa', 'Integralmente redigido segundo o Acordo Ortogr&aacute fico, apresenta as novas regras de acentua&ccedil &atilde o, hifeniza&ccedil &atilde o e grafia. E mais: Separa&ccedil &atilde o sil&aacute bica, indica&ccedil &otilde es de plural, feminino, aumentativo e diminutivo, pron&uacute ncia de palavras estrangeiras, n&iacute vel de uso, sin&ocirc nimos, ant&ocirc nimos, hom&ocirc nimos, par&ocirc nimos e regionalismos, vocabul&aacute rio t&eacute cnico e cient&iacute fico, termos atuais relacionados &agrave inform&aacute tica, internet, ci&ecirc ncias e tecnologia, gram&aacute tica, adendos com informa&ccedil &otilde es variadas como correspond&ecirc ncia de medidas, tabela peri&oacute dica e convers&atilde o de medidas al&eacute m de um quadro exclusivo de pa&iacute ses, povos, l&iacute nguas e moedas.', 92.94, 92.94, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rffu-m32j8lwckkod0c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F18999561547', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49910933796', 'Rivalidade ardente – Heated Rivalry', 'Rivalidade ardente – Heated Rivalry O romance esportivo hot que inspirou a série de TV Heated Rivalry, distribuída no Brasil pela HBO MAX A estrela do hóquei profissional Shane Hollander não é apenas absurdamente talentoso: Ele também tem uma reputação impecável. O hóquei é sua vida. Agora que é o capitão do time Montreal Voyageurs, ele não deixará que nada coloque seu trabalho em risco — muito menos o cara russo sexy cujo corpo atlético tira seu sono. O capitão do Boston Bears, Ilya Rozanov, é tudo o que Shane não é. Autoproclamado rei do gelo, é tão arrogante quanto talentoso. Ninguém consegue vencê-lo — exceto Shane. Os dois construíram suas carreiras em cima dessa rivalidade lendária, mas quando saem da pista de gelo, o calor entre eles é inegável. Quando Ilya percebe que quer mais do que alguns encontros secretos, ele sabe que precisa se afastar — o risco é grande demais. Mas conforme a atração entre eles se intensifica, os dois lutam para manter o relacionamento longe dos holofotes. Se a verdade vier à tona, a carreira de ambos será arruinada. Só que, quando o desejo que sentem um pelo outro passa a rivalizar com a ambição no rinque, manter o segredo deixa de ser uma opção. Rivalidade ardente faz parte da série de romance esportivo picante Game Changers e foi adaptado para série de TV, estrelando Connor Storrie e Hudson Williams e distribuída no Brasil pela HBO Max.', 47.9, 47.9, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-823oj-moif0tnz7n5s90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F49910933796', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
