INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593496668', 'CEREAL SUCRILHOS ORIGINAL KELLOGGS LEVE 800G PAGUE 690G', 'Sucrilhos® original da Kellogg\''s® é feito com milho de verdade, é crocante e delicioso a cada colherada. Contém 4 vitaminas do complexo B, vitamina D e ferro, que podem contribuir para um adequado desempenho físico e energético, quando associados a uma alimentação equilibrada e a prática de atividade física. Desfrute do seu sabor favorito para vencer com garra e energia! Há diversas opções para compor os lanches, como as frutas que podem fornecer fibras, vitaminas e minerais, o leite ou iogurte que fornecem proteínas e cálcio e os cereais como os pães e biscoitos que fornecem carboidratos, dão energia e são alternativas interessantes e deliciosas para fazer parte deste momento.', 31.31, 29.89, NULL, 'Food & Beverages > Breakfast Cereals & Spread > Cereal, Granola & Oats', 'https://cf.shopee.com.br/file/sg-11134201-7renh-m1sg1g108ldpaf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F638330698%2F22593496668', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18898300315', 'Coifa de Parede Moob 90cm Vidro Curvo Inox Slim com Duto 220V', 'Coifa de Parede Moob Vidro Curvo Slim Inox 90 cm: Ar Limpo e Modernidade na Sua Cozinha! 💨✨ Quer ter um eletrodoméstico que será de grande utilidade para deixar o ar de sua cozinha mais saudável? A Coifa de Parede Vidro Curvo Moob é a escolha perfeita! Com um produto de praticidade, moderno e fácil instalação, ela pode ser usada como **exaustor** ou **depurador**. Seus 90 cm de largura são ideais para ser utilizada em fogões de 4 a 6 bocas, mantendo sua cozinha livre de fumaça e gordura. 🏡 Principais Características - Design Inovador: Acabamento em vidro curvo e painel de controle Easy Touch, mais fino que as coifas convencionais, que confere um visual moderno e elegante. 💎 - Dupla Função: Pode operar como Exaustor (eliminando o ar) ou Depurador (filtrando o ar e devolvendo-o limpo). - Alta Capacidade de Sucção: Com 550m³/h, garante que o ar da sua cozinha seja renovado e purificado de forma eficiente. 🌬️ - Painel Easy Touch: Comando simples e intuitivo com **3 velocidades de sucção** para você escolher conforme a necessidade. - Iluminação LED: Duas lâmpadas LED (2W no total) oferecem iluminação funcional para a área do fogão. 💡 - Filtros Práticos: Possui filtro de **carvão ativado** (para o modo depurador) e filtro de **alumínio metálico lavável** (para reter a gordura). 🧼 Itens Inclusos 🎁 - Filtro de carvão ativado - Parafusos e b900 x 495 x 450 mmuchas - Suporte de fixação para dutos inferior e superior - Dutos Externos Superior/Inferior - Manual do produto Atenção e Notas 📝 - A instalação do tubo interno é opcional e não acompanha o produto. - As dimensões do produto podem variar em até 7 mm. Para instalação embutida em nichos, o fabricante recomenda uma folga de pelo menos 1cm em cada lado. Características Gerais do Produto 📋 - Material da Coifa: Aço Inox Escovado - Dimensões Base da Coifa (LxAxP): 900 x 495 x 450 mm - Altura dos Dutos (Mínima - Máxima): 500 - 930 mm - Potência Total: 142W - Potência do Motor: 140W - Ruído: 65 dB - Consumo: 0,142KWh - Frequência: 60 Hz Adicione agora mais tecnologia e saúde ao seu ambiente com a Coifa Moob! 🛒 ⭐ Tags #BelaMagazine #Coifa #Moob #CoifaDeParede #Eletrodomestico #Inox #Cozinha #VidroCurvo #Depurador #Exaustor', 849.9, 799.9, NULL, 'Home Appliances > Kitchen Appliances > Hoods', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mibmf3jc1wqucc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F680601528%2F18898300315', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
