INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693269681', 'Livro A senhora das velas', 'O CORAÇÃO SEMPRE FALA, SEMPRE INDICA O CAMINHO CERTO.MAS, A MAIOR PARTE DO TEMPO, AS PESSOAS NÃO O SEGUEM. Combinando realismo fantástico com fábula e mensagem de esperança, "A Senhora das Velas" é um relato sobre a lição de que as pessoas são capazes de mudar o próprio destino. A saga de Felipe, um menino órfão em buscada Senhora das Velas, surge de maneira mágica somente a guardiã das velas, que representam a vida de cada um de nós, poderá mudar o destino de Felipe. Walcyr Carrasco criou personagens que não se separam de quem lê o livro, em um cenário mágico, com acontecimentos que tocam o coração e mostram que todos os dias há algo novo a aprender._x000D_ _x000D_ Editora: Principis_x000D_ Edição: 1, 2024_x000D_ Autor: Walcyr Carrasco_x000D_ Ilustrador: Cesar Munhoz_x000D_ Idioma: Português_x000D_ Páginas: 128_x000D_ Dimensões: L 15.50 x A 22.60 x E 0.90_x000D_ ISBN: 9786550972325_x000D_ Coleção: Não se aplica_x000D_ Linha Editorial: Principis - Autores contemporâneos_x000D_ Faixa Etária: + 14 anos_x000D_ Assuntos (tags): Literatura brasileira , Espiritualidade, Jornada, Sobrenatural, Família, Relacionamento, Amor, Sofrimento, Doença, Morte, Resiliência, Esperança_x000D_ BISAC: Ficção / Literária_x000D_ Linha de Produto: Principis_x000D_ Encadernação: Brochura_x000D_ Acabamento: Laminação fosca e verniz localizado_x000D_ Material: Papel', 39.9, 39.9, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-7rdyh-m03iqbc4rk6e48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F23693269681', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
