INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19498336284', 'Cloro Piscina Weekend Hidroazul 2,4K', 'O Cloro para Piscina Weekend Hidroazul é a solução ideal e revolucionária para recuperar piscinas com água verde ou que estão sem uso há muito tempo. Com ele, você dispensa a aplicação de outros produtos, pois ele age rapidamente, limpando a piscina da noite para o dia. Este balde de 2,4kg oferece um tratamento poderoso e eficiente para restaurar a cristalinidade da sua água de forma prática e sem complicações. Tenha sua piscina pronta para uso em poucas horas! Produto: Cloro para Piscina Weekend Marca: Hidroazul Peso: 2,4 kg Função: Tratamento revolucionário para água verde ou piscinas sem uso Benefício: Limpa a piscina da noite para o dia, dispensa outros produtos', 147.9, 80.9, NULL, 'Home & Living > Gardening > Others', 'https://cf.shopee.com.br/file/sg-11134201-8258t-mg419nt6dzpnc6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F965617276%2F19498336284', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
