INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47858095885', 'Sensor Rotação Volkswagen Golf 1.6 8V Gasolina/Flex1998 A 2007 Polo 1.6 8V Gasolina/Flex 2002 A 2006', 'Sensor de Rotação do Virabrequim Greenparts GP6B603230 - Volkswagen Golf e Polo O Sensor de Rotação do Virabrequim Greenparts GP6B603230 é um componente essencial para o correto funcionamento da injeção eletrônica, realizando a leitura da rotação e da posição do virabrequim com precisão. É uma reposição de qualidade para quem busca confiabilidade, compatibilidade e desempenho. Benefícios e diferenciais Leitura precisa da rotação do motor Tecnologia Hall / Pwm Contribui para partidas mais estáveis Ajuda no correto funcionamento da injeção eletrônica Produto da marca Greenparts Aplicação / Compatibilidade Compatível com os seguintes veículos: Volkswagen Golf 1.6 8V Gasolina/Flex - 1998 a 2007 Volkswagen Polo 1.6 8V Gasolina/Flex - 2002 a 2006 Importante: confira a referência da peça, os números originais e a aplicação exata no veículo antes da compra. Especificações técnicas Produto: Sensor de Rotação do Virabrequim Tipo: Sensor Rotação Virabrequim Tipo de sensor: Hall / Pwm Frequência: 238Hz Comprimento: 54,5 mm Referência: GP6B603230 Marca: Greenparts EAN: 7908374423353 Números originais 030957147D 030957147G', 99.9, 98.3, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-81ztp-mmizgmriibcz59', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F405317374%2F47858095885', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
