INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898353187', 'Cropped Feminino Slik de Estrela Planet Girls Azul Médio', 'A Regata Feminina Delusional da Planet Girls é um charme total! Com alcinhas finas e um detalhe de lacinho super fofo, ela traz uma vibe descontraída e cheia de estilo. A estampa "Delusional" adiciona um toque divertido e único, enquanto o tecido leve garante conforto o dia inteiro. DETALHES QUE VOCÊ VAI AMAR SABER: Com a Regata Feminina Delusional Planet Girls você terá uma peça fundamental para expressar sua personalidade marcante e conquistar olhares com confiança. Use com calças jeans estilo mom ou reta de cintura alta. Para um visual mais leve, combine com calças de sarja em cores neutras como cáqui ou verde militar.', 49.99, 49.99, NULL, 'Women Clothes > Traditional Wear > Tops', 'https://cf.shopee.com.br/file/sg-11134201-8259i-mqrxz0zlrlsffc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F675392510%2F23898353187', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18697690723', 'Aneethun Force System - Máscara Fortalecedora 250g', 'Aneethun Force System Máscara para cabelos enfraquecidos. Aneethun Force System impulsiona o crescimento e proporciona mais força aos fios. A Máscara Fortalecedora Aneethun Force System possui exclusiva tecnologia Densifiber que atua desde o bulbo até o córtex capilar para minimizar a queda, hidratar, nutrir e condicionar profundamente, devolvendo resistência, brilho e vitalidade aos cabelos. Conselho de Aplicação Aplique a Máscara mecha a mecha, enluvando os fios, iniciando na altura da orelha em direção às pontas. Deixe agir por 2 minutos e depois enxágue. Nossos Experts Ensinam Utilize uma touca térmica durante a ação do produto e veja resultados ainda mais potentes! Densifiber: o mecanismo de ação do Densifiber estimula o metabolismo intracelular, eleva os níveis de Trifosfato ATP, melhora a vascularização da derme, impulsionando o crescimento dos fios e evitando a queda. Aminoácidos Vegetais: promovem uma reconstrução profunda do fio danificado, aumentando sua resistência. Cabelo hidratado, fortalecido, brilhoso e com mais vitalidade.', 87.75, 87.75, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lw76fy9ovb829c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939426851%2F18697690723', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210215090', 'Aquecedor Domestico Halógeno 1200w com Proteção Superaquecimento 220v', 'Aquecedor Halógeno Doméstico 1200W Nagano NALH1 com 3 Níveis de Potência e Desligamento Automático Aqueça seu ambiente em poucos instantes com eficiência e praticidade. O aquecedor halógeno Nagano NALH1 é uma solução prática e eficiente para aquecer ambientes internos de forma rápida. Utilizando lâmpadas halógenas, ele gera calor imediato, ideal para quem precisa de conforto térmico sem esperar. Indicado para uso em salas, escritórios e outros espaços fechados, é uma excelente escolha para quem busca aquecimento pontual com controle de intensidade. Com três níveis de potência, permite ajustar o calor conforme a necessidade, oferecendo mais conforto no dia a dia. APLICAÇÕES E VERSATILIDADE Ambientes residenciais como salas e quartos Escritórios e locais de trabalho Pequenos espaços que precisam de aquecimento rápido Uso doméstico em dias frios Ideal para quem busca aquecimento localizado e imediato DESTAQUES DO PRODUTO Aquecimento rápido com lâmpadas halógenas Potência máxima de 1200W 3 níveis de potência (400W, 800W e 1200W) Desligamento automático para maior segurança Design compacto para uso em ambientes internos BENEFÍCIOS DO PRODUTO Tecnologia Halógena - Gera calor instantâneo, ideal para quem precisa aquecer o ambiente rapidamente. 3 níveis de potência - Permite ajustar o consumo de energia e o nível de aquecimento conforme a necessidade. Potência de até 1200W - Oferece aquecimento eficiente para ambientes pequenos e médios. Desligamento automático - Proporciona mais se', 211.0, 211.0, NULL, 'Home Appliances > Large Household Appliances > Heaters', 'https://cf.shopee.com.br/file/sg-11134201-820mc-mnx2pxoh9ce873', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F427153374%2F58210215090', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12657296576', 'Balde Forças Armadas Soldados e Cercados Brasileiros 60 Peças Gulliver - 0603', 'Balde Forças Armadas Soldados e Cercados Brasileiros 60 Peças Gulliver - 0603 Que tal não ter somente um, mas ter um Balde com a Forças Armadas com figuras da Gulliver? Nossos amiguinhos verdes, sempre em seus postos preparados para ajudar nossos soldados. Vamos viver grandes aventuras com esses soldadinhos engraçadíssimos. Seus Soldados encaram qualquer missão com muita determinação e trabalho em equipe. Produto recomendado ou indicado para crianças acima de 3 anos. *Imagens Meramente Ilustrativas* Características: - Marca: Gulliver - Referência: 0603 Especificações técnicas: - Quantidade de Bonecos: 60 - Idade: Acima de 03 anos - Material/Composição: Plástico - Observação: As cores podem variar entre as imagens mostradas acima e o produto. - 60 miniaturas de soldados de exército - 4 cercados Conteúdo da embalagem: - 1x Balde Forças Armadas Soldados e Cercados Brasileiros 60 Peças Gulliver - 0603', 39.5, 37.53, NULL, 'Mom & Baby > Toys > Others', 'https://cf.shopee.com.br/file/br-11134201-23020-olg85d13n4mvf9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F376053737%2F12657296576', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10741710208', 'Aditivo De Radiador - Pronto Uso - 1L Aditivo De Radiador Diluído', 'Aditivo de radiador pronto uso ADITIVO PRONTO USO O aditivo tem um papel extremamente importante no funcionamento do sistema de arrefecimento: ele compõe, da melhor maneira, juntamente com a água, o fluido do radiador. Conforme acontece a circulação da água pelo motor, ela esquenta e pode entrar em ebulição. O que é aditivo pronto para uso? Aditivo para radiador sintético pronto uso é um produto de alta qualidade, elaborado com polímeros sintéticos e aditivos anticorrosivos protetivos de última geração. Garante total proteção contra cavitação e corrosão em ligas metálicas presentes nos radiadores e componentes.', 14.99, 14.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/br-11134207-820lj-mr24bsccy3us2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F414229824%2F10741710208', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
