INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8459029205', 'Kit Nutrifier Shampoo e Condicionador L’Oréal Professionnel', 'Este Kit Contém:1 Shampoo Serie Expert Nutrifier 300ml - L''oreal Professionnel 1 Condicionador Serie Expert 200ml - L''oreal Professionnel APRESENTAÇÃO DA LINHA L´ORÉAL PROFESSIONEL SERIE NUTRIFIER Linha para cabelos ressecados. A linha L''Óreal Professionnel Serie Expert Nutrifier proporciona nutrição e hidratação à fibra capilar, para fios mais lindos e macios. Densevolvida para combater o ressecamento dos fios. L''Óreal Professionnel Serie Expert Nutrifier Duo é uma linha profissional desenvolvida com óleo de coco. Repara a fibra do cabelo, que fica ressecada por falta de umectação e nutrientes. Oferece limpeza suave e não pesa sobre o cabelo por não possuir silicone. RESULTADOS Cabelo nutrido, hidratado, bonito, macio e saudável. L''Óreal Professionnel Serie Expert Nutrifier - Shampoo 300ml Limpa suavemente e ajuda a nutrir os fios. MODO DE USO: Coloque uma pequena quantidade de shampoo sobre o cabelo molhado. Massageie até surgir espuma. Em seguida, enxágue. L''Óreal Professionnel Serie Expert Nutrifier - Condicionador 200ml Proporciona hidratação profunda e nutrição, além de selar os fios. MODO DE USO: Aplique o condicionador em todo o comprimento e pontas. Deixe agir por 2 a 3 minutos e, em seguida, enxágue bem.', 487.99, 236.72, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/br-11134201-7r98o-lksffw0sgcqb1c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F361729924%2F8459029205', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22399435185', 'Slide Birken Colcci Julia Feminino Confortável Leve', 'O Slide Julia da Colcci é a escolha perfeita para quem busca praticidade, conforto e estilo em um único produto. Inspirado no modelo birken, ele é confeccionado em material expandido, garantindo extrema leveza e conforto durante o uso. Com design clássico e versátil, combina facilmente com diversos looks, do casual ao moderno, sendo ideal para o dia a dia, passeios ou momentos de lazer. - Material expandido: leve e confortável - Modelo estilo birken (tendência) - Design clássico e versátil - Ideal para uso diário e momentos de lazer', 99.99, 89.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/br-11134207-820me-mnkccltgbbpg5f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F728423102%2F22399435185', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
