INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298824925', 'CORRENTE DE COMANDO RIFFEL 90 ELOS PARA HONDA POP 110 i BIZ 110 i', 'Corrente de comando 25H 90L Marca: Riffel Aplicação: Compatível com Honda BIZ 110I 2016 em diante. Compatível com Honda POP 110I 2016 em diante. Descrição: A corrente de comando é quem liga o virabrequim ao comando de válvulas de forma sincronizada. A corrente de comando da Riffel é uma peça com extrema qualidade e durabilidade.', 32.9, 32.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-81ztt-mmj65086yy9vf8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1297313782%2F23298824925', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9613393149', 'Kit Tubetes MINI Para Aniversários Festas Lembrancinhas 8cm C/20 Unidades', 'Os Tubetes Mini Para Lembrancinha são ideais para criar lembrancinhas encantadoras e personalizadas para sua festa! Feitos de plástico transparente de alta qualidade, esses tubetes têm um design cristalino, que garante um visual elegante para suas embalagens de doces, confetes e outros itens de festa. Quantidade: 2 pacotes com 10 unidades cada, totalizando 20 unidades. Tamanho: Aproximadamente 8 cm de altura x 3 cm de diâmetro. Material: Plástico transparente de alta qualidade (totalmente cristal). Uso: Perfeito para festas infantis, aniversários, casamentos e eventos corporativos. Com os Tubetes Mini Para Lembrancinha, você pode criar kits personalizados, preenchendo-os com doces ou outros itens, e ainda garantir a praticidade e a qualidade que sua festa merece. Somos uma loja especializada em artigos de festa, confeitaria, embalagens e atacado em doces com lojas físicas no estado de São Paulo, desde 2002. Imagens meramente ilustrativas, de acordo com nossos fornecedores que nos fornecem. Todas as Informações divulgadas são de responsabilidade do fabricante/fornecedor.', 22.99, 22.99, NULL, 'Home & Living > Party Supplies > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m79f1mug5s96d3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318555124%2F9613393149', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7859751557', 'Balas De Goma Festa Sortidas 1kg - Kuky', 'Balas de Goma Festa Sortidas 1kg – Kuky | Doces Coloridos e Divertidos para Todas as Festas! Leve mais alegria para suas comemorações com as Balas de Goma Festa Sortidas 1kg da Kuky! Docinhas, macias e com cores vibrantes, são perfeitas para encantar crianças e adultos. 🎉 Descrição do Produto: As balas de goma da Kuky são feitas com textura macia e sabores variados, ideais para dar um toque divertido e delicioso à sua festa. Vêm em um pacote de 1kg, com balas coloridas que tornam qualquer mesa mais alegre. 🧁 Principais Características: Peso: 1kg (embalagem econômica) Tipo: Balas de goma tipo festa, sortidas e coloridas Textura: Macia e saborosa Sabores: Sortidos (frutas) 🌟 Benefícios: Prontas para consumo imediato. Perfeitas para montar mesas de doces, lembrancinhas, sacolinha surpresa, brindes escolares e eventos corporativos. Visual atrativo que chama a atenção em festas infantis e eventos temáticos. 🎯 Indicação de Uso: Ideal para festas de aniversário, chás de bebê, eventos escolares, lembrancinhas e até para venda por unidade. 📦 Entrega e Qualidade: Produto com pronta entrega, envio rápido e seguro. Embalado com cuidado para garantir que chegue em perfeitas condições até você. ⚠️ Avisos Importantes: Contém açúcar. Pode conter traços de glúten e derivados de leite (verifique no rótulo). Armazenar em local seco, fresco e longe da luz. Somos uma loja especializada em artigos de festa, confeitaria, embalagens e doces com lojas físicas no estado de São Paulo, desde 2002. Garanta já suas balas e deixe sua festa ainda mais gostosa e colorida! 🍬✨', 28.99, 28.99, NULL, 'Food & Beverages > Snacks > Sweets & Candy', 'https://cf.shopee.com.br/file/br-11134207-81z1k-min4rjnbvi12c8', 'https://shope.ee/an_redir?origin_link=https%3