INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23397611149', 'Cabo Hdmi 1.4 1080p 3M 20M Blindado Full HD Para TV Game PC', 'O cabo HDMI versão 1.4 foi desenvolvido para estabelecer conexão entre diversos aparelhos com entrada HDMI como TVs, vídeo games, computadores, monitores e outros aparelhos. Usar este cabo é a garantia de ter qualidade de som e vídeo em seus equipamentos sem perda de sinal e sem interferências. O cabo é composto por uma espessa camada emborrachada com reforços próximos às extremidades. Ele também conta com uma malha de proteção e conectores banhados a ouro para garantir uma transmissão ainda mais eficiente. Todas essas características fazem com que o produto tenha uma longa vida útil. Tenha momentos de entretenimento com imagem e som em altíssima qualidade. ESPECIFICAÇÕES: - Conexão: Hdmi tipo A x Hdmi tipo A; - Comprimento do cabo: 3 ou 5 metros; - Versão:1.4; - Indicado para conectar DVD Player, blu-ray, vídeo games, receptor e conversor de TV digital, TVs de Plasma, LCD, LED, monitor, projetor e etc; - Compatível com resoluções de 480i, 480p, 720i, 720p, 1080i e 1080p; - Revestido com malha de nylon para maior proteção; - Conectores banhados a ouro. CONTEÚDO: 1x Cabo HDMI (Tamanho a sua escolha)', 31.77, 22.15, NULL, 'Audio > Audio & Video Cables & Converters', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m14b6fjw0ej40d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373745451%2F23397611149', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
