INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209456498', 'Mini kibe Daki', 'O mini kibe Daki é uma pequena porção de carne moída temperada e trigo para quibe, com uma casca crocante e um recheio suculento e bem condimentado. Sua combinação de sabores inclui carne, cebola, hortelã e especiarias, resultando em uma mordida deliciosa que mistura texturas e aromas. Perfeito como aperitivo ou petisco em eventos, o mini kibe oferece uma amostra saborosa da culinária do Oriente Médio.', 10.99, 10.99, NULL, 'Food & Beverages > Fresh & Frozen Food > Frozen Processed Food', 'https://cf.shopee.com.br/file/sg-11134201-825ah-mqneksqnjw2332', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555057%2F58209456498', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497563051', 'Jogo 2 Pneus Ceat Aro 13 EcoDrive 165/70R13 83T XL', 'Marca: CEAT Modelo: ECODRIVE Medida: 165/70R13 Largura: 165 Perfil: 70 Tamanho de Aro: 13 Índice de peso: 83 - 487 kg Índice de velocidade: T - 190 km/h Tipo de Veiculo: CARRO Tipo de terreno: HT RunFlat: Não Sidewall: BSW LETRAS PRETAS Extra Load: Sim Desenho: SIMÉTRICO UTGQ: 440AB Adesão à àgua: B Eficiência energética: B Ruído externo: 70 *Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. O novo pneu CEAT ECODRIVE foi desenvolvido para um amanhã mais verde. Projetado para reduzir o uso de combustível e reduzir a poluição, o ECODRIVE oferece ao seu carro uma incrível economia de combustível. Sua composição inteligente e moderna tecnologia de mistura garantem alta quilometragem e baixa resistência ao rolamento. Lamelas eficazes e flexíveis, juntamente com paredes laterais flexíveis, oferecem uma condução confortável e silenciosa. Sobre a marca Ceat A marca Ceat fundada como Cavi Electrici e Affini Torino em 1924 em Turim na Itália, mas constituída como CEAT em 1958, possui hoje sua sede em Mumbai e é uma das principais fabricantes de pneus da Índia, com forte presença nos mercados globais, sendo a principal empresa do grupo RPG Enterprise. Produzindo cerca de 165 milhões de pneus por ano, a Ceat produz pneus de primeira classe e alto desempenho para uma ampla gama de veículos sendo eles carros, motocicletas, caminhões e ônibus pesados, veículos comerciais leves, escavadeiras, empilhadeiras, tratores, reboques e scooters além da sua referência em câmaras de ar exportando todos os produtos para países da África, América, Austrália e Ásia.', 736.13, 677.24, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rdxo-ly5o99r9v8dod3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F22497563051', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
