INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22491290221', 'Pote Plástico com Travas Hermético Verde Menta 2L Freshy Sanremo', 'O Pote Plástico com Travas Hermético Verde Menta 2L Freshy Sanremo conta com design moderno, inteligente e funcional: possui borracha integrada na tampa, quatro travas com aquele “click” - que garantem o fechamento hermético - e o melhor: os potes da Linha Freshy são modulares, o que permite um empilhamento perfeito e maior otimização do espaço na geladeira, no freezer e nos armários. Com a linha Freshy da Sanremo, o colorido e o frescor dos alimentos vão dar mais vida e beleza na sua cozinha. - Transparente e com medidas de VOLUME DA CAIXA. - Fechamento hermético: não vaza nada. - Desenvolvido com matéria-prima virgem e BPA Free: produto atóxico - o uso contínuo não causa danos à sua saúde. - Borracha fixa na tampa: não permite o acúmulo de água, mofo, odores e nem a formação de fungos e bactérias. - Alimentos frescos por muito mais tempo. Medidas: 11,3 x 13,7 x 20,7 cm (A x L x C)', 33.9, 33.9, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/br-11134201-820m3-mqxnm7ahnuo4bf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816806234%2F22491290221', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997276828', 'Cesto Organizador Circular Plástico Castor 30L Moolti Sanremo', 'Os cestos flexíveis da Sanremo proporcionam ao seu dia dia uma utilização ainda mais prática leve e divertida no momento de organizar ambientes. O Cesto Organizador Circular Plástico Castor 30L Moolti Sanremo possui pegas laterais facilitadoras durante o uso, material flexível, leve e muito prático. A sua versatilidade de armazenamento se adequa na lavanderia, no quarto ou para organizar brinquedos e acomoda bem qualquer tipo de objeto. Medidas: 31,3 x 49,7 x 45,6 cm (A x L x C)', 79.9, 69.9, NULL, 'Home & Living > Home Organizers > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rfi8-m95ygiyrcuj580', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816806234%2F23997276828', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17800391848', 'Aperitivo Aperol 750ml', 'Aperitivo italiano. Como diz o nome, Aperol é um aperitivo perfeito. Possui cor laranja, vívida e sabor inconfundível, graças a sua receita secreta, a base de laranjas de diversos tipos: amarga, doce, china, genziana, rhubarb e muitos outros ingredientes, como ervas aromáticas numa dose perfeita. Hoje, já é o queridinho dos apreciadores mais modernos (quase um estilo de vida!), e você já deve ter visto por aí uma bebida laranja em uma grande taça redonda que, no mínimo, chama a atenção dos olhos. Levemente doce, com teor alcoólico baixo, é fácil de agradar, e faz sucesso principalmente no famoso drink Aperol Spritz (com espumante). CARACTERÍSTICAS: Categoria: Aperitivo / Licor. Graduação: 11% vol. Volume: 750 litro.', 69.9, 59.9, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0goknyl28iob0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F661273874%2F17800391848', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259463600', 'Néctar Maguary de Morango', 'Suco de Morango Maguary 1L Delícia Refrescante para Todos os Dias! Desperte seu paladar com o Suco de Morango Maguary, uma experiência sensorial que adoça e refresca seu dia a dia. Com um sabor incrivelmente frutado, este suco é a escolha perfeita para acompanhar suas refeições, trazendo consigo o autêntico e refrescante sabor das frutas. Além de ser uma delícia, é uma excelente fonte de vitamina C, adicionando um toque saudável e natural à sua rotina. Características do Produto: * Refrescante e saboroso * Sem conservantes * Pronto para beber * Sem glúten Este suco de caixinha já vem pronto para consumo, sendo a opção mais prática e deliciosa para desfrutar do sabor natural dos morangos. A Maguary, conhecida por sua excelência na produção de sucos e bebidas doces à base de frutas, tem como prioridade a saúde e o bem-estar dos clientes, encantando pessoas de todas as idades com sua ampla variedade de produtos. Armazenamento: Mantenha o suco fechado em local fresco e arejado. Após aberto, conserve na geladeira e consuma em até 3 dias para preservar seu sabor e frescor. Aprecie a doçura natural e o frescor irresistível do Suco de Morango Maguary, uma experiência que combina saúde e sabor em um único gole!', 6.49, 4.69, NULL, 'Food & Beverages > Beverages > Juice & Juice Vinegar', 'https://cf.shopee.com.br/file/sg-11134201-825a8-mr0jbuf2olc437', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555057%2F58259463600', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398368192', 'Comoda Lopas Easy Like Amendoa Clean/Off White', 'Cômoda Lopas Easy LikeA Cômoda Easy Like da Móveis Lopas é a escolha perfeita para quem busca aliar estilo e funcionalidade no ambiente do quarto. Com um design contemporâneo e elegante, essa cômoda promete transformar seu espaço, proporcionando um toque de modernidade e sofisticação. Características PrincipaisCom uma estrutura robusta e acabamento de alta qualidade, a Cômoda Easy Like é ideal para quem valoriza durabilidade e beleza. Suas 8 gavetas oferecem amplo espaço de armazenamento, permitindo que você mantenha seu ambiente organizado e livre de bagunça. Atributos do ProdutoMarca: Móveis Lopas Modelo: Easy Like Cor: Amendoa Clean/Off White Dimensões: 152 cm (largura) x 48 cm (profundidade) x 96 cm (altura) Peso:77 kg Material do Corpo: MDF/MDP Quantidade de Gavetas: 08 Corrediças: Metálicas Telescópicas Portas: Não Requer Montagem: Sim Inclui Manual de Montagem: Sim Detalhes e BenefíciosO acabamento em pintura UV confere um toque de sofisticação, enquanto a escala de brilho fosco proporciona um visual moderno e discreto. A cômoda é projetada para facilitar o acesso a suas roupas e acessórios, com corrediças que garantem um deslizar suave e eficiente. Além disso, a montagem é simples, com um manual claro que acompanha o produto. Por que Escolher a Cômoda Easy Like?Se você procura uma peça que combine estética e praticidade, a Cômoda Easy Like é a solução ideal. Seu design versátil se adapta a diferentes estilos de decoração, tornando-a uma adição valiosa ao seu dormitório. Não perca a oportunidade de transformar seu espaço com esta peça incrível! Adquira agora a sua Cômoda Lopas Easy Like e traga mais organização e estilo ao seu quarto! ```', 1316.01, 949.9, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7reo2-m85mbsqzjflsa0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1372644554%2F23398368192', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497552606', 'Tênis Meia Bebê Menino Sola Antiderrapante Dinossauro Marinho com Laranja Kidstep', 'Modelos divertidos e coloridos, que não deixam de lado o conforto e a qualidade que são marcas registradas da Kidstep. INFORMAÇÕES TÉCNICAS: Fechamento em Velcro Material – Textil Peso 300g pode variar de acordo com tamanho. Solado – pvc flexível. Palmilha – Macia com carimbo da marca. Caixa embalagem: cada par vai a sua caixa individual. Como tirar suas medidas: Em um papel, desenhe o contorno dos pés descalços. Meça do dedão até o calcanhar. Adicione 0,5 cm de folga. COMO REALIZAR A COMPRA DE FORMA CORRETA: 1- Selecione a cor e a numeração desejada e clique em adicionar ao carrinho. 2- Se desejar outro par junto desta compra, volte ao anuncio e selecione outro produto e adicione ao carrinho. 3- Selecionado todo seu pedido, vá até o carrinho e clique para finalizar a compra.', 89.9, 46.9, NULL, 'Baby & Kids Fashion > Boy Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lvnhi3ud2qam7f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F376576138%2F22497552606', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18197761576', 'Mesa Plástica Tramontina Cassino 90cm Branca - 92301/910', 'A Mesa Tramontina Cassino em Polipropileno possui um design moderno perfeito para ambientes internos ou externos, residenciais ou comerciais. Útil e robusta, ela é produzida com processos controlados e tecnologia de ponta, além de ser testada por rigorosos testes que garantem a alta qualidade do pro', 363.62, 290.9, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/sg-11134201-7rd70-lwyg575d8ccm65', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412527932%2F18197761576', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21499243935', 'Cilindro Ignicao da Coluna de Direcao Com Chave Kombi Clipper 1981 A 2013 1 Pino', 'CILINDRO DE IGNICAO COM CHAVE 1 PINO CROMADA KOMBI --------------------------------------------------------------------------------------- COMPATIVEL COM: KOMBI CLIPPER 1980 ATE 2013 --------------------------------------------------------------------------------------- CONTEUDO NA EMBALAGEM: 1 NOTA FISCAL 1 CILINDRO DE IGNICAO COM CHAVE 1 PINO CROMADA --------------------------------------------------------------------------------------- CARACTERISTICAS DO PRODUTO: IMAGEM ILUSTRATIVA ALTA QUALIDADE E DURABILIDADE GARANTIA DE 3 MESES COD INTERNO DO PRODUTO: 11002125 PRODUTO RESISTENTE --------------------------------------------------------------------------------------- ANTES DE FINALIZAR A COMPRA: VERIFIQUE COM MUITA ATENCAO ATRAVES DAS FOTOS E DESCRICAO SE O PRODUTO E COMPATIVEL COM O MODELO QUE DESEJA ADQUIRIR. NOS NAO NOS RESPONSABILIZAMOS POR MA INSTALACAO OU MAU USO DO PRODUTO. PARA EVITAR TRANSTORNO PROCURE UM PROFISSIONAL ESPECIALIZADO.', 57.25, 57.25, NULL, 'Spare Parts and Accessories for Vehicles > Others', 'https://cf.shopee.com.br/file/sg-11134201-823qd-mor90aq94c9b5f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F390168708%2F21499243935', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259458995', 'Removedor de Esmalte Seduction Zulu', 'O Removedor de Esmalte Seduction da Zulu remove o esmalte de forma rápida e eficaz, sem deixar as unhas esbranquiçadas, além de possuir um aroma agradável. Modo de uso: Umedecer um algodão com o removedor de esmalte Zulu seduction e aplicar nas unhas até remover totalmente o esmalte. Se necessário repetir a aplicação.', 9.79, 9.79, NULL, 'Health > Personal Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-8258e-mqnelz1cwu0wd0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555057%2F58259458995', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598417177', 'Carro Pick-up Samba Toys Alien Horizon', 'Prepare-se para uma aventura emocionante com a Carro Pick-up Samba Toys Alien Horizon! Este incrível veículo de 40cm é perfeito para as crianças que adoram brincar com carros de grande porte e explorar terrenos desconhecidos. Com adesivos temáticos, capota que abre e fecha, e rodas livres, este brinquedo oferece uma experiência realista e cheia de diversão.A Carro Pick-up Samba Toys Alien Horizon se destaca pelo seu design detalhado e adesivos temáticos de alienígenas, que capturam a imaginação das crianças e as transportam para aventuras em planetas distantes. Feita de plástico de alta qualidade, esta pick-up é robusta e durável, pronta para enfrentar qualquer terreno que as crianças possam imaginar.Uma das características mais empolgantes desta pick-up é sua capota que abre e fecha, permitindo que as crianças explorem diferentes cenários e carreguem itens essenciais para suas aventuras. As rodas livres facilitam a movimentação suave e rápida em qualquer superfície, proporcionando uma experiência de brincadeira dinâmica e interativa. As crianças podem criar inúmeras histórias e missões, estimulando a criatividade e o pensamento crítico. Ao manipular a pick-up e sua capota funcional, elas desenvolvem habilidades motoras finas e coordenação mão-olho.', 79.99, 74.99, NULL, 'Mom & Baby > Toys > Toy Vehicles', 'https://cf.shopee.com.br/file/sg-11134201-82592-mqytlyxqbf9e5a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050213612%2F23598417177', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '6782939906', 'Autoridade Espiritual - Watchman Nee', 'DESCRIÇÃO Autoridade Espiritual é uma obra de Watchman Nee que investiga o que significa viver sob autoridade — civil, eclesiástica e espiritual — à luz da Palavra de Deus. O livro oferece orientações bíblicas diretas acerca de como os cristãos devem reagir quando autoridades humanas divergem dos princípios divinos, enfatizando a obediência fiel à Escritura acima de tudo. Leitura ideal para líderes, pastores, cristãos que desejam amadurecer na disciplina espiritual e para quem busca fundamentos sólidos para discernimento em situações complexas de autoridade. Com linguagem clara e prática, ajuda a construir uma vida de submissão consciente e reverente. FICHA TÉCNICA Título: Autoridade Espiritual - Obediência à Palavra Autor: Watchman Nee Editora: Vida Formato: Brochura Páginas: 222 Dimensões: 14 × 21 cm Peso: 100 g Edição: 1ª edição (1979) / reimpressão ou nova edição contemporânea disponível ISBN: 9786555841909 PALAVRAS-CHAVE autoridade espiritual, watchman nee, obediência à palavra, obediência cristã, autoridade bíblica, vida cristã, disciplina espiritual, liderança espiritual, cristianismo prático, submissão à autoridade', 44.89, 44.89, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ltwq7pr81y00fd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380531074%2F6782939906', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793042893', 'Cola de Silicone Líquida Tek Bond 100ml', 'Cola de Silicone Líquida Tek Bond 100ml, é totalmente incolor e possui alta viscosidade. É indicada para trabalhos artísticos, reparos domésticos e artesanatos, pois adere a diversos substratos como madeira, couro, metais, papel, papelão, EVA, isopor entre outros.', 24.99, 24.99, NULL, 'Stationery > School & Office Equipment > Glues', 'https://cf.shopee.com.br/file/sg-11134201-825a3-mqs0he2ooky3bb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050213612%2F22793042893', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58255453001', 'Cesto Multiuso São Bernardo 18,2x9,4x12,9cm Branco', 'Organize seu banheiro usando o Cesto Multiuso São Bernardo. Feito de plástico branco, o cesto tem design ideal para ser instalado em qualquer espaço do box. Possui ventosas para evitar os furos e traz praticidade, deixando todos os produtos que você usa sempre ao alcance da mão.', 24.99, 19.99, NULL, 'Home & Living > Bathrooms > Others', 'https://cf.shopee.com.br/file/sg-11134201-825ae-mqlz3evbc4crf2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050213612%2F58255453001', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
