INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397683788', 'Kit 50 Copos Copo 300ml Festa Bebidas Refri Sucos Descartável Lavável Acrílico Resistente Cores', 'Kit C/50 Copos 300ml Festa Descartáveis Acrílico Resistente 50 Copos Refrigerante 300ml Para Bebidas em Geral Acrílico Deixe seu dia mais prático com os copos PLAZAPEL, produzidos com matéria prima de alta qualidade, oferecem higiene, resistência e versatilidade. O produto é fabricado em polipropileno PS, material que confere alta qualidade e resistência a impactos. Atóxico, este produto pode entrar em contato com os líquidos sem transferir odor ou gosto. Copo em acrílico descartável resistente para deixar a decoração da sua festa ou evento mais estilosa. A embalagem do Copo Acrílico contém 10 unidades e é ideal para servir sucos, água, refrigerantes, cervejas e até mesmo sobremesas e sorvetes aos convidados de sua festa. Os copos acrílicos conferem muita praticidade as suas refeições, mas sem perder o charme. POR SUA RESISTÊNCIA É ideal para lanchonetes, festas, shows, eventos, aniversários, confraternizações, acampamentos, pescaria, fast-food, food truck e muito mais. A PLAZAPEL possui uma linha completa em descartáveis, entre copos, pratos, talheres e canudos tradicional e biodegradáveis Os copos lisos da Plazapel, são mais estruturados e resistentes, e a distribuição da matéria prima é uniforme , por isso o copo não fica manchado. Características do produto > Cor: Escolher no ato da compra > Material: Poliestireno (PS) em alta resistência > Produto Atóxico: Sim > Embalado em cor única > Contém: 5 pacotes com 10 Unidades cada = 50 Copos > Modelo: CR300 Medias do produto > AxL: 11,2 x 7,5cm - Marca: Plazapel - Garantia: 3 meses contra defeitos de fabricação Vantagens de comprar na Brester: - Nota fiscal para Pessoa Física e Pessoa Jurídica. - Produto original, novo, com garantia de fábrica. - Produto a pronta entrega. - Envio em até 48hs em dias úteis após confirmação do pagamento. Obrigado por escolher a Brester, Loja Oficial.', 70.07, 70.07, NULL, 'Home & Living > Party Supplies > Disposable Tableware', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m70z5sdkto4ne4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442506479%2F22397683788', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22897458532', 'Vestido Feminino Decote Com Zíper Em Moletom Flanelado', 'Vestido confeccionado em moletom flanelado. Esse modelo de comprimento curto e com shape Amplo, tendo o seu caimento mais folgado ao corpo, apresenta decote com abertura frontal por zíper, mangas longas com cavas deslocadas e barra e punhos marcados em textura. Além disso, ela foi feita em moletom flanelado, garantindo aquecimento e estilo. Com a textura flanelada, o item torna-se ainda mais macio, confortável e aconchegante para o uso no dia a dia. Aposte em um visual urbano e street, combinando com bota tratorada e jaqueta Malwee! Vestido Amplo em Moletom Flanelado Decote com Zíper Frontal Mangas Longas Cavas Deslocadas Situação de Uso: Casual e Dia a Dia', 130.9, 117.81, NULL, 'Women Clothes > Dresses', 'https://cf.shopee.com.br/file/sg-11134201-7rd6n-lu6pfl5jnl5a87', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939838662%2F22897458532', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
