INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594143126', 'Catraca Roda Livre Index Rosca Bike Mtb 7v 14-28 + Corrente 7v', 'A Catraca Roda Livre 7 Marchas 14/28 Index Sunrun Ultima Preta é perfeita para os amantes de mountain bike. Com sua cor dourado-escuro, ela traz um toque de estilo para sua bicicleta. Feita em aço resistente, garante durabilidade e desempenho. Com um mecanismo de transmissão de catraca, você pode alternar entre as 7 marchas com facilidade. Com uma quantidade máxima de dentes de 28 e mínima de 14, você terá opções para enfrentar diferentes terrenos. Fácil de montar com seu sistema de rosca. Aproveite essa oportunidade de melhorar sua experiência de pedalada com a Catraca Roda Livre 7 Marchas 14/28 Index Sunrun Ultima Preta. Marca: Sunrun OU Paco (Mesma importadora) Catraca Indexada para relações de 7 velocidades, fixação com rosca Compatível com Shimano, Sunrace, Gta, Paco, entre outros... Material: Aço carbono Escalonamento: 14/16/18/20/22/24/28 Peso: 460g CORRENTE TEC 7V Marca: Tec Modelo: C30 Corrente para Bicicleta em aço Compatível com 21 marchas Medida: 1/2 X 3/32 polegadas 116 elos Composição: Aço', 41.43, 41.43, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7raso-maur9l1h2z2b0d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F22594143126', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
