INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13033501047', 'Shampoo Seda Infantil Tiana Juntinhos Crespos Encantados com 300ml', '• Shampoo Crespos Encantados • Hidratação e brilho para os cachinhos • O Shampoo Seda Juntinhos é feito com ingredientes que limpam, hidratam e dão brilho aos crespinhos, além de deixar-los com um cheirinho delicios • Seda não testa em animais. • * inclusão de pelo menos 39% de plástico reciclado. • * Nossa garrafa é feita com plástico reciclado ** e é 100% reciclável Novo Seda Juntinhos traz para a hora do banho as aventuras das personagens mais amadas pelas crianças. É diversão para os pequenos e cuidado com seus cabelos, já que o Shampoo Seda Juntinhos é feito com ingredientes que limpam, hidratam e dão brilho aos crespinhos, além de deixá-los com um cheirinho delicioso! Como usar: Coloque nas mãos e aplique-o diretamente nos cabelos. Massageie bem e enxágue. Quer resultados ainda mais incríveis? Use também o Condicionador Seda Juntinhos Tiana', 21.58, 21.58, NULL, 'Mom & Baby > Bath & Body Care > Hair Care & Body Wash', 'https://cf.shopee.com.br/file/595262ebd0cb0c4bf03ebe5a61072651', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F546513063%2F13033501047', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49062297022', 'Mini Triturador de Alimentos Tupperware Turbo Chef Supersonic Vermelho 300ml', 'Para facilitar o seu dia a dia e te livrar do cheiro de alimentos nas mãos, a Tupperware® desenvolveu o Turbo Chef, que com apenas 15 segundos realiza o corte de 28 facas. Ideal para o corte de legumes, frutas e condimentos, a lâmina tripla em aço é inoxidável é acionada quando a corda do produto é puxada. Com a qualidade das lâminas, você terá em sua mesa cortes precisos que equivalem a 19 cortes por segundo. A base é transparente e possui antiderrapante para garantir firmeza no manuseio do produto.', 309.29, 265.05, NULL, 'Home Appliances > Kitchen Appliances > Food Processors & Meat Grinders', 'https://cf.shopee.com.br/file/sg-11134201-824g6-mpi3dl3s9p8r0f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1608053305%2F49062297022', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22893846352', 'Motor A Diesel Estacionário BFD 10CV 4 Tempos com Partida Manual Buffalo', 'Motor Diesel Estacionário BFD 10CV Partida Manual Buffalo O Motor BFD 10.0 Diesel 4T da Buffalo é a escolha ideal para quem busca potência, eficiência e durabilidade em um motor versátil e confiável. Projetado para atender às demandas de aplicações industriais, agrícolas e de construção, este motor combina desempenho robusto com baixo consumo de combustível, tornando-o perfeito para tarefas pesadas e contínuas. Destaques do Produto: *Potência robusta: Com 10 CV de potência máxima e 9 CV de potência contínua, este motor é capaz de lidar com as tarefas mais exigentes. *Eficiência de torque: Oferece um torque máximo de 2,8 Kgf.m a 2000 rpm, garantindo excelente desempenho mesmo em baixas velocidades. *Consumo econômico: Com um consumo médio de apenas 2,1 L/h, é uma opção altamente eficiente para operações prolongadas. *Lubrificação eficiente: Sistema de lubrificação forçada por bomba mantém os componentes internos bem lubrificados, prolongando a vida útil do motor. *Garantia de 6 meses: Proteção contra defeitos de fabricação, oferecendo tranquilidade e confiança ao usuário. Por Que Escolher Este Motor? O Motor BFD 10.0 Diesel 4T se destaca pela sua confiabilidade e versatilidade. Com uma cilindrada de 418 cm³ e uma alta taxa de compressão de 20:1, ele oferece resposta rápida e desempenho superior em diversas aplicações. Além disso, seu tanque de combustível de 5,5 litros para Diesel S500 garante uma operação contínua e eficiente. Projetado para ser compacto e portátil, com dimensões de 520 x 500 x 550 mm e peso líquido de 42,8 kg, este motor é fácil de transportar e instalar em diferentes configurações. Seja para uso em geradores, bombas, máquinas agrícolas ou equipamentos industriais, o Motor BFD 10.0 Diesel 4T é a solução ideal para quem busca potência e eficiência sem abrir mão da durabilidade. Informações Técnicas Tipo: Diesel 4T - Refrigerado a Ar Potência Máxima: 10,0 CV (7,4 kW) a 3600 rpm Potência Contínua: 9,0 CV (6,7 kW) a 3600 rpm Torque Máximo: 2,8 Kgf.m a 2000 rpm Cilindrada: 418 cm³ Combustível: Diesel S500 (capacidade de 5,5 litros) Aplicações Ideais: * Geradores de energia * Bombas de água * Maquinário agrícola * Equipamentos industriais e de construção Escolha o Motor BFD 10.0 Diesel 4T da Buffalo e tenha um equipamento que combina potência, eficiência e confiabilidade para enfrentar os desafios mais exigentes. Invista em qualidade e desempenho com a Buffalo!', 4348.13, 4348.13, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rd46-m7mn6zf7d2j8de', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F984366979%2F22893846352', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16468484699', 'A Rainha de Sabá - Knut Hamsun', 'Esta obra apresenta três obras de Knut Hamsun: A Rainha de Sabá A Morte de Glahn e O Sonhador. Hamsun foi um dos maiores escritores do século XX embora suas melhores obras tenham sido escrita antes de 1900. Autor de muitos livros que vão da prosa à poesia do conto romance e novela ao teatro é como romancista que se tornou mais conhecido.', 24.0, 10.0, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/a1c14b03223c25ba89355203600e2330', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F16468484699', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
