INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23397461115', 'Bomba De Agua Fiat Palio 1.0 1.5 96 97 98 99 Brosol Urba', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação FIAT PALIO CITY 1.0 4P 1999 PALIO CITYMATIC 1.0 MPI 1999 PALIO ED 1.0 MPI 2P E 4P 1996 até 1999 PALIO EDX 1.0 MPI 2P 1996 até 1999 PALIO EDX 1.0 MPI 4P 1996 até 1999 PALIO EL 1.5 MPI 2P E 4P 1996 até 1999 PALIO ELX 1.0/ 1.0 FIRE FLEX 8V 2P 1999 PALIO ELX 1.5 4P 1999 PALIO ELX/ 500 1.0 4P 1998 até 1999 PALIO EX 1.0 MPI 2P 1998 até 1999 PALIO EX 1.0 MPI 4P 1998 até 1999 PALIO WEEKEND 1.0 6-MARCHAS 1996 até 1999 PALIO WEEKEND 1.5 MPI 4P 1997 até 1999 PALIO WEEKEND ELX 1.5 MPI 4P 1998 até 1999 PALIO WEEKEND EX 1.5 MPI 1999 Conteúdo Da Embalagem 1 Bomba D''agua Cor do Produto No Tipo de Veículo para Carros Marca Há mais de 50 anos, os produtos Brosol são reconhecidos em todo o Brasil por sua qualidade, desempenho e durabilidade. Nossos carburadores e bombas de combustível são os únicos produzidos no país a partir dos projetos originais desenvolvidos com as montadoras. Para atingir essa excelência, todo o processo de produção é certificado pela norma ISO 9001 e realizado pela nossa equipe de colaboradores. Somos responsáveis desde a fundição do alumínio e zamac, brasagem e usinagem de precisão até as etapas de montagem, calibração e testes. O Produto A bomba de água é um componente que atua no sistema de arrefecimento de motores à combustão interna. Esse sistema resfria o motor do carro e evita o superaquecimento. Para isso, utiliza água, bem como o aditivo de radiador que torna esse precioso líquido ainda mais adequado para exercer sua função, que é a de retirar o calor interno do motor. Rotor de metal e corpo de alumínio - Sem polia. Importante •Recomendamos que os produtos sejam instalados por profissionais especializados e não se responsabiliza pelo mau uso ou instalação indevida, causando a perda da garantia. • Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. • Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. • Tempo de garantia: 6 meses • Valor Unitário • Imagem meramente ilustrativa •Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 EAN 7892391051975 Código do Fabricante UB764 Material do Corpo metal', 82.55, 82.55, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd48-lwddj0r85iy76d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F23397461115', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694176208', 'Par Lift Dianteiro Calço Suspensão 2 Polegadas S10 2012-2024', '--->>>Atenção a colocação desse produto pode ocasionar a dimunuição da vida útil das peças da suspensão. Por se tratar de um item de adaptação.Par Lift Dianteiro Calço Suspensão 2 Polegadas S10 2012 2013 2014 2015 2016 2017 2018 2019 2020 2021 2022 2023 2024O Lift de suspensão permite elevar a suspensão do veículo com o objetivo de melhorar a performance do mesmo em terrenos off-road (Trilhas e Rallys). Com essa alteração da altura original do veículo, o desempenho em trilhas torna-se muito melhor, uma vez que é possível transpor obstáculos tais como atoleiros, erosões e quaisquer dificuldades com maior facilidade, pois o veículo estará mais alto em relação ao solo. Com isso, também permite-se a colocação de pneus bem maiores, além do visual do veículo ficar bem mais imponente.Especificações técnicas:Lift de 2 polegadas para subir 5 Cm de altura na dianteira.Fabricados em aço 1020.Pintura eletrostática, preto fosco.Não precisa de adaptações.Conteúdo da embalagem:02 - Calços DianteirosCompatível com:S10 2012 à 2024.(Compatível para todas as versões Cabine Simples e Dupla) Garantia de 3 meses contra defeitos de fabricação.Recomendamos que a instalação seja realizada por um profissional.Imagens ilustrativas.------------------------------Lift Dianteiro S10 2012/...------------------------------Atenção: As compras realizadas em nome de Pessoa Jurídica estão sujeitas à cobrança de ICMS, conforme Protocolo ICMS 41, de 4 de Abril de 2008. Caso você tenha dúvidas sobre o percentual (%) a ser aplicado, consulte a Cláusula Segunda, 1 do referido Protocolo.', 239.88, 239.88, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-7ra13-mbfnpgw8wm93b7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1229982526%2F22694176208', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
