INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23492682488', 'Modelador Salon Line #Todecacho Antifrizz 120gr', '#html-body [data-pb-style=A71TLTS]{justify-content:Flex-start;display:Flex;flex-direction:Column;background-position:Left top;background-size:Cover;background-repeat:No-repeat;background-attachment:Scroll}Descrição: A Modeladora #todecacho Antifrizz proporciona uma modelagem flexível com efeito matte e blindagem do frizz. É Ideal para acabamentos e penteados. Dermatologicamente e oftalmologicamente testada. Ativos: A Modeladora #todecacho Antifrizz para texturas grossas, médias e finas possui rosa-mosqueta e água de rosas. Sua fórmula com ação condicionante promove hidratação, modelagem, fixação flexível e controle total do frizz. Modo de Uso: Espalhe o produto entre os dedos e aplique sobre os fios. A aplicação ideal dependerá da quantidade e do comprimento dos fios. Não enxágue.', 25.06, 25.06, NULL, 'Beauty > Hair Care > Hair Styling', 'https://cf.shopee.com.br/file/sg-11134201-7rblu-lp6mvm7vxl0a6d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F23492682488', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23397173945', 'Escova De Cabelo Marco Boni Thermal Ceramic Premium 36Mm', 'A Escova Profissional Marco Boni possui cerdas com dupla altura (javali e de nylon) que proporciona maior tração aos fios e tufagem reta, que desliza com mais facilidade nos cabelos. Seu cabo antideslizante e também possui separador de mechas. Faz parte da linha de escovas Thermal Ceramic, na qual todas possuem corpo revestido de cerâmica; ajuda a manter a temperatura do secador de modo uniforme e prolongado; agiliza a secagem. Tamanho: 36mm Modo de uso: Antes de iniciar a escovação, deixe seus cabelos quase completamente secos. Em seguida, reparta os cabelos em mechas finas, separando a parte do topo da cabeça para garantir mais volume às raízes, e prepare-se para começar. Alterne as direções e os ângulos para os quais as mechas são escovadas. #html-body [data-pb-style="646BA64FD4B0A"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA64FD4B1E"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 83.04, 83.04, NULL, 'Beauty > Beauty Tools > Hair Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rbml-lp5j187zvyta90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F23397173945', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
