INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20699648979', 'Kit Creme Hidratante Nivea Lata Média 29g - 3 Unidades - Hidratação Intensa e Proteção', 'Creme Hidratante Nivea Lata Média 29g O Hidratante Facial Nivea Creme é um dos produtos mais tradicionais e amados nos cuidados com a pele, oferecendo hidratação intensa e proteção contra o ressecamento. Com mais de 100 anos de história, é indicado para todas as partes do corpo, principalmente áreas mais ressecadas como joelhos, cotovelos e pés. Sua fórmula rica previne o surgimento de rugas e proporciona emoliência duradoura. ✨ Principais Benefícios: ✅ Hidratação intensa e duradoura ✅ Previne o ressecamento em áreas mais secas ✅ Ajuda a prevenir rugas e combate a flacidez ✅ Com Eucerit e Glicerina, garantindo um cuidado completo e eficaz ✅ Sem conservantes e adequado para todos os tipos de pele 🌿 Modo de Uso: Aplique o Hidratante Facial Nivea Creme sobre o corpo, rosto e mãos sempre que sentir a necessidade de hidratação intensa. Ideal para o uso diário. Uso externo. Com o tradicional cheirinho Nivea, cuide da sua pele com todo o carinho e proteção que ela merece!', 90.99, 90.99, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/sg-11134201-7rd5g-m7clwluon1xy56', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F20699648979', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
