INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22696346556', 'Taurina 500g 100% Pura Importada 4well Sabor Natural', 'Na 4well, acreditamos que sentir-se bem não precisa ser complicado. Por isso, desenvolvemos uma linha de suplementos e vitaminas práticos e eficazes que podem se encaixar perfeitamente em sua rotina diária. Com o nosso lema "É prático sentir-se bem!", buscamos oferecer soluções convenientes para ajudá-lo a alcançar seus objetivos de saúde e condicionamento físico. Manter uma alimentação balanceada desempenha um papel crucial na promoção da qualidade de vida. Diante do estilo de vida acelerado que muitas pessoas enfrentam, por vezes, torna-se desafiador atender a todas as necessidades nutricionais essenciais para garantir a saúde e a vitalidade do corpo. Nesse contexto, os suplementos desempenham a função de complementar a dieta, auxiliando na obtenção das vitaminas, minerais, proteínas e demais componentes fundamentais para o adequado funcionamento do organismo', 49.9, 49.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9ywi7sczyux4d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F346351615%2F22696346556', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
