INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250131304', 'Colchão Casal de Molas Superlastic High Support IN Ecoflex - 138x188', 'Colchão Casal de Molas Superlastic High Support IN Ecoflex - 138x188 O Colchão Casal High Support de 138x188 cm da Ecoflex é ideal para você ter uma excelente noite de sono. Fabricado com sistema de Molas Superlastic, é desenvolvido para atender biotipos diferenciados, com molas de fio contínuo, trabalhadas no sistema de união. Esse sistema distribui de forma adequada a pressão exercida, possui nível de conforto firme e é indicado para pessoas que não se adaptam a um sistema de molejo que ofereça grande flutuação. Ainda conta com tratamento antiácaro, antifungo e antialérgico. Características do produto: Modelo: High Support Modelo de colchão: Casal Tipo de colchão: Molas Superlastic Nível de conforto: Firme Revestimento: Tecido malha com bordado localizado, Lâminas de espuma D20 2 cm e D20 1 cm Acabamento: Debrum Tratamento no tecido:Antiácaro, Antialérgico, Antifungo Faixa Lateral: 100 Poliéster Respiros laterais:Sim Bordas: Polyframe - Caixa de espuma de alta densidade que envolve o molejo, com a função de manter o colchão nivelado. Tampo: Malha 86 poliéster 14 viscose Peso suportado por pessoa: 120 kg Observações: Não acompanha sommier. Certificado pelo Inmetro: Sim Dimensões: Altura: 26 cm Largura: 138 cm Profundidade: 188 cm Peso: 29.20 kg Atenção: Este móvel não acompanha itens de decoração e base. Imagem meramente ilustrativa! Garantia do fornecedor de 3 Meses', 1187.63, 1187.63, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-8257y-mgf2umrhmpl61c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1630032069%2F58250131304', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
