INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26941373889', 'Sapatênis Pegada Anilina Preto - Masculino', 'Sapatênis Pegada Anilina Preto - Masculino O Sapatênis Pegada Anilina Preto é confeccionado em couro, garantindo durabilidade e excelentes características físico-mecânicas. O forro em tecido espumado proporciona conforto e absorção de suor, mantendo os pés secos e arejados. Com solado antiderrapante de alta flexibilidade, feito em material de bidensidade, oferece segurança e versatilidade para o uso diário. O sistema AMORTECH de amortecimento no solado e na palmilha interna em PU macio na região do calcanhar reduz o impacto durante o caminhar. Além disso, o modelo conta com zíper lateral e atacador em elástico para um Calce Fácil. Ficha Técnica: Marca: Pegada Material do Cabedal: Couro Forro: Tecido Espumado Solado: Antiderrapante de Bidensidade Tecnologia: Amortech Fechamento: Elástico e Zíper Gênero: Masculino Cor: Preto Conteúdo da Embalagem: 1 Par de Sapatênis Pegada Anilina Preto - Masculino', 289.99, 289.99, NULL, 'Men Shoes > Slip Ons & Mules', 'https://cf.shopee.com.br/file/sg-11134201-824hj-mehjudodzcp3fb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F26941373889', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18099078844', 'Calha de Chuva Defletor Inteiriça/Slim Fiat Fastback 2022/2023 4 Portas em Acrílico TGPoli-24.030', 'Calha de Chuva Defletor Slim Inteiriça Fiat Fastback 2022 em diante 4 Portas Acrílico Preto Fumê TGPoli - TG01100196 Jogo de calhas de chuva para as portas do seu carro evitam que entre água ou que os vidros fiquem embaçados. Com essa calha você pode deixar os vidros um pouco aberto para a circulação do ar mesmo em dias de chuva, melhorando a visibilidade do motorista e reduzindo o ruído do vento. Características: Marca: TG POLI Modelo: TG01100196 *Imagens meramente ilustrativas Especificações técnicas: - Peso: 1,370 KG - Dimensões da embalagem (AxLxP): 0,042 x 0,222 x 1,07 metros - Cor: Preta Fumê - Aplicação: Parte Superior da Porta - Encaixe Sob Medida - Fixação: com Fita Dupla Face (Acompanha o Produto) - Possui Proteção Contra Raios UV - Material: 100% Acrílico - Alta Resistência - Alta Durabilidade Veiculos Compativeis: - Fiat Fastback 2022 e 2023 Conteúdo da Embalagem: - 2x Calhas Traseiras - 2x Calhas Dianteiras - 1x Kit Instalação', 246.83, 212.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rff2-m9iw2wt1fx61b4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F18099078844', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
