INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19897982363', 'Shampoo Cabelos Loiros Braé Stages Blonding 250ml', 'O Shampoo Braé Stages Blonding 250ml foi especialmente formulado para cuidar de cabelos loiros, descoloridos ou grisalhos. Ele neutraliza os tons amarelados indesejados, proporcionando um loiro luminoso e vibrante, enquanto limpa suavemente os fios sem ressecar. Principais benefícios: Neutralização de tons amarelados: mantém o loiro frio e uniforme. Realce do brilho: deixa os cabelos loiros mais radiantes e com aparência saudável. Limpeza delicada: remove impurezas sem agredir a fibra capilar. Hidratação e maciez: evita o ressecamento comum em cabelos loiros e descoloridos. Modo de uso: Aplique o shampoo nos cabelos molhados, massageando suavemente o couro cabeludo e os fios até formar espuma. Deixe agir por 2 a 3 minutos para potencializar o efeito matizador. Enxágue bem. Se necessário, repita a aplicação. Dica especial: Para um cuidado completo, combine o shampoo com o Condicionador Braé Stages Blonding e outros produtos da linha para garantir proteção, hidratação e manutenção da cor.', 101.72, 49.17, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rfha-m30uwyoaecxn60', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F361729924%2F19897982363', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259452189', 'Lacta Bis Xtra Oreo Wafer', 'O Wafer Bis Xtra Oreo é a combinação perfeita do wafer crocante com o sabor irresistível de Oreo. Uma explosão de sabores em cada mordida! * Cobertura de chocolate branco e biscoito Oreo * Snack perfeito para qualquer momento e lugar * Ideal para dividir e transformar momentos em experiências irresistíveis', 5.49, 5.49, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/sg-11134201-825av-mqnel8x3k0sh18', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555142%2F58259452189', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294879076', 'Kit 2 Unidades Molho Shoyu Satis! para Legumes e Verduras 500ml', 'Satis!® Molho Shoyu é um tempero líquido que oferece mais sabor às preparações do dia a dia, realçando o sabor dos alimentos e proporcionando uma cor dourada aos pratos. Disponível em duas versões: - Suave – ideal para saladas e preparações frias; - Tradicional – ideal para carnes, aves e preparações quentes. Pode ser utilizado a gosto, tanto no preparo quanto na finalização dos pratos. É ideal para marinadas, pratos orientais e asiáticos, arroz, legumes, carnes, aves, molhos e bases, além da finalização de preparações quentes e frias.', 46.42, 46.42, NULL, 'Food & Beverages > Cooking Essentials > Seasonings & Condiments', 'https://cf.shopee.com.br/file/sg-11134201-8261s-mlcpvcsgyght6d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1598062483%2F23294879076', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
