INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209461743', 'Nestlé Creme Tradicional Sorvete', 'O Sorvete de Creme Tradicional Nestlé é a escolha ideal para quem busca a simplicidade e o prazer de um sorvete clássico. Em um pote de 1,5L, este sorvete oferece uma textura cremosa e um sabor suave que encanta a todos, seja em uma sobremesa rápida ou em momentos especiais.', 30.49, 30.49, NULL, 'Food & Beverages > Dairy & Eggs > Ice cream', 'https://cf.shopee.com.br/file/sg-11134201-8259a-mqneloeo1o25b2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555142%2F58209461743', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094345941', 'Marreta quadrada 3kg com cabo em fibra 109229 - MTX', 'Produto: Marreta quadrada 3kg com cabo em fibra - 109229 Marca: MTX Descrição: A Marreta Quadrada MTX, sua parceira ideal para os trabalhos mais pesados de construção e demolição. Designed especificamente para suportar as demandas intensas de profissionais, este martelo combina durabilidade excepcional com performance superior. Características: • Potência Acentuada: Com uma cabeça de 3000 g e cabo de 900 mm, esta marreta proporciona golpes poderosos e controlados, ideais para quebrar concreto, tijolos ou pedras. • Durabilidade Avançada: Fabricada com aço médio carbono de alta qualidade e temperada até 40-45 HRC, a cabeça oferece resistência superior contra rachaduras ou deformações. • Proteção Contra Corrosão: Um revestimento especial em tinta preta sobre a cabeça assegura uma proteção extra contra a corrosão, aumentando a vida útil do produto. • Conforto e Segurança: A alça de plástico, reforçada com fibra de vidro, e o revestimento de borracha garantem uma pegada segura e um manuseio confortável, reduzindo o risco de acidentes. Especificações: Perfil da marreta: Quadrado Material da marreta: Aço médio carbono Superfície da cabeça: Revestida com tinta preta Material do cabo: Plástico reforçado com uma haste de fibra de vidro. Dimensões (C x L x A): 91.00 x 14.00 x 6.00 centímetros Peso: 3.00 Kg', 181.8, 181.8, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-825b4-mr05izajdzid0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F23094345941', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19198596161', 'Fita dupla face espuma 25mm x 2m FDF-252 - Hammer', 'Produto: Fita dupla face espuma 25mm x 2m FDF-252 Marca: Hammer Descrição: Fita Dupla Face Espuma 25mm x 2m FDF-252 Hammer é a solução prática e eficiente para quem busca fixação ultraforte em ambientes internos. Ideal para instalar pequenos objetos de decoração, cartazes, molduras e peças plásticas, ela proporciona excelente aderência sem complicações, garantindo mais praticidade no dia a dia. Fabricada com EVA branco e adesivo acrílico, a fita dupla face Hammer oferece alta performance em diferentes superfícies lisas, limpas e secas, como azulejos, gesso, madeira e vidro. Seu formato de 25mm x 2m é versátil e atende diversas necessidades de fixação com acabamento discreto e seguro. Perfeita para quem deseja evitar furos e sujeira, a fita dupla face de espuma Hammer é fácil de aplicar e entrega firmeza na instalação de itens decorativos com rapidez e eficiência. Uma escolha inteligente para projetos residenciais, organização e pequenos reparos. Escolha a Fita Dupla Face Espuma Hammer 25mm x 2m e tenha mais segurança, praticidade e acabamento na fixação dos seus objetos. Um item indispensável para quem procura fita dupla face forte com qualidade e excelente custo-benefício. Especificações: Medidas: 25mm x 2m Material: EVA branco e adesivo acrílico Capacidade: 300g a cada 15 cm. Peso: 0.15 Kg', 22.68, 22.68, NULL, 'Stationery > Gift & Wrapping > Ribbons', 'https://cf.shopee.com.br/file/sg-11134201-8258w-mqwb063liyh1e4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F19198596161', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29480824129', 'Par Palheta Limpador Parabrisa Original Bosch Multiclip BMW X6 2014 à 2019', 'PAR DE PALHETA DIANTEIRO PARA-BRISA BOSCH A Palheta Aerofit Multiclip foi desenvolvida com alta tecnologia para oferecer máxima qualidade e resistência OBSERVAÇÃO: AS PALHETAS SÃO ENVIADAS COM O ADAPTADOR COMPATIVEL AO VEÍCULO KIT CONTÉM: 1 PALHETA LADO MOTORISTA 24 POLEGADAS 1 PALHETA LADO PASSAGEIRO 20 POLEGADAS O Grupo Yamase é Posto Autorizado BOSCH CAR SERVICE desde 2002. Nossos produtos são ORIGINAIS da Marca BOSCH e acompanham NOTA FISCAL.', 133.92, 133.92, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m7s3d8kuq43m22', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F29480824129', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22196635327', 'Kit Shampoo V-Floc Cera Blend Spray Vitrificadora Restaurax Vonixx', 'KIT CONTÉM: V-FLOC 500ML RESTAURAX 500ML BLEND SPRAY PINCEL EXTERNO PANO 40X40CM APLICADOR DE ESPUMA VONIXX ESPONJA AZUL ---------------------------------------------------------------- V-FLOC 500ML - LAVA AUTOS SUPER CONCENTRADO DESCRIÇÃO: V-Floc é um lava autos de alta performance e de pH neutro. Sua fórmula contém agentes condicionadores e tensoativos especiais que proporcionam uma lavagem suave e eficiente. MODO DE USO: 1. Realizar a pré-lavagem do veículo para retirada do excesso de sujeira 2. Diluir aproximadamente 10ml de V-FLOC em 4 litros de água; Recomendamos ajustar a quantidade de produto de acordo com o nível de sujeira 3. Iniciar a lavagem com o auxílio de Luva de Microfibra, sempre começando pela parte superior do veículo 4. Mergulhar a luva na solução e esfregar suavemente, até completar todo o veículo 5. Enxaguar em seguida até a retirada de todo o produto 6. Recomendamos o uso da Toalha de Secagem para finalizar ---------------------------------------------------------------- BLEND CERAMIC SPRAY WAX 500ML - CERA LÍQUIDA COM SIO2 E CARNAÚBA DESCRIÇÃO: Blend Ceramic & Carnaúba Spray Wax é uma cera híbrida, composta por SiO2 e pela mais pura carnaúba tipo 1 e que protege a superfície veicular por até quatro meses. O produto promove a resistência cerâmica, brilho quente da carnaúba e hidrorrepelência. DURABILIDADE: Até quatro meses de durabilidade MODO DE USO: 1. Agite bem o produto antes de usar 2. Após lavar o veículo, pulverize uma pequena quantidade do produto na pintura. Mantenha uma distancia de 20 cm em uma área não superior à 60 cm x 60 cm 3. Sem deixar secar, realize o acabamento utilizando toalha de microfibra limpa e seca, até obter o brilho desejado 4. Continue fazendo o processo até a conclusão total do veículo Obs: Em caso de manchas, aplicar novamente o produto. ---------------------------------------------------------------- RESTAURAX 500ML - RESTAURADOR DE PLÁSTICOS DESCRIÇÃO: Restaurax renova e restaura superfícies plásticas, como para-choques, painéis e laterais de portas. Sua fórmula contém polímeros especiais que também protegem as peças contra as ações do tempo, evitando degradação precoce do material. DURABILIDADE: Até seis meses de proteção nos plásticos internos e sessenta dias nos plásticos externos. MODO DE USO: 1. Limpar bem a superfície e em seguida aplicar o produto com um aplicador de espuma até a completa restauração. Se necessário, repetir a operação. 2. Para manter o plástico sempre novo, repetir a aplicação do produto a cada 60 dias na parte externa e a cada 6 meses na parte interna. Obs: Para um resultado com menos brilho, realizar acabamento com uma microfibra.', 172.92, 172.92, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Shampoo', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgjctn93hszrdb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F22196635327', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20697354848', 'Kit Lavagem Automotiva Cera Blend Spray Shampoo Restaurax 500ml', '1 - BLEND SPRAY 500ML VONIXX 1 - V-FLOC 500ML VONIXX 1 - RESTAURAX 500ML VONIXX 1 - LUVA MICROFIBRA JS 1 - APLICADOR DE ESPUMA VONIXX 1 - PANO 40X40 MICROFIBRA ------------------------------------------------------------ - BLEND SPRAY 500ML VONIXX DESCRIÇÃO: BLEND CERAMIC & CARNAÚBA SPRAY WAX é uma cera híbrida, composta por SiO2 e pela mais pura carnaúba tipo 1 e que protege a superfície veicular por até quatro meses. O produto promove a resistência cerâmica, brilho quente da carnaúba e hidrorrepelência. MODO DE USO: 1- Agite bem o produto antes de usar. 2- Após lavar o veículo, pulverize uma pequena quantidade do produto na pintura. Mantenha uma distancia de 20 cm em uma área não superior à 60 cm x 60 cm. 3- Sem deixar secar, realize o acabamento utilizando toalha de microfibra limpa e seca, até obter o brilho desejado. 4- Continue fazendo o processo até a conclusão total do veículo. ------------------------------------------------------------ - V-FLOC 500ML VONIXX DESCRIÇÃO: V-FLOC é um lava autos de alta performance e de pH neutro. Sua fórmula contém agentes condicionadores e tensoativos especiais que proporcionam uma lavagem suave e eficiente. V-FLOC tem alto grau de lubrificação, promovendo redução significativa do coeficiente de atrito, proporcionando um melhor deslize da luva de microfibra e reduzindo de forma efetiva as chances de microrriscos na pintura. V-FLOC também promove brilho e aspecto de renovação da pintura. MODO DE USO: 1- Realizar a pré-lavagem do veículo para retirada do excesso de sujeira; 2- Diluir aproximadamente 10ml de V-FLOC em 4 litros de água; Recomendamos ajustar a quantidade de produto de acordo com o nível de sujeira; 3- Iniciar a lavagem com o auxílio de Luva de Microfibra, sempre começando pela parte superior do veículo; 4- Mergulhar a luva na solução e esfregar suavemente, até completar todo o veículo; 5- Enxaguar em seguida até a retirada de todo o produto; 6- Recomendamos o uso da Toalha de Secagem para finalizar. ------------------------------------------------------------ - RESTAURAX 500ML VONIXX DESCRIÇÃO: RESTAURAX renova e restaura superfícies plásticas, como para-choques, painéis e laterais de portas. Sua fórmula contém polímeros especiais que também protegem as peças contra as ações do tempo, evitando degradação precoce do material. MODO DE USO: 1- Limpar bem a superfície e em seguida aplicar o produto com um aplicador de espuma até a completa restauração. Se necessário, repetir a operação. 2- Para manter o plástico sempre novo, repetir a aplicação do produto a cada 60 dias na parte externa e a cada 6 meses na parte interna.', 189.92, 189.92, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Shampoo', 'https://cf.shopee.com.br/file/br-11134207-7r98p-ll6lp8cdhedy14', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F20697354848', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17188423809', 'Luva de segurança anti-corte e proteção alta temperatura Delta Plus', 'Produto: Luva de segurança anti-corte e proteção alta temperatura - Venicut 52 Marca: Delta Plus Tamanho: G Descrição: Desenvolvida com fibra de alta performance HEATnocut a Luva de segurança anti-corte e proteção alta temperatura Venicut 52 da Delta Plus possui ótima resistência ao corte. O revestimento corrugado da palma proporciona excelente aderência para preensão dos objetos manipulados. Além disso, possui excelente resistência ao rasgo (EN388 3X42D) e calor de contato de até 250 °C (EN407 X2XXXX). Características: Fibra HEATnocut • Resistência máxima ao corte • Alta resistência à abrasão • Resistente ao calor de contato: até 250 °C Revestimento corrugado na palma • Excelente aderência para preensão dos objetos manipulados Ótima resistência ao corte • D CA 36.007 • Aprovada para proteção das mãos contra agentes abrasivos, escoriantes, cortantes, perfurantes e térmicos (calor de contato). Especificações: Composição: Polietileno de alto peso molecular (HPPE), para-aramida (AR) e borracha natural (NR: 2-metilbut-1, 3-dieno)CA: 36.007 Cor: Preta e amarela Comprimento: 25cm Tamanho: 9 - G. Peso: 0.12 Kg', 90.55, 90.55, NULL, 'Home & Living > Tools & Home Improvement > Protective Gloves, Goggles & Masks', 'https://cf.shopee.com.br/file/sg-11134201-825b5-mr4co38au22q74', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F17188423809', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20099357709', 'Cooler para Notebook Hp G4-1190BR', 'Cooler compatível com Hp G4-1190BR Interno Este é um Cooler bringIT compatível com o notebook Hp G4-1190BR. Os coolers para notebook da bringIT são a solução definitiva para possíveis problemas de ventilação e resfriamento do seu equipamento. Também conhecidos como “fans”, “ventiladores” ou “resfriadores”, os coolers são responsáveis pela retirada do máximo de calor gerado pelo processador e por outros componentes eletrônicos. Para evitar problemas de compatibilidade, compare as fotos deste anuncio com seu equipamento original. Assim você consegue verificar as principais informações de compatibilidade e demais especificações do seu cooler. Atenção: Esse é um cooler bringIT, portanto não é um produto original da fabricante Hp. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Informações Técnicas Quantidade de vias: 3 vias Corrente (Amperagem): 0.4A Tensão (Voltagem): 5V Garantia: 3 meses de garantia contra defeitos de fabricação Referência: CL008-HP-0573', 49.88, 44.89, NULL, 'Computers & Accessories > Desktop & Laptop Components > Fans & Heatsinks', 'https://cf.shopee.com.br/file/sg-11134201-8259h-mqtcymixqi9v39', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F20099357709', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18498293125', 'Bomba de Água 370W (0.5HP) 220V 35m 35L/min Cobre para Construção Irrigação e Drenagem', 'Potência Eficiente para Demandas Diversas A bomba de água EPICA STAR combina alta performance e durabilidade com seu motor de fio de cobre de 370W (0.5HP) e impulsor em cobre, garantindo operação estável a 2850 rpm. Ideal para construção civil, irrigação doméstica, agrícola e drenagem de áreas inundadas. Especificações Técnicas: Tensão: 220V ~ 50/60Hz Potência de Entrada: 370W (0.5HP) Elevação Máxima: 35 metros Vazão Máxima: 35 litros/minuto Diâmetro do Tubo: 1"x1" Cabo: 0.15 metros (prático para uso temporário) Altura de Sucção Máxima: 8 metros Vantagens Exclusivas: ✅ Dissipação de Calor Eficiente: Estrutura oca protege o motor e mantém a temperatura ideal, prolongando a vida útil. ✅ Materiais Premium: Motor e impulsor em cobre, resistentes ao desgaste e corrosão. ✅ Versatilidade: Atende desde pequenas irrigações até demandas de construção e emergências. ✅ Design Prático: Leve, portátil e com embalagem protegida para transporte seguro. Aplicações Ideais: Abastecimento de água em canteiros de obras Irrigação de jardins e plantações agrícolas Drenagem de porões, piscinas ou áreas alagadas Uso residencial e comercial Inclui: 1 Bomba EPICA STAR com garantia de qualidade e manual de instruções.', 1599.0, 1599.0, NULL, 'Home & Living > Tools & Home Improvement > Water Pumps, Parts & Accessories', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdli37railsh9b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1442717886%2F18498293125', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22092973923', 'Chumbo para Balanceamento Contrapeso Contra Peso Garra Baixa 45 Gramas Pacote Com 50 unidades', 'Anuncio referente a 01 PACOTE de Contrapeso de Chumbo Garra Baixa 45 gramas, sendo o pacote com 50 unidades de 45 gramas cada. ENCAIXE: Garra MATERIAL: Chumbo INDICACAO: Rodas de Ferro Marca GS CONTRAPESOS Produto novo, temos a pronta entrega. Somos uma empresa ha mais 35 anos no mercado de Auto Pecas. Nossos produtos sao somente novos. Teremos o prazer em atende-lo. ****Recomendamos que os produtos sejam instalados por profissionais especializados***', 298.35, 140.23, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rd3r-lu9npg33451e25', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316897655%2F22092973923', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20397617401', 'Kit Completo Lavagem de Moto Blend Spray V-Mol Pneu Pretinho Vonixx', 'KIT CONTÉM: 1- V-MOL 500ML VONIXX 1- BLEND SPRAY 500ML VONIXX 1- PNEU PRETINHO 500ML VINTEX 1- REJUVEX 400G VINTEX 1- APLICADOR DE ESPUMA 1- PINCEL ROMA 1- ESCOVA DE CORRENTE DETAILER 1- TOALHA DE SECAGEM 50X90 300GSM 1- LUVA MICROFIBRA JS ---------------------------------------------------------- BLEND CERAMIC SPRAY WAX 500ML - CERA LÍQUIDA COM SIO2 E CARNAÚBA DESCRIÇÃO: Blend Ceramic & Carnaúba Spray Wax é uma cera híbrida, composta por SiO2 e pela mais pura carnaúba tipo 1 e que protege a superfície veicular por até quatro meses. O produto promove a resistência cerâmica, brilho quente da carnaúba e hidrorrepelência. DURABILIDADE: Até quatro meses de durabilidade MODO DE USO: 1. Agite bem o produto antes de usar 2. Após lavar o veículo, pulverize uma pequena quantidade do produto na pintura. Mantenha uma distancia de 20 cm em uma área não superior à 60 cm x 60 cm 3. Sem deixar secar, realize o acabamento utilizando toalha de microfibra limpa e seca, até obter o brilho desejado 4. Continue fazendo o processo até a conclusão total do veículo Obs: Em caso de manchas, aplicar novamente o produto. ---------------------------------------------------------- V-MOL 500ML - LAVA AUTOS DESINCRUSTANTE DESCRIÇÃO: Produto lava autos desincrustante com pH levemente básico que não agride a superfície do veículo. Excelente na remoção de sujeiras mais difíceis como remoção de barro e óleo DILUIÇÃO: Sujeira leve/manutenção: 1:100 Sujeira Média: 1:50 Sujeira pesada 1:10 MODO DE USO: 1. Diluir o produto na proporção indicada. 2. Iniciar a lavagem com o auxilio de uma luva de mcrofibra, sempre começando pelas partes superiores do veículo 3. Mergulhar a luva na solução e esfregar suavemente até completar o veículo 4. Enxaguar em seguida até a retirada de todo o produto 5. Secar o veículo por completo a fim de evitar manchas ---------------------------------------------------------- PNEU PRETINHO 500ML VINTEX DESCRIÇÃO: O Pneu Pretinho é um produto que foi especialmente desenvolvido para proteger, conservar e dar brilho aos pneus em geral. Promove proteção prolongada, brilho intenso e duradouro que deixa os pneus com as pecto de novos. MODO DE USO: 1- Lave bem os pneus removendo toda a sujeira como lama, barro, etc; 2- Em seguida, aplique o produto puro com o auxílio do Aplicador de Espuma. ---------------------------------------------------------- REJUVEX 400G VINTEX DESCRIÇÃO: Rejuvex é um revitalizador de plásticos que renova e dá brilho em plásticos externos de automóveis em geral. Desenvolvidos com matérias-primas especiais, o produto é indicado para uso em oficinas de repintura automotiva. MODO DE USO: 1- Aplique uma pequena quantidade do produto sobre a superfícies limpa e seca 2- Com uma esponja, faça movimentos circulares até a total cobertura da peça', 206.8, 206.8, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Degreasers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lwe98005uq9i1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F20397617401', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493683791', 'Ar Condicionado Bi Split Elgin 18000 BTUS 2X9000 Inverter Quente e Frio 220V MTQE18C2CB', 'Ar Condicionado Bi Split Elgin 18000 BTUs (2x9000) Inverter Quente e Frio 220V O Ar Condicionado Bi Split Elgin 18000 BTUs é ideal para quem busca conforto térmico e eficiência energética em dois ambientes ao mesmo tempo. Com duas unidades internas de 9000 BTUs e uma única unidade externa, ele oferece uma climatização uniforme e personalizada para atender às suas necessidades. Tecnologia Inverter para Economia de Energia Com a tecnologia Inverter, o ar-condicionado ajusta automaticamente sua operação, mantendo a temperatura desejada de forma constante e silenciosa. Esse sistema proporciona maior eficiência energética, reduzindo o consumo de energia e garantindo economia na conta de luz. Conforto Inteligente e Funcionalidades Avançadas O Bi Split Elgin vem equipado com diversas funções inteligentes, pensadas para praticidade e bem-estar: ° Auto Restart: Retoma as configurações automaticamente após uma queda de energia. ° Timer: Programe o funcionamento conforme sua rotina, otimizando o uso e economizando energia. ° Auto Limpeza: Mantém o aparelho limpo e livre de impurezas, promovendo um ambiente mais saudável e aumentando a durabilidade do equipamento. ° Display Invisível: Design discreto e moderno, integrando-se perfeitamente à decoração do ambiente. ° Conectividade Wi-Fi: Controle o ar-condicionado à distância usando seu smartphone ou tablet, proporcionando praticidade e flexibilidade no ajuste de temperatura. ° Controle Remoto: Ajuste facilmente a temperatura e outras configurações, garantindo conveniência e conforto. Desempenho e Qualidade Elgin O Ar Condicionado Bi Split Elgin utiliza Gás Refrigerante R32, que é mais ecológico e eficiente. Além disso, a serpentina de cobre com aletas douradas garante maior durabilidade e resistência à corrosão. Com um sistema de filtragem de Nylon e Carvão Ativado, o aparelho oferece ar mais puro e livre de odores, proporcionando um ambiente mais saudável. Especificações Técnicas ° Marca: Elgin ° Modelo: MTQE18C2CB ° Capacidade Total: 18000 BTUs (2 unidades internas de 9000 BTUs) ° Voltagem: 220V ° Ciclo: Quente e Frio ° Tecnologia: Inverter ° Material da Serpentina: Cobre com aletas douradas ° Gás Refrigerante: R32 ° Vazão de Ar: 420 m³/h ° Consumo Nominal: ° Evaporadora: 35W ° Condensadora: 1598W ° Tipo de Filtragem: Nylon e Carvão Ativado ° Funções: Auto Restart, Display Invisível, Wi-Fi, Timer, Auto Limpeza, Controle Remoto ° Unidade Interna: 69,8 L x 25,5 A x 19 P cm | Peso: 6,5 kg ° Unidade Interna Embalada: 76,4 L x 32,5 A x 26,7 P cm | Peso: 8,5 kg ° Unidade Externa: 85,3 L x 60,2 A x 34,9 P cm | Peso: 31 kg ° Unidade Externa Embalada: 89 L x 62,8 A x 38,5 P cm | Peso: 33 kg ° Garantia: 36 meses O Ar Condicionado Bi Split Elgin 18000 BTUs Inverter é a escolha perfeita para quem busca tecnologia avançada, eficiência energética e conforto personalizado. Com design moderno, conectividade Wi-Fi e funções inteligentes, ele proporciona uma experiência prática e confortável em qualquer estação do ano.', 7399.99, 7399.99, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-7rbm8-m5u5cwdffuafcd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1059412251%2F23493683791', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209669126', 'Leite Condensado Semidesnatado Italac', 'O Leite Condensado Semidesnatado Italac é um produto cremoso e versátil, ideal para suas receitas doces, sobremesas, confeitarias e cafés especiais. Produzido com leite semidesnatado, ele contém 6% de gordura, oferecendo um equilíbrio perfeito entre sabor e leveza. Perfeito para seus pudins, doces e tortas.', 7.99, 7.99, NULL, 'Food & Beverages > Dairy & Eggs > Milk', 'https://cf.shopee.com.br/file/sg-11134201-825az-mqnellflq5n22a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555041%2F58209669126', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898304418', 'Conector DC Jack para Notebook Dell Inspiron 15-5567', 'Conector DC Jack compatível com Dell Inspiron 15-5567 Este é um DC Jack bringIT compatível com o notebook Dell Inspiron 15-5567. Ele é ideal para acabar com os problemas de alimentação de energia em um notebook. O DC Jack — ou DC Power Jack — é um conector interno responsável por intermediar a alimentação de energia entre a fonte (carregador) e o laptop. Este produto é um de alta qualidade e cumpre todas as especificações de segurança dos notebooks. Para evitar problemas de compatibilidade, compare as fotos deste anúncio com seu equipamento original. Assim você consegue verificar as principais informações de compatibilidade e demais especificações do seu notebook. Atenção: Esse é um dc jack bringIT, portanto não é um produto original da fabricante Dell. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Informações Técnicas Tamanho do Conector: 4.5mm x 3.0mm Cabo: Com Cabo Garantia: 3 meses de garantia contra defeitos de fabricação Referência: DC126-DE-0001', 45.2, 42.94, NULL, 'Computers & Accessories > Desktop & Laptop Components > Power Supply Units', 'https://cf.shopee.com.br/file/sg-11134201-8258q-mqt17dcass9a12', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F23898304418', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
