INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397130067', 'Travessa Forma de Pão 1,6 Litros N03 Alumínio, Antiaderente Grafite Cozinha MTA - 368', 'Travessa/Forma de Pão 1,6 Litros N03 Alumínio, Antiaderente Grafite MTA - 368 Nada como o cheirinho característico de cuca ou aquele pão perfumando nossa casa. Com a Forma para Pão 1.2mm em Alumínio com Revestimento Antiaderente o preparo de pães e bolos vai ficar ainda mais fácil e prático. Produzida em alumínio com revestimento interno e externo em antiaderente Superflon, garante um cozimento mais uniforme dos alimentos, além de evitar que os mesmos grudem. Fácil de limpar, pode ir à máquina de lavar louças. Versátil, pode ser utilizada em fornos a gás e elétricos. Características: - Marca: MTA - Referência: 368 *Imagens Meramente Ilustrativas Especificações Técnicas: - Cor: Grafite - Modelo: Cristal - Materiais: Alumínio - Fácil de Limpar - Antiaderente - Cozimento Uniforme Tipos de uso: - Fogão a gás - Elétrico - Vitrocerâmico - Lava-louça - Forno Conteúdo da embalagem: - 01x Travessa/Forma de Pão 1,6 Litros N03 Alumínio, Antiaderente Grafite MTA - 368', 48.73, 42.74, NULL, 'Home & Living > Kitchenware > Pots', 'https://cf.shopee.com.br/file/sg-11134201-7rbmn-lo1c8ne4xtxk5e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F22397130067', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393522439', 'Cilindro Mestre Freio SANTANA 1984 85 86 87 88 89 1990 - 2152 - C2009', 'Cilindro Mestre Freio SANTANA 1984 85 86 87 88 89 1990 DUPLO SEM RESERVATÓRIO (13/16" OU 20,63mm)_x000D_ _x000D_ • GOL 1981>1984_x000D_ • PARATI 1982>1984_x000D_ • SAVEIRO 1982>1984_x000D_ • VOYAGE 1982>1984_x000D_ • SANTANA 1984>1990 Sistema Varga / Bosch_x000D_ • PASSAT 1977>1984 Sistema Varga / Bosch Inicia Hidráulica do Freio, introduzindo e controlando o processo de frenagem. Injetando e comprimindo o óleo (fluído), gerando a pressão p/todo o sistema de freios. Cilindro Mestre Simples - A tampa do reservatório possui um respiro responsável por igualar as pressões internas, evita a formação de vácuo no caso do fluído de freio baixar. Cilindro Mestre Duplo - É a união de dois cilindros simples, esse conj. foi dirigido para dois circuitos de freio, podendo ser montado em paralelo ou diagonal.', 204.6, 204.6, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rbmt-lmxmvzog7x3t1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23393522439', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598243949', 'Mangueira Respiro Óleo PUNTO ATTRACTIVE 1.4 8v EVO 2013/2017 - 89612 - 4204', 'Mangueira Respiro Óleo PUNTO ATTRACTIVE 1.4 8v EVO 2013/2017 1.4 8v FIRE EVO (Medida: 17cm x 39cm)Essa mangueira serve para aliviar a pressão de dentro do cárter pelo vazamento dos gases dos anéis. Isso é normal e chama-se ventilação positiva. Esse gás é reabsorvido junto com o vapor do óleo pelo motor para ser queimado dentro da camara de combustão, por isso ela fica ligada logo na entrada de ar do motor, ou seja, junto do filtro de ar. Isso foi desenvolvido para não poluir o ar com esses gases.', 50.88, 50.88, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-8259j-mq1y1ozw0zkdd9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23598243949', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
