INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9728604782', 'Caixa Vazia Duto Regua 2 Falante 12 + 4 Cornetas + 2 Tweeter', 'Você que estava a procura de uma caixa acarpetada e selada de altissima qualidade, agora encontrou, uma excelente opção para seu projeto de som, tendo seu padrão de design da OESTESOM, de altissima qualidade, trata-se de um produto resistente, utiizado inclusive em paradão de som, campeonatos e muitos outros eventos. Não cometa um erro comprando em qualquer lugar, compre na OESTESOM. A OESTESOM trabalha constantemente, encontrando o que há de melhor na linha automotiva, para satisfazer os nossos clientes na medida certa; visando sempre eficiência, qualidade, e além disso um baixo custo. ------------------------------------ COMPRANDO, CHEGARÁ EM SUA RESDIÊNCIA: 1- Caixa Vazia Duto Regua 2 Falante 12 + 4 Cornetas + 2 Tweeter DESCRIÇÃO TÉCNICA • Caixa MD Vazia • Para 2 Falante 12 + 4 Cornetas + 2 Tweeter • Acarpetada • Comprimento: 89Cm • Profundidade: 31Cm • Altura: 48,5Cm --------------------------------------- VOCÊ ESTARÁ COMPRANDO UMA CAIXA VAZIA - SEM OS EQUIPAMENTOS (Falante, Driver, Tweeter, Radio, Modulo)', 436.36, 427.64, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/c82dc4b1bdac26d3f097d2e491d18eb8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328179142%2F9728604782', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
