INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12138728133', 'GUIA DE ESTUDO DO livro Campo De Batalha Da Mente | GUIA DE ESTUDOS | Joyce Meyer', 'Se você é um dos milhões que sofrem com preocupação, dúvida, depressão, raiva ou culpa, você está experimentando um ataque à sua mente. Superar pensamentos negativos que vêm contra sua mente traz liberdade e paz. Descubra como reconhecer padrões de pensamento prejudiciais e ponha um fim a essa influência em sua vida. Neste poderoso livro, a popular autora e conferencista Joyce Meyer, o conduz através de uma auto-avaliação honesta compartilhando as provações, tragédias e principais vitórias do seu próprio casamento, família e ministério incluído a verdade que ela aprendeu sobre o que estava pensando e sentindo a cada passo do caminho. Você aprenderá como Joyce ganhou a batalha em sua própria mente e como você também pode ganhar, 118 Págias 15x22cm', 28.9, 25.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/5e297f4668f75cc0e53834b640340990', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F12138728133', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193341175', 'Regata Fluminense Partner', 'Desenvolvida especialmente para os apaixonados torcedores do Fluzão, a regata do Fluminense, modelo Partner, é a escolha perfeita para todas as ocasiões. Confeccionada com poliéster leve e respirável, a peça traz tecido macio e confortável com excelente caimento ao corpo. Seu design traz as tradicionais cores da equipe, branco, verde e vermelho, em listras verticais por toda a composição. Além disso, o escudo do clube é visto estampado no lado esquerdo do tórax, assim como o ano de fundação da equipe no lado oposto. Por fim, a gola careca e as mangas regatas complementam os detalhes da peça. Adquira já a sua!Composição: 100% PoliésterEscudo: EstampadoOrigem: NacionalManga: RegataGola: CarecaDimensões Aproximadas (A x L):P: 73 x 55 cmM: 75 x 57 cmG: 77 x 59 cmGG: 79 x 61 cmEG: 81 x 63 cm', 113.9, 113.9, NULL, 'Men Clothes > Tops > Tanks', 'https://cf.shopee.com.br/file/sg-11134201-7rdy0-m0j4vv57f1id1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1337527569%2F23193341175', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
