INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17870365016', 'Filhos Irados | Uma Abordagem Bíblica | Lou Priolo', 'PÁGINAS: 240 BROCHURA MEDIDAS: 14 X 21 SINOPSE Há certos pecados que são tolerados para uma parcela significativa da igreja. A ira é um deles. Frequentemente reivindica-se ser esse um traço familiar que remonta ao avô, passa pelo pai e está presente também nos irmãos. Quando um pai entende que seu filho ao expressar ira pecaminosa manifesta, na verdade, somente um traço que lhe é próprio, perde a oportunidade de trabalhar o coração dele. Lou Priolo oferecerá neste livro conselhos úteis e práticos aos pais que pretendem lidar com as expressões da ira pecaminosa em seus filhos. Ele enfatiza que o cerne da ira pecaminosa é o coração do homem inclinado contra Deus, voltado para si e desejoso de fazer somente o que lhe agrada. Esse coração é naturalmente exigente, muitas vezes cruel, e não raro, não mede as consequências para obter o que deseja. Em sua abordagem, o autor oferecerá orientações, sugestões e ideias que o ajudarão na tarefa de treinar o seu filho para refletir o caráter do nosso Senhor Jesus Cristo nas mais diversas situações a que estiver exposto. Esta é a edição revisada do livro anteriormente publicado com o título "O Coração da Ira - Guia Prático para Lidar com a Ira dos Filhos". Autor: Lou Priolo', 34.9, 34.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/e4812a47a82ffb1d028d501a867168ac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F17870365016', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23999345534', 'Kit 3 Potes Infantil Papinha Lanchinho Buba Animal Fun', 'Kit 3 Potinhos Animais Buba O conjunto com 3 potinhos animais da Buba. É ideal para armazenar as papinhas, frutinhas e alimentos do pequeno. Além de prometer mais praticidade e segurança para as mamães, no assunto alimentação do bebê. Seu design é colorido e divertido. Coleção Animal FUN. Podem ser levados ao micro-ondas; freezer e lava louça. Medidas: 1 - Pote P 250 ml - 4,5 x 9,0 x 9,0 cm. 1 - Pote M 350 ml - 5,0 x 10,5 x 10,5 cm. 1 - Pote G 550 ml - 5,5 x 12,0 x 12,0 cm.', 40.57, 35.9, NULL, 'Mom & Baby > Feeding Essentials > Utensils', 'https://cf.shopee.com.br/file/sg-11134201-8262s-ml5hj5iiv2f41f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F23999345534', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22892672415', 'Bíblia Sagrada King James Atualizada | Letra Gigante | Capa Dura | Retro', 'Bíblia King James Atualizada Letra Hipergigante - Capa DuraTradicional e histórica, a Bíblia King James, possui essas além de muitas outras qualidades. Essa tradução da palavra de Deus tem a sua raiz na Inglaterra clássica, de William Shakespeare, mas também nos conflitos entre reis e igreja protestante e na intenção de dar ao povo a Bíblia em sua própria língua.O Rei James I era um amante da Palavra de Deus e via a necessidade do povo de conhecer a Palavra de Deus claramente, por esses motivos, ao receber o convite para auxiliar na tradução da Bíblia para a língua inglesa não hesitou, mas entregou-se de todo o coração. • Versão Atualizada | • Letra Gigante | • Tamanho: 14×21,5 cm 1152 Páginas', 44.9, 44.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rbk7-lotn5bmow4sm20', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22892672415', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497928792', 'L''Oréal Professionnel Serie Expert NutriOil - Creme Nutritivo Termoprotetor 150ml', 'L''Oréal Professionnel Serie Expert NutriOil - Creme Nutritivo Termoprotetor 150ml Leave-in para cabelos secos e ressecados. L''Oréal Professionnel Serie Expert NutriOil promove cabelos 4x mais macios, proteção térmica e efeito antifrizz por até 24 horas. O Leave-in L''Oréal Professionnel Serie Expert NutriOil é a solução ideal para cabelos mais nutridos e com muito mais brilho. Sua fórmula é enriquecida com óleo de coco e oferece textura leve e nutritiva para os fios. A proteção térmica atinge até 230ºC e o efeito antifrizz por até 24 horas. Conselho de Aplicação Sobre o cabelo úmido, distribua o leave-in uniformemente pelo comprimento e pontas. Não enxague e finalize como desejar.', 180.89, 180.89, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rdyb-m1d6mft2qbdk99', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F22497928792', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23199295902', 'Bepantriz Pomada 30g', 'Bepantriz Pomada 30g – Hidratação e Proteção para a Pele! A Bepantriz Pomada 30g é um poderoso aliado para a hidratação, regeneração e proteção da pele, sendo ideal para o tratamento de assaduras, queimaduras leves, irritações e ressecamento. Sua fórmula contém Dexpantenol (Pró-Vitamina B5), um ativo essencial que estimula a renovação celular, ajudando a pele a se recuperar rapidamente. Com textura suave e fácil de espalhar, a Bepantriz forma uma barreira protetora, evitando a perda de hidratação e prevenindo agressões externas. Indicada para todas as idades, pode ser usada tanto na pele do bebê, para prevenir assaduras, quanto por adultos para tratar pele ressecada, lábios rachados, áreas tatuadas e pequenos ferimentos. Se você procura uma pomada versátil, confiável e eficiente para cuidar da saúde da pele, a Bepantriz Pomada 30g é a escolha perfeita! ✔ Benefícios da Bepantriz Pomada: ✔ Hidrata profundamente, prevenindo o ressecamento. ✔ Acelera a regeneração da pele, promovendo rápida recuperação. ✔ Forma uma barreira protetora, prevenindo irritações e agressões externas. ✔ Ideal para bebês, adultos e idosos, oferecendo cuidados completos. ✔ Fórmula com Dexpantenol, essencial para a renovação celular. 🩹 Indicações de Uso: Prevenção e tratamento de assaduras em bebês. Hidratação intensa para áreas ressecadas, como cotovelos, joelhos e pés. Alívio para lábios rachados e irritações na pele. Cuidado pós-tatuagem, ajudando na cicatrização e hidratação. Proteção contra agressões externas, como frio, vento e atrito. 🛑 Contraindicações e Precauções: Uso externo. Evite contato com os olhos e mucosas. Não utilizar em feridas abertas sem orientação médica. Em caso de reação alérgica, suspenda o uso e procure um médico. Consulte um profissional de saúde antes de usar em casos de pele sensível ou lesões graves.', 9.99, 8.99, NULL, 'Mom & Baby > Baby Healthcare > Baby Skincare', 'https://cf.shopee.com.br/file/sg-11134201-82611-mjsmym8bif4696', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F23199295902', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398525401', 'Payot Retinol Cor 10 - Base Líquida 35ml', 'Payot Retinol Cor 10 - Base Líquida 35ml Base líquida de média cobertura para todos os tipos de pele trata o rosto, enquanto a deixa uniformizado. permite a construção de camadas, sendo capaz de disfarçar os poros e as irregularidades da sua pele, deixando um incrível acabamento natural. Além disso, sua fórmula com Retinol Vegetal auxilia na prevenção do envelhecimento precoce, devolvendo viço à pele e proporcionando maciez. Conselho de Aplicação Espalhe uma pequena quantidade pelo rosto com a ajuda de um pincel ou esponja.', 237.4, 134.9, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/sg-11134201-7ratr-ma44vak8glim5d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F23398525401', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
