INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693348039', 'Camisa Umbro Twr Striker Preta', 'A camisa preta modelo Twr Striker, fabricada pela Umbro, é a pedida certa para utilizar como fardamento do seu time de futebol ou durante as atividades físicas. Produzida em poliéster leve e respirável, ela pode ser personalizada com nome e número. Com caimento regular, seu design é inteiramente preto e possui o logo da marca fornecedora visto no tórax, bordado em branco. INFORMAÇÕES TÉCNICAS Composição: 100% Poliéster Bolso: Não Gola: Careca Logo: Bordado Manga: Curta Dimensões aproximadas (A x L): P: 72 x 48 cm M: 74 x 50 cm G: 76 x 52 cm GG: 80 x 54 cm', 113.9, 113.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Jerseys', 'https://cf.shopee.com.br/file/sg-11134201-7rdyi-m0lo4dorrvcq36', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1337527569%2F23693348039', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098527121', 'Cabo de Rede Rj45 Ugreen Cat7 F/FTP Macho 2 Metros Preto', 'Cabo Rede RJ45 Ugreen Cat7 F/FTP Macho 2M Preto Alta Velocidade Conexão Estável Internet Segura Transferência Dados Rápida Ideal Para Jogos Online Streaming HD 1. Conexão de Alta Velocidade: Experimente uma navegação mais rápida e eficiente com o Cabo de Rede RJ45 Ugreen Cat7. Ideal para atividades que exigem alta velocidade de transmissão, como jogos online e streaming de vídeos em HD. 2. Design Robusto e Flexível: Com 2 metros de comprimento, este cabo oferece grande flexibilidade para configurar seu espaço de trabalho ou entretenimento. Sua construção robusta garante uma conexão segura e confiável a longo prazo. 3. Transmissão de Dados Estável: Evite interrupções e lentidão na sua conexão com a tecnologia F/FTP do Cabo Ugreen. Este design avançado minimiza interferências, proporcionando uma transmissão de dados mais estável e segura. 4. Conexão Segura e Eficiente: O Cabo RJ45 Cat7 é a escolha ideal para quem busca uma conexão de rede sem riscos de falhas ou interferências. Desfrute de uma experiência online ininterrupta, seja para trabalho ou lazer. 5. Versatilidade de Uso: Compatível com uma variedade de dispositivos, este cabo é perfeito para diferentes usos, desde setups domésticos até ambientes corporativos, oferecendo sempre a melhor experiência de rede. Garantia de 90 dias.', 54.69, 54.69, NULL, 'Computers & Accessories > Network Components > Network Cables & Connectors', 'https://cf.shopee.com.br/file/br-11134275-7r98o-ma1mabn4280227', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1163359442%2F23098527121', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
