INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498685987', 'Caixa de Pesca Balde Porta Isca 72 Divisórias DYX609-BK - Daiyama', 'Caixa de Pesca DYX609-BK - Daiyama A Caixa de Pesca DYX609-BK da Daiyama é a escolha ideal para pescadores que priorizam eficiência e praticidade no transporte de seus acessórios. Com design moderno e funcional, ela combina estrutura robusta com um sistema de organização interna inteligente, tornando cada pescaria mais produtiva e bem planejada. Seu interior conta com uma divisória amarela removível e compartimentos bem distribuídos, oferecendo espaço suficiente para armazenar anzóis, iscas artificiais, chumbadas, linhas e demais itens essenciais de forma ordenada. Essa configuração facilita o acesso rápido aos equipamentos, economizando tempo durante a ação de pesca. Produzida com material resistente à água, a DYX609-BK protege seus pertences mesmo em ambientes úmidos, como rios, lagos ou regiões costeiras. Seu fechamento seguro mantém tudo protegido contra impactos, respingos e sujeira. Compacta e leve, ela é fácil de transportar e se encaixa perfeitamente em mochilas ou caixas maiores. Ideal para pescadores que buscam performance sem abrir mão de estilo, a DYX609-BK apresenta um visual discreto e elegante com acabamento preto e interior amarelo vibrante. Uma solução durável, prática e essencial para quem valoriza organização e qualidade em cada jornada de pesca. Especificações Marca: Daiyama Modelo: DYX609-BK Cores: Preto com divisória interna amarela Material: Plástico resistente à água Divisória interna: Removível, com múltiplos compartimentos Indicação: Armazenamento e transporte de acessórios de pesca Dimensões: 24,5 x 20,7 x 13,5cm Peso: 616g', 119.9, 119.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fishing', 'https://cf.shopee.com.br/file/sg-11134201-7ra15-mbi7cbxjh6aia7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F567374315%2F22498685987', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298979039', 'Multimídia Honda City 2008 A 2014 2ram+64gb Carplay Android Gps Bluetooth 10 Polegadas', 'Central Multimídia Android SOAUDIO 10 Polegadas – Modelo S1064B Sobre Nós Desde 2007, somos especialistas em centrais multimídia automotivas, oferecendo produtos modernos, confiáveis e com o melhor custo-benefício. Diferenciais: - Garantia de 12 meses - Suporte técnico especializado - Atendimento rápido e personalizado - Produto de altíssima qualidade, testado e garantido. Especificações Técnicas - Tela: IPS 10” 1280x720dpi (toque capacitivo duplo vidro) - Android: 15.0 - Memória: 2GB RAM / 64GB Flash - Processador: Quad Core RK3326 1.5GHz - Bluetooth: 5.0 (50 Mbps) - Wi-Fi: Dual Band 2.4G / 5.0G - Som: 4x41W com DSP e Sub EQ - Compatível com: CarPlay e Android Auto sem fio Aplicativos Instalados GPS IGO 3D offline, Waze, Netflix, Spotify, YouTube, Google Maps, Chrome e Play Store. Funções Principais - Interface personalizável: opções de layout - Logo da montadora ajustável - Câmeras compatíveis: 480p e 720p - Multitela: Divisão de tela para múltiplos apps - Bluetooth Hands-Free: Ligações e música - Ajuste de iluminação automática - Reprodução multimídia: MP3, MP4, AVI, MKV e mais - Rádio FM: Frequência 76–108 MHz - Wi-Fi com antena integrada Conteúdo da Embalagem • Central Multimídia 10” • Moldura do painel • Chicote plug and play • Câmera de ré + cabo • Antena GPS • Cabos USB e RCA • Microfone Bluetooth Suporte técnico pós-venda incluso.', 1092.3, 961.23, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/br-11134207-820lb-mqdh1diren7l3a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1613233738%2F23298979039', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
