INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200297224', 'Grill Philco 2 Em 1 PGR32 Chapa Com Abertura 180° - 220V', 'Grill Philco 2 Em 1 PGR32 Chapa Com Abertura 180° 220VTá a fim de um lanche feito de forma rápida e prática? Tenha a Grill Philco PGR32 a sua disposição a qualquer momento do dia! 2 em 1, a Grill Philco PGR32 é muito versátil e pode ser utilizada tanto como grill, quanto como sanduicheira. Com ela, você pode preparar carnes, peixes, vegetais, pães, hambúrguer e muito mais. Desenvolvida com chapa estendida 180°, facilita ainda mais na hora do preparo e grelha os dois lados por igual e ao mesmo tempo. Além disso, as placas com ajuste de altura, proporciona mais facilidade no preparo de alimentos com espessuras . Já o Revestimento Maxx Clean da Grill Philco, garante um antiaderente 4x mais resistente e fácil de limpar. Ou seja, prepare suas receitas sem precisar adicionar óleo e tenha pratos muito mais saudáveis e saborosos! Por acompanhar coletor de gordura com capacidade para 150ml, permite preparar seus alimentos sem sujeiras e muito mais saudáveis. Grill Philco PGR32, prática e compacta! Principais Características - Chapa com abertura de 180° - Acompanha coletor de gordura – capacidade para 150ml - Coletor de gordura com encaixe tipo gaveta - Luz indicadora de funcionamento - Luz indicadora de aquecimento - Placas com revestimento com antiaderente - Tamanho da Placa: 27cm x 17 cm - Placas de aquecimento com ajuste de altura - Base antiderrapante - Composição: plástico e metal. Observação: Somente faturamos para o nosso consumidor final, ou seja, não faturamos pedidos para CNPJ por este portal de vendas. Especificações Técnicas Marca: Philco Modelo: PGR32 Cor: Prata Estado: Potência: 1250W (127V) | 1500W (220V) Altura do produto: 11 cm Largura do produto: 31,5 cm Comprimento do produto: 25 cm Peso do produto: 1,7 kg Altura com embalagem: 28 cm Largura com embalagem: 34 cm Comprimento com embalagem: 14 cm Peso com embalagem: 1,95 kg Garantia: 360 Dias', 197.9, 178.11, NULL, 'Home Appliances > Kitchen Appliances > Toasters', 'https://cf.shopee.com.br/file/sg-11134201-7rdyn-mcjizr7hen2s84', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1617519379%2F58200297224', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23797923664', 'Kit 2 Chocolates Culinários Ao Leite e Dark Linea 250g', 'Linea Chocolate Culinário é fácil de derreter, ideal para raspas, recheios e coberturas. Com muito sabor, sem adição de açúcares, é adoçado com sucralose e maltitol. Baixo em sódio, não contém glúten. O chocolate para quem gosta de preparar suas receitas com facilidade! 1 Kit Composto por: - Chocolate Culinário Ao Leite Linea 250g - 1 unidade - Chocolate Culinário Dark Linea 250g - 1 unidade INGREDIENTES CHOCOLATE AO LEITE manteiga de cacau, maltodextrina, leite em pó integral, massa de cacau, gordura vegetal, soro de leite desmineralizado, edulcorantes: maltitol e sucralose, emulsificantes: lecitina de soja e poliglicerol polirricinoleato e aromatizante. ALÉRGICOS: CONTÉM DERIVADOS DE LEITE E SOJA. CONTÉM LACTOSE. NÃO CONTÉM GLÚTEN. INGREDIENTES CHOCOLATE DARK massa de cacau, manteiga de cacau, gordura vegetal, edulcorantes: maltitol e sucralose, emulsificantes: lecitina de soja e poliglicerol polirricinoleato e aromatizante. ALÉRGICOS: CONTÉM DERIVADOS DE SOJA. PODE CONTER LEITE. NÃO CONTÉM GLÚTEN.', 129.58, 116.62, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/sg-11134201-7rdyn-m1d439orpritd8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1365822827%2F23797923664', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
