INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19497998758', 'Escada de fibra de vidro extensível 3,8 x 6,5 m - Rotterman', 'Produto: Escada de fibra de vidro extensível 3,8 x 6,5 m 21 degraus - Premium Marca: Rotterman Descrição: A Escada de fibra de vidro extensível 3,8 x 6,5 m 21 degraus premium Rotterman é a escolha ideal para quem busca segurança, resistência e praticidade em trabalhos comerciais, industriais e domésticos. Desenvolvida com materiais de alta qualidade, esta escada extensível de fibra de vidro oferece excelente desempenho em atividades que exigem estabilidade, durabilidade e proteção, especialmente em ambientes onde é essencial utilizar uma escada não condutora de eletricidade. Seu sistema com parte fixa e extensível permite ajuste de altura por meio de corda em poliéster de 8 mm, roldana de nylon e catraca de alumínio com travamento seguro, garantindo operação fácil e eficiente. Os montantes em perfil “U” enrijecido, produzidos por pultrusão com resina e manta de fibra de vidro, proporcionam alto isolamento, resistência mecânica e proteção contra corrosão química. • Segurança reforçada para diferentes aplicações: por ser isolante elétrico e indicada para uso em baixa tensão, esta escada de fibra de vidro é ideal para profissionais de manutenção, instalações e serviços gerais que precisam de mais confiança durante o trabalho. • Estrutura durável e resistente: conta com alta resistência Ã água, ação química e ferrugem, sendo uma excelente opção para quem procura uma escada premium de longa vida útil e ótimo custo-benefício. • Conforto e estabilidade no uso: os degraus em formato “D”, fabricados em duralumínio com ranhuras antiderrapantes, oferecem apoio mais confortável aos pés, enquanto as sapatas em polipropileno ajudam a evitar deslizamentos no solo. • Praticidade e manutenção facilitada: além de ser mais leve que muitas escadas profissionais, permite manutenção dos acessórios, prolongando sua eficiência e reduzindo custos ao longo do tempo. Invista na Escada premium Rotterman e tenha mais desempenho, segurança e versatilidade em qualquer rotina de trabalho. Especificações: Capacidade de carga: 120 kg Escada fechada: 13 degraus - 3,8 m Escada estendida: 21 degraus - 6,50 m Material da escada: fibra de vidro Material do degraus e catracas: alumínio. Itens Inclusos: Cinto de apoio. Peso: 15.00 Kg', 1092.02, 875.9, NULL, 'Home & Living > Tools & Home Improvement > Ladders', 'https://cf.shopee.com.br/file/sg-11134201-8259i-mqlsddxt4zy8f7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F19497998758', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209669347', 'Ketchup Hellmann''s Tradicional', 'O Ketchup Hellmann''s Tradicional é feito com tomates selecionados de fazendas sustentáveis, garantindo um sabor único e irresistível para seus pratos. Use o Ketchup Hellmann''s para deixar seus sanduíches, batatas fritas, molhos, hambúrgueres e recheios ainda mais gostosos. Experimente adicionar sabor e cor incomparáveis aos seus pratos com Hellmann''s!', 13.79, 13.79, NULL, 'Food & Beverages > Cooking Essentials > Seasonings & Condiments', 'https://cf.shopee.com.br/file/sg-11134201-823r0-moo4ig8863nl62', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554945%2F58209669347', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
