INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258417043', 'Protetor de Colchão Altenburg Solteiro King Malha Slim', 'O Protetor de Colchão Solteiro Impermeável Altenburg Malha Slim garante mais higiene, conforto e durabilidade para o seu colchão. Essencial para manter a limpeza por mais tempo, ele forma uma barreira eficaz contra líquidos, suor, ácaros e poeira, ajudando a prevenir alergias e proporcionando noites mais saudáveis. Seu tecido impermeável evita que líquidos penetrem no colchão, preservando sua estrutura e aumentando sua vida útil. Além disso, impede o acúmulo de ácaros, bactérias e sujeira, sendo ideal para quem sofre de alergias respiratórias. A malha 100% poliéster proporciona uma sensação suave ao toque, sem comprometer a maciez do colchão. Com elástico em toda a volta, o protetor se ajusta perfeitamente, facilitando a troca e a lavagem. Prático e higiênico, pode ser lavado na máquina, tornando o dia a dia mais fácil. Invista no cuidado e na durabilidade do seu colchão com o Protetor de Colchão Altenburg Malha Slim e tenha noites de sono mais tranquilas e saudáveis.', 139.0, 139.0, NULL, 'Home & Living > Bedding > Mattress Protectors & Toppers', 'https://cf.shopee.com.br/file/sg-11134201-81ztq-mmsu3xpbr37o0d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674300605%2F58258417043', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
