INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23599275045', 'Perfume Masculino Eau de Toilette Adidas UEFA 11 Goal - 100ml', 'Perfume Masculino Eau de Toilette Adidas UEFA 11 Goal - 100ml O perfume Adidas UEFA Champions League Edição Goal é um eau de toilette aromático verde, que possui uma fragrância refrescante e poderosa com um toque amadeirado e fresco. Com longa duração, sua fórmula é vegana e feita com materiais reciclados. Sobre a fragrância Conta com uma tecnologia patenteada que promove uma sensação de frescor prolongada durante o dia. Nas notas de topo temos abacaxi, laranja e cardamomo. Já nas notas de coração sálvia, lavanda e gerânio. Por fim, nas notas de fundo temos vetiver, cedro e patchouli. Adidas UEFA Goal, celebra o poder, a singularidade e o amor pelo jogo. Fragrância refrescante e poderosa com um toque amadeirado e fresco. Para uma aplicação perfeita: Borrife o perfume a uns 15 cm da pele, nas áreas quentes do corpo onde há maior circulação sanguínea, como pulso, dobras dos braços, nuca e pescoço. Como faço meu Adidas UEFA Champions League Goal durar mais? Tente aplicar logo após banho quando poros estão abertos, absorvendo melhor essências, além disso hidrate bem corpo, pois peles secas tendenciam dissipar rapidamente óleos presentes nos perfumes. A aplicação em locais quentes, com maior bombeamento sanguíneo ajudam na fixação eficaz. Especificações: Público: Masculino Concentração: Eau de Toilette - EDT Familia Olfativa: Amadeirado,Aromático Notas de Topo: Abacaxi, laranja e cardamomo Notas de Coração: Sálvia, lavanda e gerânio. Notas de Fundo: Vetiver, cedro e patchouli Intensidade: Leve / Moderada Tempo de Fixação: Médio Ocasião: Casual,Dia Sazonalidade: Verão,Primavera,Outono,Inverno', 160.88, 160.88, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-8261p-mjbgmbjhdz4147', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1331826475%2F23599275045', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
