INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20099600166', 'Tampa Caixa de Passagem 31x13cm Polar - TPP03', 'Tampa Caixa de Passagem 31x13cm Polar - TPP03 A Tampa Caixa de Passagem TPP03 é ideal para cobrir caixas de passagem de forma eficiente e segura. Fabricada com materiais de alta qualidade, ela garante durabilidade e resistência, suportando as condições do dia a dia com facilidade. Seu design discreto e funcional permite uma instalação prática, adaptando-se perfeitamente aos mais diversos ambientes, seja em residências ou estabelecimentos comerciais. Além de seu tamanho compacto, a tampa proporciona vedação eficaz, evitando a entrada de sujeira e oferecendo proteção contra umidade. Essa solução é perfeita para quem busca manter a organização e segurança dos cabos e tubulações, garantindo uma aparência limpa e profissional. A Polar se destaca pela confiabilidade e tecnologia, tornando a Tampa Caixa de Passagem uma escolha ideal para qualquer projeto.', 19.9, 19.9, NULL, 'Home Appliances > Electrical Circuitry & Parts > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdy3-mbsd1nkeni3a1f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F20099600166', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
