INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997829851', 'Buffet Classico com Adega Harbin Cedro', 'O Buffet é um produto para quem procura um design inovador garantindo a elegância do seu ambiente. Feito em MDP/MDF. Possui 4 portas em MDF usinados, adega q comporta 10 garrafas e 2 prateleiras internas, seus compartilhamentos internos são ideais para armazenar e organizar diversos tipos de objetos. Dimensão do Buffet: Altura: 79 cm Largura: 190 cm Profundidade: 38,5 cm Informações do Buffet: Cor: Cedro Portas: Sim (4) MDF Usinados Pés: Sim (4) Madeira maciça Prateleira: Sim (2) Nichos: Sim, Suporta 10 garrafas Gavetas: Não Material Principal: MDP/MDF Itens Inclusos: 1 Buffet Manual de Montagem Kit completo para montagem e manual de instruções Garantia: 3 meses contra defeito de fabricação Informações Adicionais: - Fotos meramente ilustrativas do produto no ambiente. - Os objetos que ambientam as fotos não acompanham o produto; - Verificar descrição e tamanho do produto antes da compra. - Avaliar a mercadoria no ato do recebimento e recuse em caso de divergência ou avarias. - Mantenha as informações de contato e endereço de entrega atualizados para entrarmos em contato caso necessário. - Limpar com flanela ou pano macio seco, não utilizar produtos abrasivos, desengordurantes, álcool ou solvente. Não expor o produto diretamente à luz solar e à umidade. * Sugerimos a contratação de um montador profissional para a montagem do produto. Não nos responsabilizamos por avarias causadas no ato da montagem. * Não nos responsabilizamos pela montagem e desmontagem do produto no ato da entrega e devolução, assim como os custos gerados nestas situações. * A transportadora entregará o produto no andar térreo do endereço de entrega. * Não nos responsabilizamos por subir escadas, corredores e elevadores ou transporte por guincho em apartamento', 1482.99, 1023.27, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7reoh-m82cumt6xfv504', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F451273707%2F23997829851', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22297575056', 'Kit 20 Refletores Led Elgin 100w Branco Frio 6500K Bivolt Econômico', 'ATENÇÃO!!! ⚠️⚠️DIMENSÕES APROXIMADAS: 15,4 X 13 X 2 ⚠️⚠️ O Refletor de Led Elgin tem uma boa abrangência e alcance luminoso, é ideal para iluminar ambientes externos e internos, sendo eficiente para locais residenciais como piscina, jardim, varanda, garagem, portão, fachada e também ambientes comerciais como festas, fachadas de loja, outdoors, entre outros. Ele é fabricado com materiais de alta qualidade, metal resistente para uso externo. Proporciona altos índices de luminosidade com baixo consumo de energia, pouca emissão de calor e longa durabilidade. Aprovado pelo Inmetro! ⚠️⚠️DIMENSÕES APROXIMADAS: 15,4 X 13 X 2 ⚠️⚠️ DADOS TÉCNICOS Potência: 100W Tensão: Bivolt ( Serve para 110 - 220v ) Frequência: 50/60 Hz Fluxo Luminoso: 8000lm Eficiência Luminosa: 80lm/ Vida Útil: 25.000h Ângulo de Abertura: 110° Quatidade de Led´s : 60 Led´s IRC : 80 IP : 66 Fator Potência : PF > 0.5 Alto poder de luminosidade LED de alta potência e refletor de alumínio garantem boa abrangência e alcance luminoso Baixo consumo de energia Não emite radiação ultravioleta ⚠️⚠️DIMENSÕES APROXIMADAS: 15,4 X 13 X 2 ⚠️⚠️ 1 Ano de garantia ( pelo fabricante ) E 90 dias com a loja Imagens Ilustrativas.', 1256.9, 699.9, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m4j48pnunosh01', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1257849357%2F22297575056', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
