INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20631160497', 'Jogo Chave Fenda e Phillips Tramontina 6 Pçs Profissional', 'Se você preza por um completar seu kit de ferramentas, precisa do Jogo de Chaves de Fenda Tramontina Yellow 6 Peças. Um jogo que traz chaves de fenda com ponta chata, ponta cruzada e ainda uma chave clipe, ideal para fixar em cintos e alças e que é um coringa na hora de apertar ou afrouxar parafusos. Todas as peças são muito resistentes: têm hastes produzidas em aço especial cromado e cabos em polipropileno injetado. Além disso, são altamente duráveis e vão levar muito mais praticidade na execução de suas tarefas. Garanta o seu e facilite o seu dia a dia! Especificações Técnicas: • As Hastes as Chaves de Fenda são Testadas em Máquinas de Ensaio Específicas, Para Verificar o Perfeito Balanço Entre Resistência Mecânica e Dureza. • Cabos Injetados Com Material de Alta Resistência. • Os Dimensionais das Pontas são Verificados Comgabaritos-Padrão, Calibrados e Certificados. • As Ferramentas São Produzidas e Testadas Conforme Normas Específicas. Conteúdo da Embalagem: • 01 Chave de fenda ponta chata 3/16x4" • 01 Chave de fenda ponta chata 1/4x4" • 01 Chave de fenda clipe 1/8x3" • 01 Chave de fenda ponta cruzada 1/8x3" • 01 Chave de fenda ponta cruzada 3/16x4" • 01 Chave de fenda ponta cruzada 1/4x4" • Manual e Certificado de Garantia Importante: • Garantia de 273 Dias. • Valor Kit.', 43.64, 41.02, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rd52-lu848gjxnzw711', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F463375702%2F20631160497', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
