INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259698423', 'Chambinho', 'O inconfundível Petit Suisse Chambinho® Morango é um produto lácteo cremoso com gostinho de infância. Fonte de cálcio, zinco e vitaminas A e D, nutrientes importantes para o crescimento e desenvolvimento das crianças. Cada bandeja contém 8 potinhos de 40g, perfeitos para lanches rápidos, levar para a escola ou como sobremesa após as refeições.', 9.79, 9.79, NULL, 'Food & Beverages > Beverages > Dessert Drink', 'https://cf.shopee.com.br/file/sg-11134201-825av-mqnelhpna617ba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555175%2F58259698423', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
