INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397721120', 'Kit 2 und Umidificador Multi Saúde Easy Air 2,6l', 'O umidificador de ar Easy Air da Multi Saúde é um aparelho projetado para melhorar a qualidade do ar em ambientes secos. Do tipo portátil, ele tem 2,6L de capacidade, é compatível com óleos essenciais, possui baixa emissão de ruídos, desligamento automático e névoa ajustável. Ele opera continuamente e silenciosamente por um período de 10 a 42 horas, proporcionando umidade adequada para reduzir problemas respiratórios, como tosses secas, congestões nasais e desconfortos relacionados. E para melhor conservação, ele deve ser colocado numa superfície dura e plana, sem qualquer obstrução por baixo como tapetes ou toalhas. E não coloque-o em áreas próximas a computadores e equipamentos sensíveis.', 406.79, 317.0, NULL, 'Home & Living > Home Fragrance & Aromatherapy > Diffusers, Humidifiers & Oil Burners', 'https://cf.shopee.com.br/file/sg-11134201-7rdw2-lywpbi4nqu2fab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F22397721120', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998041393', 'Batalhas da Bíblia | Chaim Herzog', 'Narrado com detalhes claros, a explicação militar da Bíblia percorre um grande período – desde a invasão de Canaã pelos israelitas sobre o comando de Jósu é até a conquista do reino por Davi e Salomão, entre outras. Tais batalhas são fundamentais para o entendimento dos eventos da época, quando a luta por independência e sobrevivência ofuscavam todos os outros aspectos da vida diária. O livro Batalhas da Bíblia é uma obra fascinante e valiosa – não apenas pela sua análise detalhada dos relatos bíblicos, mas também por contínua relevância – que leva em consideração pesquisas históricas e arqueológicas atuais, assim como tendências modernas em conhecimento. Batalhas da Bíblia é, sem dúvida, um instrumento fundamental para a compreensão do milenar conflito que subsiste na Terra Santa, e para o entendimento das origens da nossa civilização. 16x23cm 336 Páginas', 30.9, 29.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7req3-m2xd5smt0y61a8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22998041393', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898860065', 'Box com 6 unidades | Minha Primeira Aventura Encantada | La Fadine', 'Os pequenos vão adorar conhecer o universoencantado de La Fadinne, com estes seis livros cartonados belamente ilustrados 19x23cm 10 Paginas', 27.9, 21.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-824j8-me2sozxbt5hi2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22898860065', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18797233167', 'Tempo de Perdão, Tempo de Cura | Charles Spurgeon', 'O Evangelho de Jesus nos promete uma transformação geral em nossa vida, em outras palavras, o Evangelho nos promete perdão espiritual e curas ficas e emocionais. A obra Tempo de Perdão, Tempo de Cura de Charles Spurgeon, traz átona todas essas verdade da Escritura, nos mostrando que além de nós perdoar, Deus quer nos incentivar a perdoar os outros, pois quem muito foi perdoado muito ama. 14x21cm 112 Páginas', 21.9, 21.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7qvec-lk0dr1c7o16t7a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F18797233167', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
