INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098937926', 'Babuche Infantil EVA Corações Pampili', 'Leveza e Estilo para o Dia a Dia! A babuche é perfeita para quem busca conforto e praticidade com um toque de estilo! Produzida com palmilha e solado em EVA, garante maciez, leveza e um ajuste perfeito para acompanhar as meninas em todas as aventuras. A correia traseira ajustável, decorada com corações coloridos em 3D, proporciona um ajuste seguro e charmoso, além de permitir um calce fácil. O cabedal injetado em PVC livre de ftalato traz mais segurança e um visual único. O solado texturizado antiderrapante garante firmeza e estabilidade, tornando essa babuche a opção ideal para o dia a dia. Além disso, sua limpeza é super fácil, garantindo praticidade extra para a rotina!', 159.99, 119.99, NULL, 'Baby & Kids Fashion > Girl Shoes > Others', 'https://cf.shopee.com.br/file/sg-11134201-824je-met4hfk2t6h0a6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1547100334%2F22098937926', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
