INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16285793610', 'Balanço Infantil Borboletinha Com Encosto Regulável até 23Kg Com Cinto de segurança Xalingo - 09356', 'As crianças podem se divertir no embalo do Balanço Infantil 3 em 1 Borboletinha da Xalingo Brinquedos. Inspirado nas Borboletas, diverte e desenvolve o equilíbrio e a coordenação motora. O balanço Infantil 3 em 1 injetado acompanha o crescimento da criança, porque contém cinto de segurança, e pode ser usado com ou sem encosto e barra de proteção. O encosto é regulável e acompanha cordas em plástico. Indicado para crianças de 19 a 36 meses. É diversão que não acaba mais! ATENÇÃO: Este modelo não acompanha gancho para prender, apenas as cordinhas. Características: - Marca: Xalingo - Modelo: 09356 *Imagens Meramente Ilustrativas Especificações Técnicas: - Idade: 1-2 anos, 3-4 anos - Inmetro: CE-BRI/IQB 005923 - Aviso: O cinto de segurança deve ser afivelado e ajustado à criança - Este brinquedo deve ter a supervisão de um adulto durante o uso. - Dimensões Aproximadas (AxLxC): 38,7x30,9x40,5 cm - Idade Recomendada: de 19 a 36 meses - Itens Inclusos: Cinto de Segurança - Peso Máximo Recomendado: 23Kg Conteúdo da Embalagem: - 1x Balanço Infantil Borboletinha', 174.26, 156.84, NULL, 'Mom & Baby > Nursery > Bouncers, Rockers & Jumpers', 'https://cf.shopee.com.br/file/sg-11134201-7qvfr-lf5kqm9zzlzc82', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F16285793610', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
